/**
 * Shared label-content builder for both SVG renderers (straight + ring), so the two-line
 * label option renders identically in either rail mode.
 */

import type { HangingStringCategory } from "../../core/types";

const SVG_NS = "http://www.w3.org/2000/svg";

/**
 * Fills a string's `<text>` label: single line (name only), or — when `twoLine` — the category
 * name on line 1 and "(value)" on line 2 via tspans. `x` must match the text element's own x
 * so the second line left-aligns with the first (tspans don't inherit x, only the flow
 * position), including inside rotated root labels, where "below" means along the tilted
 * baseline.
 */
export function setLabelContent(
  label: SVGTextElement,
  category: HangingStringCategory,
  twoLine: boolean,
  x: number
) {
  // Skip DOM rebuild when name/value/mode/x are unchanged (full render runs often during drag).
  const sig = `${twoLine ? 1 : 0}\0${category.name}\0${category.value}\0${x}`;
  if (label.dataset.labelSig === sig) return;
  label.dataset.labelSig = sig;

  if (!twoLine) {
    label.textContent = category.name;
    return;
  }
  label.textContent = "";
  const line1 = document.createElementNS(SVG_NS, "tspan");
  line1.textContent = category.name;
  const line2 = document.createElementNS(SVG_NS, "tspan");
  line2.setAttribute("class", "hsd-label-value");
  line2.setAttribute("x", String(x));
  line2.setAttribute("dy", "1.15em");
  line2.textContent = `(${category.value})`;
  label.append(line1, line2);
}
