/**
 * v2 hierarchy layout for ring mode (D16 extended, Q11): the same "sub-rail from a knob"
 * mechanism straight mode uses (core/hierarchy.ts), mapped onto the perspective ring. Pure
 * layout math, no DOM — mirrors the straight version's separation of concerns and reuses
 * computeRingLayout verbatim for the root level.
 *
 * How the branch inherits the ring's fake-3D (D3): the whole branch lives at the PARENT's depth
 * — children start from the parent's depthT/scale/opacity rather than deriving their own from
 * anchorY (their anchors sit far below the ellipse, where the depth formula is meaningless).
 * D16.1 composes a LOCAL depth on top: the sub-rail is itself a miniature ring, and a child's
 * angle around it contributes its own scale/opacity multiplier (see `localScale`). Child
 * `dropPx` stays pure value math on the ROOT scale (D1 absolute across levels, same as straight
 * mode); only the rendered pixels are foreshortened by the parent's cosmetic depth scale,
 * exactly the compromise ring mode already makes for root strings.
 *
 * Geometry is intentionally parent-RELATIVE where it matters: `slotOffsetX` (unscaled) and the
 * sub-rail's `halfSpanPx`/`gapPx` (unscaled) let the renderer re-derive everything from the
 * parent's live, animated knob every frame — the branch must hang from the parent string as it
 * slides around the arc or is dragged, not float at its resting slot (same attachment semantics
 * the user asked for in straight mode). The at-rest anchors computed here only seed animation
 * targets and hit-area sizing.
 */

import type { HangingStringCategory } from "./types";
import {
  computeRingLayout,
  type RingConfig,
  type RingLayoutResult,
  type RingStringLayout,
  type RingSubRailLayout,
} from "./ringLayout";
import { linearScale, ticksBelow } from "./scale";

/** D16.1: children START spread over this arc of their mini ring (degrees, centered on its
 * front). Kept below 180° so the initial spread sits fully on the readable front arc; sliding a
 * child (D17-for-children) or spinning the branch (D19) can take it anywhere on the ring. */
const SUB_RING_ARC_DEG = 160;

export interface RingHierarchyConfig extends RingConfig {
  /** Vertical gap between a parent's knob and its children's sub-rail, unscaled px — same role
   * (and same default, via DEFAULT_HIERARCHY_EXTRAS) as HierarchyConfig.subRailGapPx. */
  subRailGapPx: number;
  /** Horizontal slot width between adjacent child strings, unscaled px. */
  childGapPx: number;
  /** Extra sub-rail length beyond the outermost child anchors, per side, unscaled px. */
  subRailPadPx: number;
  /** Child knob radius as a fraction of knobMinRadiusPx (uniform beads, like straight mode). */
  childKnobFactor: number;
}

/**
 * Root layout via computeRingLayout, plus — for every root in `expandedIds` that has children —
 * a sub-rail hanging below that parent's knob with the children on it. Children are spliced into
 * the back-to-front array immediately AFTER their parent so they paint just in front of it
 * (they share its depth; stable order keeps the branch visually on top of its own trunk).
 */
export function computeRingHierarchyLayout(
  categories: HangingStringCategory[],
  order: string[],
  childOrders: ReadonlyMap<string, string[]>,
  expandedIds: ReadonlySet<string>,
  config: RingHierarchyConfig,
  /** D17: per-string base-angle overrides for slid roots (see computeRingLayout) — children
   * always hang from their parent's knob, so they follow a slid parent automatically. */
  angles?: ReadonlyMap<string, number>,
  /** D19: per-parent spin offsets (degrees) for the mini rings — each expanded branch's disc
   * can be rotated independently, exactly like the main ring's `rotationOffsetDeg`. Children of
   * a spun branch travel around their mini ring, including onto its back arc. */
  subRotations?: ReadonlyMap<string, number>,
  /** D17-for-children: per-child BASE-angle overrides (degrees, before the branch's rotation
   * offset) for children the user has slid around their mini ring — same free-position contract
   * as `angles` for roots: a slid child stays exactly where it was dropped, nobody else moves.
   * Children without an entry keep their even-spread slot. */
  childAngles?: ReadonlyMap<string, number>
): RingLayoutResult {
  const root = computeRingLayout(categories, order, config, angles);
  const strings: RingStringLayout[] = [...root.strings];
  const subRails: RingSubRailLayout[] = [];

  // Absolute scale (D1 across levels): identical px-per-value mapping and bead-tick values as
  // the root level — see core/hierarchy.ts, this is the same rule in the second mode.
  const dropScale = linearScale([0, root.maxValue], [0, config.maxDropPx]);
  const tickValues = ticksBelow(root.maxValue, root.tickStepValue);
  const childKnobRadius = config.knobMinRadiusPx * config.childKnobFactor;

  for (const parent of root.strings) {
    const children = parent.category.children;
    if (!expandedIds.has(parent.category.id) || !children?.length) continue;

    const byId = new Map(children.map((c) => [c.id, c]));
    const orderedIds = childOrders.get(parent.category.id) ?? children.map((c) => c.id);
    const ordered = orderedIds
      .map((id) => byId.get(id))
      .filter((c): c is HangingStringCategory => Boolean(c));
    const n = ordered.length;

    // D16.1: the sub-rail is a miniature ring — an ellipse sized like the old straight rail's
    // half-span, squashed by the SAME radiusY/radiusX ratio as the main rail so both rings read
    // as discs seen from one camera. Its center hangs gapPx + radiusY below the parent's knob
    // (top rim gapPx below the knob, where the straight rod used to sit).
    const subRx = ((n - 1) / 2) * config.childGapPx + config.subRailPadPx;
    const squash = config.radiusX > 0 ? config.radiusY / config.radiusX : 0;
    const subRy = subRx * squash;
    const rotationDeg = subRotations?.get(parent.category.id) ?? 0;

    const childEntries: RingStringLayout[] = ordered.map((child, i) => {
      // Even spread over the mini ring's front arc, left to right — same convention as roots on
      // the main ring (angle 0 = front center), just over a narrower arc. A child the user has
      // slid (D17-for-children) keeps exactly its dropped base angle instead. D19's per-branch
      // spin offset applies on top and can carry a child around to the back arc.
      const t = n <= 1 ? 0.5 : i / (n - 1);
      const baseAngleDeg =
        childAngles?.get(child.id) ?? -SUB_RING_ARC_DEG / 2 + t * SUB_RING_ARC_DEG;
      const localAngleDeg = baseAngleDeg + rotationDeg;
      const slotAngleRad = (localAngleDeg * Math.PI) / 180;
      // Slot point ON the sub-ring ellipse, unscaled px from the parent's knob (same
      // sin-for-X / cos-for-Y projection as pointOnRailEllipse).
      const slotOffsetX = subRx * Math.sin(slotAngleRad);
      const slotOffsetY = config.subRailGapPx + subRy + subRy * Math.cos(slotAngleRad);
      // The child's own depth around its mini ring, as multipliers on the parent's depth: 1 at
      // the mini ring's front, the config's back/front ratio at its back — the same falloff
      // rule the main ring applies to roots, composed one level down.
      const localDepthT = (1 - Math.cos(slotAngleRad)) / 2;
      const localScale =
        1 - localDepthT * (1 - (config.maxScale > 0 ? config.minScale / config.maxScale : 1));
      const localOpacity =
        1 - localDepthT * (1 - (config.maxOpacity > 0 ? config.minOpacity / config.maxOpacity : 1));
      const dropPx = dropScale(child.value);
      const ticks = tickValues
        .filter((v) => v < child.value)
        .map((v) => ({ value: v, y: dropScale(v) }));
      return {
        category: child,
        angleDeg: parent.angleDeg,
        anchorX: parent.anchorX + slotOffsetX * parent.scale,
        anchorY: parent.anchorY + (parent.dropPx + slotOffsetY) * parent.scale,
        depthT: parent.depthT,
        scale: parent.scale * localScale,
        opacity: parent.opacity * localOpacity,
        dropPx,
        knobRadius: childKnobRadius,
        ticks,
        parentId: parent.category.id,
        slotOffsetX,
        slotOffsetY,
        localAngleDeg,
        localScale,
        localOpacity,
      };
    });

    // Splice right after the parent: the branch paints just in front of its trunk. Within the
    // branch, deepest-around-the-mini-ring first (stable), so a child spun to the back arc
    // (D19) is correctly occluded by its front siblings — the same painter's convention the
    // root level gets from its depthT sort.
    childEntries.sort((a, b) => a.localScale! - b.localScale!);
    strings.splice(strings.indexOf(parent) + 1, 0, ...childEntries);

    subRails.push({
      parentId: parent.category.id,
      radiusX: subRx,
      radiusY: subRy,
      gapPx: config.subRailGapPx,
      rotationDeg,
    });
  }

  // At-rest estimate of the lowest BRANCH content (child strings hang below the parent's knob
  // and can reach past the base canvas height near the front of the ring). Only children count:
  // roots fit the base canvas by design, and including them (with the safety margins below, which
  // cover the renderer-level hanger offset and knob radius) would inflate the collapsed height.
  const childStrings = strings.filter((s) => s.parentId);
  const contentHeight =
    childStrings.length > 0
      ? Math.max(...childStrings.map((s) => s.anchorY + (s.dropPx + s.knobRadius + 20) * s.scale)) +
        16
      : 0;

  return { ...root, strings, subRails, contentHeight };
}
