/**
 * First reference renderer (SVG) — the PLANAR rail family (straight, and since M2 any curved
 * PlanarRailForm such as the arc; wiki/design/rail-forms.md). Consumes core/layout.ts output;
 * contains all DOM/SVG-specific code so the core stays reusable by other renderers (Canvas,
 * React, D3 — see implementation plan).
 *
 * D20 (2026-07-14): dragging a string slides it POSITIONALLY along its rail — the planar
 * mirror of ring mode's D17, arc length instead of angle. It stays exactly where dropped and
 * no other string moves; slot reorder and the slide-to-compare preview are retired. The rail's
 * form supplies both directions of the mapping (anchorAt / alongAtX), so the same drag code
 * serves the straight rod and any curved planar rod.
 */

import type { HangingStringGroup, HangingStringCategory } from "../../core/types";
import type { LayoutResult, StringLayout } from "../../core/layout";
import { STUDIO_THEME, type HangingStringsDiagramTheme } from "../../core/theme";
import { createFillDef, createThreadPaintSource, type ThreadPaintSource, CAST_SHADOW_TRANSFORM } from "./theme";
import { nextInstanceUid } from "./uid";
import type { StringHoverEvent } from "./hover";
import { breezeSignal, threadWindAccel } from "./backdrop";
import { heatmapColor, linearScale } from "../../core/scale";
import { setLabelContent } from "./labels";
import { setAttrIfChanged } from "./domAttr";
import { DEFAULT_QUIPU_CONFIG, computeQuipuLayout } from "../../core/quipu";
import { buildQuipuLayer, type QuipuGlyphEl } from "./quipuGlyphs";
import {
  N_NODES,
  chainParamsForStiffness,
  clamp,
  morphAnchorEaseRate,
  createChainAnim,
  smoothPathThroughPoints,
  stepChainAnim,
  xAlongPolyline,
  type Point,
  type StringChainAnim,
} from "../../core/chain";
import { expandHitRadius, lowerEndHitGeometry } from "./stringHit";

const SVG_NS = "http://www.w3.org/2000/svg";

/** Above this string count, permanently disable per-thread/label drop-shadows (CSS .hsd-dense). */
const DENSE_STRING_THRESHOLD = 40;

// D10: flexible-string "shock absorber" micro-interaction — physics lives in core/chain.ts
// (shared with ring mode, see renderRing.ts) so both rail modes feel identical. The planar
// renderer's own contribution is just: the anchor's target Y never moves with the swing.

/** D13 hanger rings on EVERY rail form (user, 2026-07-15 — previously ring-mode-only): the
 * same curtain-hanger hardware — a small vertically-elongated loop at each string's anchor,
 * with the thread hanging from its BOTTOM edge rather than sprouting out of the rod. Same
 * geometry as renderRing.ts. */
const HANGER_RING_RX = 3.5;
const HANGER_RING_RY = 7;
const HANGER_DROP_OFFSET = HANGER_RING_RY;

/** D20 keyboard parity: one arrow press slides the string this many px along its rail — the
 * planar counterpart of ring mode's ±5° nudge. */
const ARROW_NUDGE_PX = 12;

/** D20: a slid child stops this short of the sub-rail bar's ends, so the hanger never sits on
 * the very tip of the rod. */
const SUBRAIL_END_PAD_PX = 4;

type StringAnim = StringChainAnim;

/** Element refs cached at creation time so neither `render()` nor the per-frame animation loop
 * ever has to `querySelector` back into the subtree it just built. */
interface StringEls {
  g: SVGGElement;
  /** D13 hanger ring at the anchor — lives in `hangerLayer` (under the rod), not in `g`. */
  hanger: SVGEllipseElement;
  /** D11.1 cast shadows: offset same-geometry copies of the thread and knob, thrown onto
   * whatever hangs behind (the breeze sheet above all). First children of the hang group so
   * everything real paints over them. */
  castThread: SVGPathElement;
  castKnob: SVGCircleElement;
  thread: SVGPathElement;
  ticksLayer: SVGGElement;
  /** The bead-ticks' y positions, mirrored into JS so the per-frame loop never reads attributes. */
  tickYs: number[];
  /** Cheap identity of the currently-built bead-ticks, to skip DOM rebuilds when unchanged. */
  tickSig: string;
  /** D28: the quipu knot layer (2nd metric as khipu numbers) + its glyph groups for the
   * per-frame sway-follow, and the rebuild signature — same pattern as the bead-ticks. */
  quipuLayer: SVGGElement;
  quipuEls: QuipuGlyphEl[];
  quipuSig: string;
  shadow: SVGEllipseElement;
  knob: SVGCircleElement;
  /** D16 branch affordance: a +/− glyph drawn on the knob of a string that has children. */
  glyph: SVGTextElement;
  label: SVGTextElement;
  hit: SVGRectElement;
  /** D16: dedicated toggle button over a branch knob — sits ON TOP of the drag hit rect so a
   * press on the +/− knob always toggles and can never fall through into a reorder drag.
   * Hidden for leaf strings (their knob stays part of the grab-anywhere drag surface). */
  knobHit: SVGCircleElement;
  /** Last written transform / path d — skip identical setAttribute in the RAF loop. */
  lastGTransform: string;
  lastPathD: string;
}

export interface SvgRendererOptions {
  width: number;
  height: number;
  groups: HangingStringGroup[];
  categories: HangingStringCategory[];
  colorMode: "group" | "heatmap";
  /** String flexibility for the D10 swing (0 = floppy, 1 = near-rigid rod). Default 0.5. */
  stiffness: number;
  /** Whether the bead-tick gridline marks (D6) are drawn along each string. Default true. */
  showTicks: boolean;
  /** Two-line labels: category name on line 1, "(value)" on line 2 — reads exact values at a
   * glance without hovering. Default false (name only). */
  labelValues: boolean;
  /** D28 (v4): render the 2nd metric as khipu knots on each cord. While active the D6
   * bead-ticks hide (Q30 — two knot vocabularies on one cord is unreadable). Default false. */
  quipuKnots?: boolean;
  /** v2 photoreal: the theme, consulted only for the thread's stroke texture (everything else
   * this renderer shows themes through CSS variables). Defaults to Studio (no texture — the
   * plain data-tinted stroke, exactly the pre-photoreal behavior). */
  theme?: HangingStringsDiagramTheme;
  /** D20: called on release after sliding a string along its rail, with the position it was
   * dropped at — for a ROOT the arc-length `along` parameter on the main rod (feed it back via
   * computeLayout's `positions`); for a CHILD its offset from the parent's anchor x on the
   * sub-rail (computeHierarchyLayout's `childPositions`). The string stays exactly where it
   * was dropped; nothing else moves. Arrow keys nudge through the same callback. */
  onSlide?: (id: string, position: number) => void;
  /** v2 (D16): called when a string with children is clicked (pointer never moved) or activated
   * via Enter/Space — caller toggles that branch's expansion and re-runs layout. Optional. */
  onToggleExpand?: (id: string) => void;
  /** Called when a group swatch is clicked (group-to-front). */
  onGroupToggle: (groupId: string) => void;
  /** Q25: fired with the hovered string's data on pointer enter and `null` on leave — for a
   * host's own tooltip. Independent of `showHoverCard`. */
  onHover?: (event: StringHoverEvent | null) => void;
  /** Q25: whether the built-in hover info card renders (default true) — hosts bringing their
   * own tooltip via `onHover` switch it off. */
  showHoverCard?: boolean;
}

export class SvgRenderer {
  private svg: SVGSVGElement;
  /** M1 (rail forms): a path, not a line — its shape comes from the layout's PlanarRailForm
   * (a straight full-width segment for StraightRailForm, curved for M2+ forms), so this
   * renderer never assumes what the rod looks like. */
  private railEl: SVGPathElement;
  private captionEl: SVGTextElement;
  /** D13 hanger rings, drawn under the rod so the rail stroke passes over each loop. */
  private hangerLayer: SVGGElement;
  private subRailLayer: SVGGElement;
  /** D16: per-expanded-parent sub-rail line + its offsets relative to the parent's knob, so the
   * animation loop can keep the sub-rail attached to the parent's live (swinging) knob rather
   * than its resting layout slot. dx1/dx2 are relative to the parent's anchor X; dy is the gap
   * below the parent's knob. */
  private subRailEls = new Map<string, { line: SVGLineElement; dx1: number; dx2: number; dy: number }>();
  private stringLayer: SVGGElement;
  /** Grows past options.height when an expanded branch (D16) needs the room; never shrinks
   * below the configured height. */
  private effectiveHeight: number;
  private els = new Map<string, StringEls>();
  private anim = new Map<string, StringAnim>();
  private hoverCard: HTMLDivElement;
  private options: SvgRendererOptions;
  private activeGroupId: string | null = null;
  private lastLayout: LayoutResult | null = null;
  private stringById = new Map<string, StringLayout>();
  private radiusMin = 0;
  private radiusMax = 0;
  /** Horizontal shift that centers the content when it's narrower than the canvas — applied as a
   * transform on `stringLayer`, and un-applied when converting pointer positions back to layout
   * coordinates. */
  private contentOffsetX = 0;
  /** v2 photoreal: per-tint thread stroke paint (plain tint, or a textured yarn pattern when
   * the theme ships a thread texture) — see createThreadPaintSource. */
  private threadPaint: ThreadPaintSource;
  /** This svg's <defs> — thread patterns plus the flat-rod sheen workaround below. */
  private defs: SVGDefsElement;
  /** D21.2: whether the scene breeze also stirs the threads (same signal as the backdrop
   * sheet). While on and visible, the physics loop never parks — the air never goes still. */
  private windEnabled = true;
  /** D21.8: multiplies organic breeze intensity for threadWindAccel (shake envelope). */
  private windScale = 1;
  private windPhase = 0;
  private visible = true;
  /** D20 live positional slide — mirrors ring mode's dragState (renderRing.ts), one level down
   * the abstraction: roots slide by arc length along the main rod, children by x-offset along
   * their straight sub-rail. A plain click (position unchanged) commits nothing. */
  private dragState: {
    id: string;
    pointerId: number;
    /** SVG bounding rect captured at drag start so pointermove never forces layout. */
    rect: DOMRect;
    /** Current slide position: a root's `along` on the main rail / a child's dx from its
     * parent's anchor. Committed via onSlide on release when it differs from startPos. */
    dragPos: number;
    startPos: number;
  } | null = null;
  private liveDragId: string | null = null;
  /** Q25: the currently hovered string (null = none) — dedupes onHover enter/leave firing. */
  private hoverId: string | null = null;
  /** The svg's viewBox width: the layout width, grown to the full content extent when the
   * content is wider (proportional fit — see render()). All pointer/hover conversions use
   * THIS, not options.width. */
  private viewBoxWidth: number;
  /** D25 (Q13 morph): screen-px anchor positions handed over by the OTHER renderer at a rail
   * mode switch — consumed by the next render(), which starts each string's spring there so
   * it visibly glides to its new anchor instead of teleporting. */
  private morphSeedScreen: Map<string, { x: number; y: number }> | null = null;
  /** Same map converted to THIS renderer's layout coords, plus each string's sweep chase
   * rate (valid for one render pass). D25.2: coords are optional — a planar form morph keeps
   * every string where it is and only slows its chase, so the rod's bend visibly ripples
   * through the hanging strings. */
  private morphSeedLayout: Map<string, { x?: number; y?: number; rate: number }> | null = null;
  /** D25.2: the next render assigns sweep chase rates without any position hand-off. */
  private formSweepPending = false;
  private morphTimer: ReturnType<typeof setTimeout> | null = null;
  /** The drawn rod's extent in `along` parameters, refreshed each render — slides clamp to it
   * so the hanger stays threaded on the rod (D17/D20: it never detaches past an end). */
  private railAlongMin = 0;
  private railAlongMax = 0;
  private rafId: number | null = null;
  private lastFrameTime: number | null = null;
  /** groupId → color / name, rebuilt when options.groups changes. */
  private groupColorById = new Map<string, string>();
  private groupNameById = new Map<string, string>();

  /** Q23: document-unique prefix for this instance's SVG def ids (thread patterns, the
   * flat-rod sheen) — url(#…) resolves document-wide, so ids must never repeat across
   * instances. */
  private readonly uid = nextInstanceUid("hsd-straight");

  constructor(container: HTMLElement, options: SvgRendererOptions) {
    this.options = options;
    this.rebuildGroupMaps();
    this.effectiveHeight = options.height;
    this.viewBoxWidth = options.width;

    this.svg = document.createElementNS(SVG_NS, "svg");
    this.svg.setAttribute("width", String(options.width));
    this.svg.setAttribute("height", String(options.height));
    this.svg.setAttribute("viewBox", `0 0 ${options.width} ${options.height}`);
    this.svg.setAttribute("role", "img");
    this.svg.setAttribute("aria-label", "Hanging Strings Diagram, straight rail");
    this.svg.classList.add("hsd-svg");

    // v2 photoreal: this renderer's first theme-derived DOM — per-tint thread patterns when
    // the theme ships a stroke texture (Wool & brass's yarn). Without one the paint source is
    // a pass-through and the defs stay empty.
    this.defs = document.createElementNS(SVG_NS, "defs");
    this.svg.appendChild(this.defs);
    this.threadPaint = createThreadPaintSource(this.defs, `${this.uid}-yarn`);
    this.threadPaint.setTexture((options.theme ?? STUDIO_THEME).thread.texture);

    this.railEl = document.createElementNS(SVG_NS, "path");
    this.railEl.setAttribute("class", "hsd-rail");
    // <path> fills black by default (the old <line> had no such gotcha) — the rod is stroke-only.
    this.railEl.setAttribute("fill", "none");

    // D6 sub-detail: what one bead is worth — without this the bead-ticks are unreadable
    // decoration to anyone who hasn't read the design docs.
    this.captionEl = document.createElementNS(SVG_NS, "text");
    this.captionEl.setAttribute("class", "hsd-tick-caption");
    this.captionEl.setAttribute("x", "8");
    this.svg.appendChild(this.captionEl);

    this.stringLayer = document.createElementNS(SVG_NS, "g");
    this.svg.appendChild(this.stringLayer);

    // M2: the rail lives INSIDE the string layer (so strings paint over it) because it
    // shares the layer's centering offset — on a curved form the rod's height varies with x, so
    // rod and anchors must agree on coordinates or strings would hang from the wrong heights.
    // For the straight rod this is pixel-identical to the old svg-level line. The D13 hanger
    // rings paint UNDER the rod (the rail stroke passes over each loop), same stacking as ring
    // mode's plate→hangers→rail order.
    this.hangerLayer = document.createElementNS(SVG_NS, "g");
    this.hangerLayer.setAttribute("class", "hsd-hangers");
    this.stringLayer.appendChild(this.hangerLayer);
    this.stringLayer.appendChild(this.railEl);

    // D16: sub-rails render inside the string layer (they share its centering offset) but
    // before every string group, so strings hang in front of their sub-rail bar.
    this.subRailLayer = document.createElementNS(SVG_NS, "g");
    this.stringLayer.appendChild(this.subRailLayer);

    container.appendChild(this.svg);

    // Heal stale string drags (same guard as renderRing.ts): one pointer cannot press twice,
    // so a NEW pointerdown carrying the same pointerId proves the previous drag's pointerup was
    // lost. Left in place, a stale drag pins its string to the drag target forever. Capture
    // phase, so it runs before any target handler starts the new drag.
    this.svg.addEventListener(
      "pointerdown",
      (ev) => {
        if (this.dragState && this.dragState.pointerId === ev.pointerId) {
          this.els.get(this.dragState.id)?.g.classList.remove("hsd-dragging");
          this.dragState = null;
          this.liveDragId = null;
        }
      },
      true
    );

    this.hoverCard = document.createElement("div");
    this.hoverCard.className = "hsd-hover-card";
    this.hoverCard.style.display = "none";
    // The hover card needs a positioned ancestor — but never OVERWRITE a positioning the host
    // chose (an adapter's absolutely-positioned overlay must stay absolute).
    if (getComputedStyle(container).position === "static") {
      container.style.position = "relative";
    }
    container.appendChild(this.hoverCard);
  }

  setOptions(patch: Partial<SvgRendererOptions>) {
    const groupsChanged = patch.groups !== undefined;
    this.options = { ...this.options, ...patch };
    if (groupsChanged) this.rebuildGroupMaps();
  }

  private rebuildGroupMaps() {
    this.groupColorById = new Map(this.options.groups.map((g) => [g.id, g.color]));
    this.groupNameById = new Map(this.options.groups.map((g) => [g.id, g.name]));
  }

  /** T3 live theme switching, v2 photoreal: this renderer's only theme-derived DOM is the
   * per-tint thread patterns — rebuild them and repaint (same contract as
   * RingSvgRenderer.setTheme; everything else here themes through CSS variables). */
  setTheme(theme: HangingStringsDiagramTheme) {
    this.options = { ...this.options, theme };
    this.threadPaint.setTexture(theme.thread.texture);
    if (this.lastLayout) this.render(this.lastLayout);
  }

  /** Shows/hides this renderer's DOM without tearing it down — used when switching rail modes
   * (v1.1) so straight mode's D10 spring state survives being temporarily out of view. */
  setVisible(visible: boolean) {
    this.visible = visible;
    this.svg.style.display = visible ? "" : "none";
    if (!visible) this.hoverCard.style.display = "none";
    else this.ensureTicking(); // resume the breeze (the loop parks while hidden)
  }

  /** D21.2: the scene breeze stirring the threads — tied to the backdrop's toggle. */
  setWind(on: boolean) {
    this.windEnabled = on;
    if (on) this.ensureTicking();
  }

  /** D21.8: multiplies breeze intensity applied to threads (default 1). */
  setWindScale(scale: number) {
    this.windScale = Number.isFinite(scale) ? Math.max(0, scale) : 0;
  }

  /** D25 (Q13 morph): every string's CURRENT animated anchor in screen px relative to the
   * svg's top-left — the hand-off coordinate space both renderers share (their svgs overlap
   * during the cross-fade). */
  captureAnchorScreenPositions(): Map<string, { x: number; y: number }> {
    const out = new Map<string, { x: number; y: number }>();
    const rect = this.svg.getBoundingClientRect();
    if (!(rect.width > 0)) return out;
    const scale = rect.width / this.viewBoxWidth;
    for (const [id, anim] of this.anim) {
      out.set(id, {
        x: (this.contentOffsetX + anim.anchorX) * scale,
        y: anim.anchorY * scale,
      });
    }
    return out;
  }

  /** D25: the incoming half of the hand-off — the next render() starts each seeded string's
   * spring at the given screen position (converted into this renderer's layout space). */
  seedAnchorScreenPositions(seed: Map<string, { x: number; y: number }>): void {
    this.morphSeedScreen = seed;
  }

  /** D25.2 (planar form morph — straight↔arc↔wave): no position hand-off (same renderer,
   * strings stay put horizontally), but the next render gives every string its sweep chase
   * rate so the anchors ripple to the new rod form instead of snapping in ~50ms. */
  beginFormSweep(): void {
    this.formSweepPending = true;
  }

  /** D25 cross-fade, outgoing side: the svg ghosts in place (absolute, non-interactive) and
   * fades out, then hides. */
  morphOut(durationMs: number): void {
    if (this.morphTimer !== null) clearTimeout(this.morphTimer);
    const svg = this.svg;
    svg.classList.add("hsd-morphing", "hsd-morph-ghost");
    svg.style.opacity = "1";
    requestAnimationFrame(() => {
      svg.style.opacity = "0";
    });
    this.morphTimer = setTimeout(() => {
      this.morphTimer = null;
      svg.classList.remove("hsd-morphing", "hsd-morph-ghost");
      svg.style.opacity = "";
      this.setVisible(false);
    }, durationMs);
  }

  /** D25 cross-fade, incoming side: becomes visible at opacity 0 and fades in. */
  morphIn(durationMs: number): void {
    if (this.morphTimer !== null) clearTimeout(this.morphTimer);
    const svg = this.svg;
    svg.classList.remove("hsd-morph-ghost");
    svg.classList.add("hsd-morphing");
    svg.style.opacity = "0";
    this.setVisible(true);
    requestAnimationFrame(() => {
      svg.style.opacity = "1";
    });
    this.morphTimer = setTimeout(() => {
      this.morphTimer = null;
      svg.classList.remove("hsd-morphing");
      svg.style.opacity = "";
    }, durationMs);
  }

  /** Tears this renderer's DOM out of the container and stops its animation loop — the façade's
   * destroy() path (integration I4). The instance must not be used afterwards. */
  destroy() {
    if (this.rafId !== null) cancelAnimationFrame(this.rafId);
    this.rafId = null;
    this.svg.remove();
    this.hoverCard.remove();
  }

  /** Adopts a new canvas width (responsive sizing) — the caller re-runs layout + render after. */
  resize(width: number) {
    this.options.width = width;
    this.viewBoxWidth = Math.max(width, Math.ceil(this.lastLayout?.contentWidth ?? 0));
    this.applyCanvasSize();
  }

  private applyCanvasSize() {
    this.svg.setAttribute("width", String(this.viewBoxWidth));
    this.svg.setAttribute("height", String(this.effectiveHeight));
    this.svg.setAttribute("viewBox", `0 0 ${this.viewBoxWidth} ${this.effectiveHeight}`);
  }

  setActiveGroup(groupId: string | null) {
    this.activeGroupId = groupId;
    if (this.lastLayout) this.render(this.lastLayout);
  }

  render(layout: LayoutResult) {
    // D25: convert the morph hand-off (screen px) into THIS renderer's layout coords using
    // the svg's CURRENT geometry — before the viewBox/offset updates below change it. The
    // converted map is consumed by updateStringElement during this one pass. Each string also
    // gets its sweep rate: later strings (layout order) glide slower, so the transformation
    // visibly travels across the chart.
    if (this.morphSeedScreen) {
      const rect = this.svg.getBoundingClientRect();
      if (rect.width > 0) {
        const toLayout = this.viewBoxWidth / rect.width;
        const orderIndex = new Map(layout.strings.map((s, i) => [s.category.id, i]));
        const lastIndex = Math.max(1, layout.strings.length - 1);
        this.morphSeedLayout = new Map(
          [...this.morphSeedScreen].map(([id, p]) => [
            id,
            {
              x: p.x * toLayout - this.contentOffsetX,
              y: p.y * toLayout,
              rate: morphAnchorEaseRate((orderIndex.get(id) ?? 0) / lastIndex),
            },
          ])
        );
      }
      this.morphSeedScreen = null;
    }
    // D25.2: a planar form change sweeps rates only — strings keep their positions and glide
    // to the new rod's heights left-to-right.
    if (this.formSweepPending) {
      const lastIndex = Math.max(1, layout.strings.length - 1);
      this.morphSeedLayout = new Map(
        layout.strings.map((s, i) => [s.category.id, { rate: morphAnchorEaseRate(i / lastIndex) }])
      );
      this.formSweepPending = false;
    }

    this.lastLayout = layout;
    this.stringById = new Map(layout.strings.map((s) => [s.category.id, s]));
    const radii = layout.strings.map((s) => s.knobRadius);
    this.radiusMin = radii.length ? Math.min(...radii) : 0;
    this.radiusMax = radii.length ? Math.max(...radii) : 0;

    // D16: grow the canvas downward when an expanded branch needs the room (never shrink below
    // the configured height — collapsing back doesn't jump the page around).
    const wantedHeight = Math.max(this.options.height, Math.ceil(layout.contentHeight ?? 0));
    // Proportional fit (2026-07-20): the viewBox always covers the FULL content extent — a
    // layout wider than the canvas used to be silently clipped at the right edge; now the
    // whole diagram scales down uniformly into the visible container instead (style.css
    // .hsd-svg width:100%/height:auto does the fitting).
    const wantedWidth = Math.max(this.options.width, Math.ceil(layout.contentWidth));
    if (wantedHeight !== this.effectiveHeight || wantedWidth !== this.viewBoxWidth) {
      this.effectiveHeight = wantedHeight;
      this.viewBoxWidth = wantedWidth;
      this.applyCanvasSize();
    }

    // Center the hanging content when it's narrower than the canvas; the rail itself still spans
    // the full width (a rod longer than its curtains), so only the strings shift.
    this.contentOffsetX = Math.max(0, (this.options.width - layout.contentWidth) / 2);
    this.stringLayer.setAttribute("transform", `translate(${this.contentOffsetX}, 0)`);

    // M1/M2: the rod's rendered shape comes from the form. It still spans the full canvas
    // width (a rod longer than its curtains), but is drawn in the string layer's shifted
    // coordinates — alongAtX converts the canvas edges into `along` parameters, which for the
    // straight rod reproduces the old full-width line exactly. The same extent bounds D20
    // slides, so a string can be parked anywhere on the visible rod and nowhere off it.
    this.railAlongMin = layout.railForm.alongAtX(-this.contentOffsetX);
    this.railAlongMax = layout.railForm.alongAtX(this.viewBoxWidth - this.contentOffsetX);
    this.railEl.setAttribute(
      "d",
      layout.railForm.railPath(this.railAlongMin, this.railAlongMax)
    );

    // Zero-height-bbox workaround for photoreal sheens: a PERFECTLY HORIZONTAL rod path has a
    // degenerate bounding box, and the SVG spec disables objectBoundingBox paint servers on
    // degenerate boxes outright — the shared hsd-rail-sheen gradient paints NOTHING on the
    // straight rod (curved planar rods and the ring's ellipse have real boxes and shade
    // normally). Detection is geometric (three form samples at one height); the fix is a local
    // userSpace copy of the sheen spanning exactly the rod's stroke band — the lit-pipe
    // cross-section — referenced inline so the CSS var stays authoritative everywhere else.
    const theme = this.options.theme ?? STUDIO_THEME;
    const sheen = theme.rail.sheen;
    const railYs = [this.railAlongMin, (this.railAlongMin + this.railAlongMax) / 2, this.railAlongMax]
      .map((along) => layout.railForm.anchorAt(along).y);
    const flatRod = Math.max(...railYs) - Math.min(...railYs) < 0.5;
    const flatSheenId = `${this.uid}-rail-sheen-flat`;
    this.defs.querySelector(`#${flatSheenId}`)?.remove();
    if (sheen && flatRod) {
      const local = createFillDef(flatSheenId, sheen);
      local.setAttribute("gradientUnits", "userSpaceOnUse");
      local.setAttribute("x1", "0");
      local.setAttribute("x2", "0");
      local.setAttribute("y1", String(railYs[0] - theme.rail.strokeWidth / 2));
      local.setAttribute("y2", String(railYs[0] + theme.rail.strokeWidth / 2));
      this.defs.appendChild(local);
      this.railEl.style.stroke = `url(#${flatSheenId})`;
    } else {
      this.railEl.style.stroke = "";
    }

    // D16 sub-rails: a handful of lines, rebuilt per render. Coordinates here are the resting
    // layout position; the animation loop re-anchors each line to its parent's live knob every
    // frame (see applyTransform) so the branch stays visually attached while the parent moves.
    this.subRailLayer.textContent = "";
    this.subRailEls.clear();
    for (const rail of layout.subRails ?? []) {
      const parentS = this.stringById.get(rail.parentId);
      const line = document.createElementNS(SVG_NS, "line");
      line.setAttribute("class", "hsd-rail hsd-subrail");
      // Same degenerate-bbox problem as the flat rod above, but a sub-rail bar also RIDES its
      // parent's live knob every frame — a static userSpace gradient would misalign mid-swing.
      // Branch hardware settles for the flat rail tone under sheen themes.
      if (sheen) line.style.stroke = theme.rail.color;
      line.setAttribute("x1", String(rail.x1));
      line.setAttribute("x2", String(rail.x2));
      line.setAttribute("y1", String(rail.y));
      line.setAttribute("y2", String(rail.y));
      this.subRailLayer.appendChild(line);
      if (parentS) {
        this.subRailEls.set(rail.parentId, {
          line,
          dx1: rail.x1 - parentS.x,
          dx2: rail.x2 - parentS.x,
          dy: rail.y - parentS.knobY,
        });
      }
    }

    this.captionEl.textContent = `· 1 knot = ${layout.tickStepValue}`;
    // M1: the caption rides the rail's height AT ITS OWN X (form-derived, not the shared
    // railY), so it stays glued above the rod's left end when a curved form varies the height.
    // Its x is canvas-absolute (outside the string layer), hence the offset conversion.
    this.captionEl.setAttribute(
      "y",
      String(layout.railForm.anchorAt(layout.railForm.alongAtX(8 - this.contentOffsetX)).y - 12)
    );
    this.captionEl.style.display = this.options.showTicks ? "" : "none";

    const secondaryValues = this.options.categories
      .map((c) => c.secondaryValue)
      .filter((v): v is number => typeof v === "number");
    const secondaryDomain: [number, number] =
      secondaryValues.length > 0
        ? [Math.min(...secondaryValues), Math.max(...secondaryValues)]
        : [0, 1];
    const heatT = linearScale(secondaryDomain, [0, 1]);

    const seenIds = new Set<string>();
    for (const s of layout.strings) {
      seenIds.add(s.category.id);
      let els = this.els.get(s.category.id);
      if (!els) {
        els = this.createStringElement(s.category.id);
        this.els.set(s.category.id, els);
        this.hangerLayer.appendChild(els.hanger);
        this.stringLayer.appendChild(els.g);
      }
      this.updateStringElement(els, s, heatT);
    }
    for (const [id, els] of this.els) {
      if (!seenIds.has(id)) {
        els.g.remove();
        els.hanger.remove();
        this.els.delete(id);
        this.anim.delete(id);
      }
    }
    // Proportional fit, part 2: rotated rail-tags (D9 option B) extend up-RIGHT past their
    // anchor, so the LAST string's label can poke past layout.contentWidth — measure the real
    // text lengths (deterministic rest positions, not animation state) and grow the viewBox
    // for the overhang, then stretch the rod to the new right edge. Only text that renders
    // measures > 0 (a hidden renderer re-renders on becoming visible, so nothing goes stale).
    let contentRight = this.viewBoxWidth;
    for (const s of layout.strings) {
      const els = this.els.get(s.category.id);
      const len = els?.label.getComputedTextLength?.() ?? 0;
      if (!(len > 0)) continue;
      // D9.1: every label rides its knob horizontally, starting knobRadius+6 right of the
      // anchor (see updateStringElement's label transform). Small pad covers the halo stroke.
      const reach = s.knobRadius + 6 + len + 8;
      contentRight = Math.max(contentRight, this.contentOffsetX + s.x + reach);
    }
    const grownWidth = Math.ceil(contentRight);
    if (grownWidth !== this.viewBoxWidth) {
      this.viewBoxWidth = grownWidth;
      this.applyCanvasSize();
      this.railAlongMax = layout.railForm.alongAtX(this.viewBoxWidth - this.contentOffsetX);
      this.railEl.setAttribute(
        "d",
        layout.railForm.railPath(this.railAlongMin, this.railAlongMax)
      );
    }

    this.morphSeedLayout = null; // one-shot: consumed by the pass above
    this.ensureTicking();
    this.svg.classList.toggle("hsd-dense", layout.strings.length >= DENSE_STRING_THRESHOLD);
  }

  private groupColor(groupId: string): string {
    return this.groupColorById.get(groupId) ?? "#888";
  }

  private colorFor(s: StringLayout, heatT: (v: number) => number): string {
    if (this.options.colorMode === "heatmap") {
      if (typeof s.category.secondaryValue !== "number") return "#9ca3af";
      return heatmapColor(heatT(s.category.secondaryValue));
    }
    return this.groupColor(s.category.groupId);
  }

  private createStringElement(id: string): StringEls {
    const hanger = document.createElementNS(SVG_NS, "ellipse");
    hanger.setAttribute("class", "hsd-string-hanger");
    hanger.setAttribute("rx", String(HANGER_RING_RX));
    hanger.setAttribute("ry", String(HANGER_RING_RY));

    const g = document.createElementNS(SVG_NS, "g");
    g.setAttribute("class", "hsd-string");
    g.dataset.id = id;

    // Everything that hangs starts below the hanger ring's bottom edge (D13) so the string
    // visibly hangs FROM the hardware — same `hang` subgroup structure as renderRing.ts.
    const hang = document.createElementNS(SVG_NS, "g");
    hang.setAttribute("transform", `translate(0 ${HANGER_DROP_OFFSET})`);
    g.appendChild(hang);

    // D11.1: the cast shadows go in FIRST — beneath the thread, ticks, knob and label — and
    // carry the scene light's fixed offset; per frame they just mirror the thread's d / knob's
    // cx, so the shadow swings with the string at no filter cost.
    const castThread = document.createElementNS(SVG_NS, "path");
    castThread.setAttribute("class", "hsd-thread-cast");
    castThread.setAttribute("transform", CAST_SHADOW_TRANSFORM);
    hang.appendChild(castThread);

    const castKnob = document.createElementNS(SVG_NS, "circle");
    castKnob.setAttribute("class", "hsd-knob-cast");
    castKnob.setAttribute("transform", CAST_SHADOW_TRANSFORM);
    hang.appendChild(castKnob);

    const thread = document.createElementNS(SVG_NS, "path");
    thread.setAttribute("class", "hsd-thread");
    thread.setAttribute("fill", "none");
    hang.appendChild(thread);

    const ticksLayer = document.createElementNS(SVG_NS, "g");
    ticksLayer.setAttribute("class", "hsd-ticks");
    hang.appendChild(ticksLayer);

    // D28: quipu knots paint over the thread exactly like the bead-ticks they replace.
    const quipuLayer = document.createElementNS(SVG_NS, "g");
    quipuLayer.setAttribute("class", "hsd-quipu");
    hang.appendChild(quipuLayer);

    const shadow = document.createElementNS(SVG_NS, "ellipse");
    shadow.setAttribute("class", "hsd-shadow");
    shadow.setAttribute("rx", "10");
    shadow.setAttribute("ry", "3");
    hang.appendChild(shadow);

    const knob = document.createElementNS(SVG_NS, "circle");
    knob.setAttribute("class", "hsd-knob");
    hang.appendChild(knob);

    const glyph = document.createElementNS(SVG_NS, "text");
    glyph.setAttribute("class", "hsd-expand-glyph");
    hang.appendChild(glyph);

    const label = document.createElementNS(SVG_NS, "text");
    label.setAttribute("class", "hsd-label");
    hang.appendChild(label);

    const hit = document.createElementNS(SVG_NS, "rect");
    hit.setAttribute("class", "hsd-hit");
    hit.setAttribute("x", "-18");
    hang.appendChild(hit);

    const knobHit = document.createElementNS(SVG_NS, "circle");
    knobHit.setAttribute("class", "hsd-knob-hit");
    knobHit.setAttribute("aria-hidden", "true");
    knobHit.style.display = "none";
    hang.appendChild(knobHit);

    this.attachInteractions(hit, id);
    this.attachToggleInteractions(knobHit, id);
    return {
      g,
      hanger,
      castThread,
      castKnob,
      thread,
      ticksLayer,
      tickYs: [],
      tickSig: "",
      quipuLayer,
      quipuEls: [],
      quipuSig: "",
      shadow,
      knob,
      glyph,
      label,
      hit,
      knobHit,
      lastGTransform: "",
      lastPathD: "",
    };
  }

  private updateStringElement(els: StringEls, s: StringLayout, heatT: (v: number) => number) {
    const color = this.colorFor(s, heatT);
    const wasTicking = this.rafId !== null;

    let anim = this.anim.get(s.category.id);
    if (!anim) {
      // D16: a child string appearing on expand spawns at its parent's live knob and swings out
      // to its own slot — the "unfurl" comes free from the shared chain physics.
      const parentAnim = s.parentId ? this.anim.get(s.parentId) : undefined;
      const parentS = s.parentId ? this.stringById.get(s.parentId) : undefined;
      const spawnX =
        parentAnim && parentS
          ? parentAnim.anchorX + parentAnim.nodes[N_NODES - 1].value
          : s.x;
      const spawnY =
        parentAnim && parentS
          ? parentAnim.anchorY + HANGER_DROP_OFFSET + parentS.dropPx
          : s.railY;
      anim = createChainAnim(spawnX, spawnY);
      anim.targetX = s.x;
      anim.targetY = s.railY;
      this.anim.set(s.category.id, anim);
    } else if (s.category.id !== this.liveDragId) {
      // Never retarget the string currently being dragged — a render mid-drag (setOptions,
      // resize) must not yank the grabbed string off the pointer.
      anim.targetX = s.x;
      anim.targetY = s.railY;
    }
    // D25: a rail-mode morph starts this string's spring at its position in the OTHER
    // renderer — it glides to the target set above instead of teleporting, at its sweep
    // rate (self-clearing, see core/chain.ts). D25.2 form morphs carry no coords: the
    // string stays where it is and only its chase slows.
    const morphFrom = this.morphSeedLayout?.get(s.category.id);
    if (morphFrom) {
      if (morphFrom.x !== undefined) anim.anchorX = morphFrom.x;
      if (morphFrom.y !== undefined) anim.anchorY = morphFrom.y;
      anim.anchorEaseRate = morphFrom.rate;
    }

    const dimmed = this.activeGroupId !== null && s.category.groupId !== this.activeGroupId;
    els.g.classList.toggle("hsd-dimmed", dimmed);
    els.hanger.classList.toggle("hsd-dimmed", dimmed);

    setAttrIfChanged(els.thread, "stroke", this.threadPaint.paintFor(color));

    // Q30: quipu mode owns the cord's knot vocabulary — the D6 bead-ticks yield while it's on.
    const quipuOn = this.options.quipuKnots === true;
    els.ticksLayer.style.display = this.options.showTicks && !quipuOn ? "" : "none";
    els.quipuLayer.style.display = quipuOn ? "" : "none";
    // D6.1: the scale marks are KNOTS tied in the thread — ellipse bulges filled with the
    // thread's OWN paint (data tint, or the rope texture: both live in the same local frame,
    // so the pattern runs continuously through the knot like a knot tied in the same rope).
    // Sized off the theme's thread width — a fat rope gets a fat knot; the faint themable
    // edge (--hsd-tick-stroke) is what keeps the bulge readable against the straight run.
    // Paint and size join the rebuild signature so theme/texture/color-mode switches restyle.
    const tickPaint = this.threadPaint.paintFor(color);
    const knotRx = Math.max(2.6, (this.options.theme ?? STUDIO_THEME).thread.strokeWidth * 0.85);
    const tickSig = `${tickPaint}|${knotRx}|${s.ticks.map((t) => t.y.toFixed(2)).join(",")}`;
    if (tickSig !== els.tickSig) {
      els.tickSig = tickSig;
      els.tickYs = s.ticks.map((t) => t.y);
      els.ticksLayer.textContent = "";
      for (const tick of s.ticks) {
        const knot = document.createElementNS(SVG_NS, "ellipse");
        knot.setAttribute("class", "hsd-tick");
        knot.setAttribute("cy", String(tick.y));
        knot.setAttribute("rx", String(knotRx));
        knot.setAttribute("ry", String(knotRx * 0.72));
        knot.style.fill = tickPaint;
        els.ticksLayer.appendChild(knot);
      }
    }

    // D28: rebuild the quipu glyphs when the encoded value, cord length, or paint changes.
    if (quipuOn) {
      const qLayout = computeQuipuLayout(s.category.secondaryValue, s.dropPx);
      const sw = (this.options.theme ?? STUDIO_THEME).thread.strokeWidth;
      const qSig = `${tickPaint}|${sw}|${s.dropPx.toFixed(1)}|${qLayout.mode}|${qLayout.digits.join("")}|${qLayout.bucketUnit ?? ""}`;
      if (qSig !== els.quipuSig) {
        els.quipuSig = qSig;
        els.quipuEls = buildQuipuLayer(
          els.quipuLayer,
          qLayout,
          s.dropPx,
          tickPaint,
          sw,
          DEFAULT_QUIPU_CONFIG
        );
      }
    } else if (els.quipuSig !== "") {
      els.quipuSig = "";
      els.quipuEls = [];
      els.quipuLayer.textContent = "";
    }

    setAttrIfChanged(els.shadow, "cy", String(s.dropPx + s.knobRadius * 0.9));

    setAttrIfChanged(els.knob, "cy", String(s.dropPx));
    setAttrIfChanged(els.knob, "r", String(s.knobRadius));
    setAttrIfChanged(els.castKnob, "cy", String(s.dropPx));
    setAttrIfChanged(els.castKnob, "r", String(s.knobRadius));
    setAttrIfChanged(els.knob, "fill", color);

    // D9.1 (user, 2026-07-15): ALL labels ride their knob at the string's BOTTOM — option C
    // replaces the rotated rail-tag (B); the hover card (D) is unchanged. Root and child
    // labels now share one convention, and the rail line stays clean for the hanger hardware.
    const isChild = Boolean(s.parentId);
    els.label.classList.toggle("hsd-label-child", isChild);
    setAttrIfChanged(els.label, "x", "0");
    setAttrIfChanged(els.label, "y", "0");
    setLabelContent(els.label, s.category, this.options.labelValues, 0);

    // D16 affordances: a parent with children gets a visibly different knob (branch cue) and an
    // expanded marker while its sub-rail is out.
    const childCount = s.category.children?.length ?? 0;
    const isExpanded = (this.lastLayout?.subRails ?? []).some(
      (r) => r.parentId === s.category.id
    );
    els.knob.classList.toggle("hsd-knob-branch", childCount > 0);
    els.g.classList.toggle("hsd-expanded", isExpanded);
    const glyphText = childCount > 0 ? (isExpanded ? "−" : "+") : "";
    if (els.glyph.textContent !== glyphText) els.glyph.textContent = glyphText;
    setAttrIfChanged(els.glyph, "y", String(s.dropPx));
    setAttrIfChanged(els.glyph, "font-size", String(Math.max(9, s.knobRadius * 1.7)));

    // D16: the toggle button IS the knob face (+/−) — slightly larger than the painted knob.
    // D30: expand target stays on the weight; the slide hit is a separate lower-end halo around it.
    els.knobHit.style.display = childCount > 0 ? "" : "none";
    setAttrIfChanged(els.knobHit, "r", String(expandHitRadius(s.knobRadius)));
    setAttrIfChanged(els.knobHit, "cy", String(s.dropPx));
    setAttrIfChanged(
      els.knobHit,
      "aria-label",
      childCount > 0
        ? `${isExpanded ? "Collapse" : "Expand"} ${s.category.name}`
        : ""
    );

    // D30: grab-to-slide only at the lower weight — upper cord is inert to accidental grabs.
    const hitGeo = lowerEndHitGeometry(s.dropPx, s.knobRadius);
    setAttrIfChanged(els.hit, "x", String(hitGeo.x));
    setAttrIfChanged(els.hit, "y", String(hitGeo.y));
    setAttrIfChanged(els.hit, "width", String(hitGeo.width));
    setAttrIfChanged(els.hit, "height", String(hitGeo.height));
    els.hit.style.cursor = "grab";
    setAttrIfChanged(els.hit, "tabindex", "0");
    setAttrIfChanged(els.hit, "role", "button");
    const groupName = this.groupNameById.get(s.category.groupId);
    const childHint =
      childCount > 0
        ? `, ${childCount} children — press the +/− on the weight to ${isExpanded ? "collapse" : "expand"}`
        : "";
    setAttrIfChanged(
      els.hit,
      "aria-label",
      `${s.category.name}, value ${s.category.value}${groupName ? `, group ${groupName}` : ""}${childHint}. Drag the weight to slide along the ${isChild ? "sub-rail" : "rail"}.`
    );

    // If the RAF loop is already running it will applyTransform this frame — skip the duplicate
    // write from render()/drag-preview. When idle, pose immediately before ensureTicking starts.
    if (!wasTicking) this.applyTransform(els, anim, s);
  }

  /**
   * Positions everything from the current animation state. The thread is a smooth curve through
   * anchor(0,0) and all of anim.nodes, ending exactly at the knob — Y is always exactly `dropPx`
   * for the knob and the tick's own y for ticks (D1-safe), only X ever sways.
   */
  private applyTransform(els: StringEls, anim: StringAnim, s: StringLayout) {
    const gTransform = `translate(${anim.anchorX}, ${anim.anchorY})`;
    if (els.lastGTransform !== gTransform) {
      els.g.setAttribute("transform", gTransform);
      els.hanger.setAttribute("transform", gTransform);
      els.lastGTransform = gTransform;
    }

    const points: Point[] = [{ x: 0, y: 0 }];
    for (let i = 0; i < N_NODES; i++) {
      points.push({ x: anim.nodes[i].value, y: ((i + 1) / N_NODES) * s.dropPx });
    }
    const knobX = anim.nodes[N_NODES - 1].value;

    const pathD = smoothPathThroughPoints(points);
    if (els.lastPathD !== pathD) {
      els.thread.setAttribute("d", pathD);
      els.castThread.setAttribute("d", pathD);
      els.lastPathD = pathD;
    }

    // D9.1: every label rides its knob — to the right of the weight, at the value's depth.
    setAttrIfChanged(
      els.label,
      "transform",
      `translate(${knobX + s.knobRadius + 6} ${s.dropPx + 4})`
    );

    // D16: keep this parent's sub-rail glued to its live knob (sway and all) — the branch must
    // read as hanging FROM the parent string, not floating at the parent's old slot.
    const sub = this.subRailEls.get(s.category.id);
    if (sub) {
      const knobWorldX = anim.anchorX + knobX;
      const railWorldY = anim.anchorY + HANGER_DROP_OFFSET + s.dropPx + sub.dy;
      setAttrIfChanged(sub.line, "x1", String(knobWorldX + sub.dx1));
      setAttrIfChanged(sub.line, "x2", String(knobWorldX + sub.dx2));
      setAttrIfChanged(sub.line, "y1", String(railWorldY));
      setAttrIfChanged(sub.line, "y2", String(railWorldY));
    }

    // D23: bead-knots track the thread every frame — breeze sway and single-string pulls are
    // cheap and keep full detail (the hsd-animating LOD is a ring-mode disc-spin concern; the
    // planar rails have no disc, so this renderer never sheds it).
    if (this.options.showTicks && this.options.quipuKnots !== true) {
      const tickEls = els.ticksLayer.children;
      for (let i = 0; i < tickEls.length; i++) {
        setAttrIfChanged(tickEls[i], "cx", String(xAlongPolyline(points, els.tickYs[i])));
      }
    }
    // D28: quipu glyphs ride the bowed thread the same way — each glyph group re-translates
    // to the thread's x at its own y (the knots are tied IN the cord, so they sway with it).
    for (const q of els.quipuEls) {
      setAttrIfChanged(q.g, "transform", `translate(${xAlongPolyline(points, q.y)} ${q.y})`);
    }

    setAttrIfChanged(els.shadow, "cx", String(knobX));
    setAttrIfChanged(els.knob, "cx", String(knobX));
    setAttrIfChanged(els.castKnob, "cx", String(knobX));
    setAttrIfChanged(els.glyph, "x", String(knobX));
    setAttrIfChanged(els.knobHit, "cx", String(knobX));
  }

  // --- animation loop (D10: flexible-string "shock absorber") ----------------------------

  private ensureTicking() {
    if (this.rafId === null) {
      this.lastFrameTime = null;
      this.rafId = requestAnimationFrame(this.tick);
    }
  }

  private tick = (timestamp: number) => {
    const dt = Math.min((timestamp - (this.lastFrameTime ?? timestamp)) / 1000, 1 / 30);
    this.lastFrameTime = timestamp;

    // Hoisted out of the per-string loop: same for every string this frame.
    const chainParams = chainParamsForStiffness(this.options.stiffness);

    // D21.2: the same breeze that waves the backdrop sheet stirs the threads — one wind for
    // the whole scene (same signal, same traveling gust field, phase integrating gust speed).
    const wind = this.windEnabled && this.visible ? breezeSignal(timestamp / 1000) : null;
    if (wind) this.windPhase += wind.speed * dt * 1.1;

    let allSettled = true;
    for (const [id, anim] of this.anim) {
      const s = this.stringById.get(id);

      // D16: children chase their PARENT's live knob (anchor + sway), not their static layout
      // slot, so the whole branch hangs off the parent string while it moves. Roots insert into
      // the anim map before their children, so the parent has already stepped this frame.
      // D20: a child being DRAGGED stays pinned to the sub-rail (its target is the bar point at
      // its live drag offset, recomputed from the parent's live knob) — the hanger slides along
      // the mini rod instead of detaching from it, mirroring the ring's mini-rim behavior.
      if (s?.parentId) {
        const parentAnim = this.anim.get(s.parentId);
        const parentS = this.stringById.get(s.parentId);
        if (parentAnim && parentS) {
          const parentKnobWorldX = parentAnim.anchorX + parentAnim.nodes[N_NODES - 1].value;
          const dx =
            id === this.liveDragId && this.dragState
              ? this.dragState.dragPos
              : s.x - parentS.x;
          anim.targetX = parentKnobWorldX + dx;
          anim.targetY =
            parentAnim.anchorY + HANGER_DROP_OFFSET + parentS.dropPx + (s.railY - parentS.knobY);
        }
      }

      const { settled } = stepChainAnim(anim, {
        isDraggingThis: id === this.liveDragId,
        stiffness: this.options.stiffness,
        chainParams,
        knobRadius: s?.knobRadius ?? this.radiusMin,
        radiusMin: this.radiusMin,
        radiusMax: this.radiusMax,
        dt,
        windAccelPx: wind
          ? threadWindAccel(
              (anim.anchorX + this.contentOffsetX) / this.viewBoxWidth,
              this.windPhase,
              wind.intensity * this.windScale
            )
          : 0,
      });
      if (!settled) allSettled = false;

      const els = this.els.get(id);
      if (els && s) this.applyTransform(els, anim, s);
    }

    if (!allSettled || this.liveDragId !== null || (this.windEnabled && this.visible)) {
      this.rafId = requestAnimationFrame(this.tick);
    } else {
      this.rafId = null;
      this.lastFrameTime = null;
    }
  };

  /** D20: a string's CURRENT position in slide coordinates — a root's `along` on the main rod
   * (inverted from its anchor x via the form), a child's dx from its parent's anchor. Drags
   * and arrow-key nudges start from here. */
  private restPositionOf(s: StringLayout): number {
    if (s.parentId) {
      const parentS = this.stringById.get(s.parentId);
      return s.x - (parentS?.x ?? 0);
    }
    return this.lastLayout?.railForm.alongAtX(s.x) ?? s.x;
  }

  /** The slide bounds for a string (D17/D20: the hanger stays threaded on its rod): a root's
   * are the drawn rail's extent; a child's the sub-rail bar, minus a small end margin. */
  private slideBoundsOf(s: StringLayout): [number, number] {
    if (s.parentId) {
      const sub = this.subRailEls.get(s.parentId);
      if (!sub) return [0, 0];
      return [sub.dx1 + SUBRAIL_END_PAD_PX, sub.dx2 - SUBRAIL_END_PAD_PX];
    }
    return [this.railAlongMin, this.railAlongMax];
  }

  private attachInteractions(hit: SVGRectElement, id: string) {
    hit.addEventListener("pointerenter", () => {
      this.els.get(id)?.g.classList.add("hsd-slide-hover");
      this.showHoverCard(id);
    });
    hit.addEventListener("pointerleave", () => {
      this.els.get(id)?.g.classList.remove("hsd-slide-hover");
      if (this.dragState) return;
      this.hideHoverCard();
    });
    hit.addEventListener("pointerdown", (ev) => {
      // D30: grab is always the weight (lower end) — drive the chain from the knob node.
      const anim = this.anim.get(id);
      const s = this.stringById.get(id);
      const svgRect = this.svg.getBoundingClientRect();
      if (anim) anim.grabbedIndex = N_NODES - 1;
      const startPos = s ? this.restPositionOf(s) : 0;
      this.dragState = {
        id,
        pointerId: ev.pointerId,
        rect: svgRect,
        dragPos: startPos,
        startPos,
      };
      this.liveDragId = id;
      try {
        hit.setPointerCapture(ev.pointerId);
      } catch {
        // ignore — a capture failure shouldn't cancel the drag, just the "keeps tracking
        // outside the element's bounds" guarantee capture normally gives
      }
      this.els.get(id)?.g.classList.add("hsd-dragging");
      this.els.get(id)?.g.classList.remove("hsd-slide-hover");
      hit.style.cursor = "grabbing";
      this.ensureTicking();
    });
    hit.addEventListener("pointermove", (ev) => {
      if (!this.dragState || this.dragState.id !== id || !this.lastLayout) return;
      const st = this.dragState;
      const s = this.stringById.get(id);
      const anim = this.anim.get(id);
      if (!s || !anim) return;
      const rect = st.rect;
      const scaleX = this.viewBoxWidth / rect.width;
      const pointerX = (ev.clientX - rect.left) * scaleX - this.contentOffsetX;
      const [min, max] = this.slideBoundsOf(s);
      if (s.parentId) {
        // D20 for children: slide by x-offset along the straight sub-rail, measured from the
        // parent's LIVE knob (the bar rides it). The tick loop turns dragPos into the actual
        // target every frame, so the child keeps riding the bar even while the parent swings.
        const parentAnim = this.anim.get(s.parentId);
        const parentKnobWorldX = parentAnim
          ? parentAnim.anchorX + parentAnim.nodes[N_NODES - 1].value
          : s.x;
        st.dragPos = clamp(pointerX - parentKnobWorldX, min, max);
      } else {
        // D20 for roots: the pointer's x inverts through the form into an `along` position,
        // and the anchor is the rail point THERE — on a curved rod the hanger visibly tracks
        // the rod's height as it slides, exactly like the ring's hanger around the ellipse.
        st.dragPos = clamp(this.lastLayout.railForm.alongAtX(pointerX), min, max);
        const anchor = this.lastLayout.railForm.anchorAt(st.dragPos);
        anim.targetX = anchor.x;
        anim.targetY = anchor.y;
      }
      this.ensureTicking();
    });
    const endDrag = (ev: PointerEvent) => {
      if (!this.dragState || this.dragState.id !== id) return;
      try {
        hit.releasePointerCapture(ev.pointerId);
      } catch {
        // ignore — capture may never have been granted (see pointerdown's guard above)
      }
      this.els.get(id)?.g.classList.remove("hsd-dragging");
      hit.style.cursor = "grab";
      const st = this.dragState;
      this.dragState = null;
      this.liveDragId = null;
      // D20: commit the exact position it was dropped at — it stays where it was slid and no
      // other string is repositioned. A plain click (position unchanged) commits nothing;
      // expand/collapse lives on the knob's own button (attachToggleInteractions).
      if (st.dragPos !== st.startPos) {
        this.options.onSlide?.(id, st.dragPos);
      }
      this.hideHoverCard();
      this.ensureTicking();
    };
    hit.addEventListener("pointerup", endDrag);
    hit.addEventListener("pointercancel", endDrag);
    // Capture can be lost without a pointerup ever reaching us (e.g. the element is torn out of
    // the DOM by a re-render mid-drag) — commit the drag where it currently is instead of
    // leaving it pinned to its drag target forever. Same guard as renderRing.ts.
    hit.addEventListener("lostpointercapture", endDrag);
    hit.addEventListener("keydown", (ev: KeyboardEvent) => {
      if (ev.key === "Enter" || ev.key === " ") {
        const s = this.stringById.get(id);
        if ((s?.category.children?.length ?? 0) > 0) {
          ev.preventDefault();
          this.options.onToggleExpand?.(id);
        }
        return;
      }
      if (ev.key !== "ArrowLeft" && ev.key !== "ArrowRight") return;
      ev.preventDefault();
      const s = this.stringById.get(id);
      if (!s) return;
      // D20: arrows nudge the string positionally along its rail (no slots), clamped like a drag.
      const [min, max] = this.slideBoundsOf(s);
      const nudged = clamp(
        this.restPositionOf(s) + (ev.key === "ArrowLeft" ? -ARROW_NUDGE_PX : ARROW_NUDGE_PX),
        min,
        max
      );
      this.options.onSlide?.(id, nudged);
    });
  }

  /** D16: the +/− knob button — a press here always toggles the branch and never starts a
   * slide (it sits above the lower-end drag hit). Up to 8px of hand jitter still counts as a
   * press; real movement beyond that cancels the toggle rather than turning into a surprise slide. */
  private attachToggleInteractions(knobHit: SVGCircleElement, id: string) {
    let press: { pointerId: number; startX: number; startY: number; cancelled: boolean } | null =
      null;
    const gOf = () => this.els.get(id)?.g;
    knobHit.addEventListener("pointerenter", () => {
      gOf()?.classList.add("hsd-expand-hover");
      gOf()?.classList.remove("hsd-slide-hover");
    });
    knobHit.addEventListener("pointerleave", () => {
      gOf()?.classList.remove("hsd-expand-hover", "hsd-expand-press");
    });
    knobHit.addEventListener("pointerdown", (ev) => {
      press = { pointerId: ev.pointerId, startX: ev.clientX, startY: ev.clientY, cancelled: false };
      gOf()?.classList.add("hsd-expand-press");
      try {
        knobHit.setPointerCapture(ev.pointerId);
      } catch {
        // ignore — see attachInteractions's identical guard
      }
    });
    knobHit.addEventListener("pointermove", (ev) => {
      if (!press || press.pointerId !== ev.pointerId) return;
      if (Math.abs(ev.clientX - press.startX) > 8 || Math.abs(ev.clientY - press.startY) > 8) {
        press.cancelled = true;
        gOf()?.classList.remove("hsd-expand-press");
      }
    });
    knobHit.addEventListener("pointerup", (ev) => {
      if (!press || press.pointerId !== ev.pointerId) return;
      try {
        knobHit.releasePointerCapture(ev.pointerId);
      } catch {
        // ignore
      }
      const ok = !press.cancelled;
      press = null;
      gOf()?.classList.remove("hsd-expand-press");
      if (ok) this.options.onToggleExpand?.(id);
    });
    knobHit.addEventListener("pointercancel", () => {
      press = null;
      gOf()?.classList.remove("hsd-expand-press");
    });
  }

  private showHoverCard(id: string) {
    const s = this.stringById.get(id);
    if (!s) return;
    // The card is HTML in the layer's LOCAL px while string positions are layout units —
    // under proportional display scaling (style.css .hsd-svg) the two differ by the svg's
    // rendered/layout ratio. clientWidth, not getBoundingClientRect: the card sits INSIDE
    // the D27 zoom layer, so its coordinates must stay untransformed (the layer's transform
    // then moves card and chart together).
    const localW = this.svg.clientWidth || this.svg.getBoundingClientRect().width;
    const localH = this.svg.clientHeight || this.svg.getBoundingClientRect().height;
    const displayScale = localW > 0 ? localW / this.viewBoxWidth : 1;
    const left = clamp(
      (this.contentOffsetX + s.x + 24) * displayScale,
      8,
      Math.max(8, localW - 170)
    );
    const top = clamp(
      (s.knobY + HANGER_DROP_OFFSET) * displayScale,
      8,
      Math.max(8, localH - 90)
    );

    // Q25: the host tooltip event — once per enter (not on the re-shows a drag can trigger).
    if (this.hoverId !== id) {
      this.hoverId = id;
      this.options.onHover?.({
        id,
        parentId: s.parentId ?? null,
        category: s.category,
        x: left,
        y: top,
      });
    }
    if (this.options.showHoverCard === false) return;
    const group = this.options.groups.find((g) => g.id === s.category.groupId);

    // Built with textContent (not innerHTML) so category/group names can never inject markup.
    this.hoverCard.textContent = "";
    const title = document.createElement("div");
    title.className = "hsd-hover-title";
    title.textContent = s.category.name;
    this.hoverCard.appendChild(title);
    const addRow = (label: string, val: string) => {
      const row = document.createElement("div");
      row.className = "hsd-hover-row";
      row.append(`${label}: `);
      const strong = document.createElement("strong");
      strong.textContent = val;
      row.appendChild(strong);
      this.hoverCard.appendChild(row);
    };
    addRow("Group", group?.name ?? "—");
    addRow("Value", String(s.category.value));
    if (typeof s.category.secondaryValue === "number") {
      addRow("2nd metric", s.category.secondaryValue.toFixed(1));
    }

    this.hoverCard.style.left = `${left}px`;
    this.hoverCard.style.top = `${top}px`;
    this.hoverCard.style.display = "block";
  }

  private hideHoverCard() {
    if (this.hoverId !== null) {
      this.hoverId = null;
      this.options.onHover?.(null);
    }
    this.hoverCard.style.display = "none";
  }
}
