/**
 * Second reference renderer (SVG), perspective-ring ("curtain") mode — D2's exploration/
 * aesthetic view. Consumes core/ringLayout.ts output; mirrors render.ts's per-string visual
 * vocabulary (thread/ticks/shadow/knob/label) and reuses its CSS classes so colors, D6 bead-
 * ticks, and D11 elevation shadows look identical across both rail modes for free.
 *
 * Phase 1 (geometry only) shipped static positions, no interactions. Phase 2 (Q12) added the two
 * candidate ring interactions — grab-and-slide a single string (`onReorder`) and spin the whole
 * ring (`onRotate`) — but as a discrete, un-eased jump. Per user feedback ("not realistic...
 * discreet without any transition"), this pass replaces both with the *exact same* D10 flexible-
 * string physics straight mode uses (`core/chain.ts`, shared, not reimplemented): every string
 * has a persistent 2D anchor (`anchorX`/`anchorY`, since its attachment point moves along an
 * ellipse rather than a straight rail) that eases toward its current slot, a cascading chain of
 * local-X node offsets that swings/settles behind it, and `onRotate` now reports a small
 * *continuous* angle delta every pointermove instead of a whole discrete slot on release — so
 * "spinning the ring" plays out as every string's anchor smoothly sliding around the ellipse,
 * with the string itself swinging with inertia, precisely like straight mode's reorder-and-settle
 * feel. Depth/scale/opacity are derived every frame from the *animated* anchor's current Y
 * position (`depthFromAnchorY`), not the resting layout, so a string visibly shrinks/fades as it
 * swings toward the back and grows/brightens as it swings toward the front — continuous, not a
 * pop at redraw time. Renders diff by category id (persistent DOM + anim state) instead of a
 * full rebuild every `render()` call, since physics needs somewhere to live between frames.
 * Rotate-drag deltas are coalesced to one layout+retarget per animation frame (a
 * 120 Hz pointer would otherwise re-layout faster than the display can show); the rotate
 * fast-path (`retargetForRotate`) skips color/label/aria rebuilds. The static compass ruler
 * is only rebuilt when the rail geometry itself changes.
 */

import type { HangingStringGroup } from "../../core/types";
import {
  depthFromAnchorY,
  pointOnRailEllipse,
  type RingLayoutResult,
  type RingStringLayout,
} from "../../core/ringLayout";
import { RingRailAssembly } from "./ringRail";
import { STUDIO_THEME, type HangingStringsDiagramTheme } from "../../core/theme";
import { createFillDef, createThreadPaintSource, type ThreadPaintSource, CAST_SHADOW_TRANSFORM } from "./theme";
import { nextInstanceUid } from "./uid";
import { breezeSignal, threadWindAccel } from "./backdrop";
import { heatmapColor, linearScale } from "../../core/scale";
import { setLabelContent } from "./labels";
import { setAttrIfChanged } from "./domAttr";
import type { StringHoverEvent } from "./hover";
import { DEFAULT_QUIPU_CONFIG, computeQuipuLayout } from "../../core/quipu";
import { buildQuipuLayer, type QuipuGlyphEl } from "./quipuGlyphs";
import {
  N_NODES,
  chainParamsForStiffness,
  clamp,
  morphAnchorEaseRate,
  createChainAnim,
  smoothPathThroughPoints,
  stepChainAnim,
  xAlongPolyline,
  type Point,
  type StringChainAnim,
} from "../../core/chain";
import { expandHitRadius, lowerEndHitGeometry } from "./stringHit";

const SVG_NS = "http://www.w3.org/2000/svg";

/** Above this string count, permanently disable per-thread/label drop-shadows (CSS .hsd-dense). */
const DENSE_STRING_THRESHOLD = 40;

/** Curtain-hanger ring geometry (D13) — a small loop "threaded" onto the rail at each string's
 * anchor, drawn as a vertically-elongated ellipse so it reads as a circular ring seen edge-on,
 * consistent with the rail's own perspective convention. The thread starts at its bottom edge
 * rather than exactly on the rail point, so the string visibly hangs *from* the hanger, not out
 * of the rail line itself. */
const HANGER_RING_RX = 3.5;
const HANGER_RING_RY = 7;
const HANGER_DROP_OFFSET = HANGER_RING_RY;

/** Inset of the vinyl plate inside the rail ellipse — separate X/Y so the visible gap band reads
 * even on the highly eccentric perspective ellipse (same px subtracted from both axes would look
 * much thicker top/bottom than left/right). The main ring's values; mini rings use the scaled-
 * down pair below (16px would swallow half a branch disc). */
const PLATE_GAP_RX = 16;
const PLATE_GAP_RY = 4;
const SUB_PLATE_GAP_RX = 4;
const SUB_PLATE_GAP_RY = 1;

/** D4 dimming factor for strings outside the active group — matches straight mode's
 * `.hsd-dimmed { opacity: 0.28 }`, but multiplied into the per-frame depth opacity here since
 * ring strings' opacity is animated inline every frame (a CSS class would be overridden). */
const DIMMED_OPACITY_FACTOR = 0.28;

/** Rotated rail labels overlap illegibly once a string is far enough back (small + faded + dense
 * near the ellipse's apex), so labels fade out entirely past a depth threshold — the front
 * labels are the ones D4's "bring group to front" is designed to make readable anyway. */
const LABEL_FADE_START_DEPTH = 0.45;
const LABEL_FADE_END_DEPTH = 0.7;

/** Element refs cached at creation time so neither `render()` nor the per-frame animation loop
 * ever has to `querySelector` back into the subtree it just built. */
interface StringEls {
  g: SVGGElement;
  hanger: SVGEllipseElement;
  /** D11.1 cast shadows: offset same-geometry copies of the thread and knob, thrown onto
   * whatever hangs behind (the breeze sheet above all). First children of the hang group so
   * everything real paints over them. */
  castThread: SVGPathElement;
  castKnob: SVGCircleElement;
  thread: SVGPathElement;
  ticksLayer: SVGGElement;
  /** The bead-ticks' y positions, mirrored into JS so the per-frame loop never reads attributes. */
  tickYs: number[];
  /** Cheap identity of the currently-built bead-ticks, to skip DOM rebuilds when unchanged. */
  tickSig: string;
  /** D28: the quipu knot layer + glyph groups for the per-frame sway-follow (see render.ts). */
  quipuLayer: SVGGElement;
  quipuEls: QuipuGlyphEl[];
  quipuSig: string;
  shadow: SVGEllipseElement;
  knob: SVGCircleElement;
  /** D16 branch affordance: a +/− glyph drawn on the knob of a string that has children. */
  glyph: SVGTextElement;
  label: SVGTextElement;
  hit: SVGRectElement;
  /** D16: dedicated toggle button over a branch knob — sits ON TOP of the drag hit rect so a
   * press on the +/− knob always toggles and can never fall through into a reorder/slide drag.
   * Hidden for leaf strings. Same pattern as straight mode's render.ts. */
  knobHit: SVGCircleElement;
  lastGTransform: string;
  lastHangerTransform: string;
  lastPathD: string;
}

export interface RingSvgRendererOptions {
  width: number;
  height: number;
  groups: HangingStringGroup[];
  colorMode: "group" | "heatmap";
  showTicks: boolean;
  /** Two-line labels (name / "(value)") — same option as straight mode's
   * `SvgRendererOptions.labelValues`. */
  labelValues: boolean;
  /** D28 (v4): render the 2nd metric as khipu knots on each cord — same option as straight
   * mode's `SvgRendererOptions.quipuKnots`. D6 bead-ticks hide while active (Q30). */
  quipuKnots?: boolean;
  /** String flexibility for the D10 swing (0 = floppy, 1 = near-rigid rod) — same option, same
   * physics, as straight mode's `SvgRendererOptions.stiffness`. */
  stiffness: number;
  /** Called with the *incremental* angle change (degrees) while spinning the ring (Q12b) —
   * continuous, not quantized to a slot. Deltas are accumulated across pointermoves and flushed
   * at most once per animation frame. The caller adds each delta to its own running rotation
   * offset and re-renders; there is nothing to "commit" on release since the state was never a
   * preview. */
  onRotate: (deltaDeg: number) => void;
  /** Fired once when the user grabs the vinyl plate to spin (Q12b) — before the first delta.
   * Caller can drop tick granularity etc. for the duration of the spin+settle. */
  onRotateGestureStart?: () => void;
  /** Fired once when the spin session settles: no disc grabbed and every rotation spring at
   * rest (threads may still swing — with ambient wind they always do, so waiting on them would
   * mean never firing). Used to restore temporary spin-time LOD changes. */
  onSettle?: () => void;
  /** D19: same contract as `onRotate`, for an expanded parent's mini ring — dragging a branch's
   * disc spins THAT branch's children around their sub-ring. The caller keeps one running
   * offset per parent id. */
  onSubRotate?: (parentId: string, deltaDeg: number) => void;
  /** D16: pressing a branch knob's +/− button (or Enter/Space on a focused parent) toggles its
   * sub-rail — shared expand state with straight mode lives in the caller. */
  onToggleExpand?: (id: string) => void;
  /** D17: called on release after sliding a string along ITS rail, with the angle (degrees,
   * INCLUDING that ring's current rotation offset) it was dropped at — the main rail for roots,
   * the branch's mini rim for children. The caller persists the base angle so the string stays
   * exactly where it was slid — no slots, no snapping, and no other string moves. */
  onSlide?: (id: string, angleDeg: number) => void;
  /** v2.5 T1: theme for the surfaces this renderer builds itself (today only the D13 plate's
   * <defs> gradient — everything else themes through style.css's --hsd-* variables, see
   * renderers/svg/theme.ts). Defaults to Studio, the pre-theming look. */
  theme?: HangingStringsDiagramTheme;
  /** Q25: fired with the hovered string's data on pointer enter and `null` on leave — for a
   * host's own tooltip. Independent of `showHoverCard`. */
  onHover?: (event: StringHoverEvent | null) => void;
  /** Q25: whether the built-in hover info card renders (default true) — hosts bringing their
   * own tooltip via `onHover` switch it off. */
  showHoverCard?: boolean;
}

export class RingSvgRenderer {
  private svg: SVGSVGElement;
  /** D19: the top-level ring's disc — plate, D18 arrows, rail, ruler, and the Q12b rotate
   * gesture, all bundled in the reusable RingRailAssembly (shared with the mini rings below). */
  private mainRail: RingRailAssembly;
  private hangerLayer: SVGGElement;
  private captionEl: SVGTextElement;
  private subRailLayer: SVGGElement;
  /** D16/D19: per-expanded-parent mini ring — the SAME RingRailAssembly as the main rail, at
   * branch scale, plus the sub-ring's unscaled dimensions. Geometry is re-derived from the
   * parent's live knob (position, sway, depth scale) every frame in applyTransform — the branch
   * hangs from the parent string, wherever it currently is. Diffed by parent id (not rebuilt
   * per render) so each mini disc's arrow-spring state survives re-renders mid-spin. */
  private subRailEls = new Map<
    string,
    { assembly: RingRailAssembly; radiusX: number; radiusY: number; gapPx: number }
  >();
  private stringLayer: SVGGElement;
  /** D26: all disc rotate hit-targets, stacked above the strings — inside a disc, the
   * pointer always turns that disc. */
  private railHitLayer: SVGGElement;
  /** Current canvas height — grows below options.height while branches are expanded (children
   * hang past the base canvas near the ring's front), returns to base when all are collapsed. */
  private effectiveHeight: number;
  private hoverCard: HTMLDivElement;
  private options: RingSvgRendererOptions;
  private activeGroupId: string | null = null;
  private lastLayout: RingLayoutResult | null = null;
  private stringById = new Map<string, RingStringLayout>();
  private radiusMin = 0;
  private radiusMax = 0;

  private stringEls = new Map<string, StringEls>();
  private anim = new Map<string, StringChainAnim>();
  private rafId: number | null = null;
  /** Q25: the currently hovered string (null = none) — dedupes onHover enter/leave firing. */
  private hoverId: string | null = null;
  /** D25 (Q13 morph): screen-px anchors handed over by the planar renderer at a rail-mode
   * switch — consumed by the next render() (see render.ts's twin for the mechanism). */
  private morphSeedScreen: Map<string, { x: number; y: number }> | null = null;
  private morphSeedLayout: Map<string, { x: number; y: number; rate: number }> | null = null;
  private morphTimer: ReturnType<typeof setTimeout> | null = null;
  /** D23: true while a disc-turn session runs (any disc grabbed, or rotation springs still
   * moving). ONLY this sheds detail (hsd-animating hides knots/floor-shadows, knot tracking
   * pauses) — breeze sway and single-thread pulls keep the full picture. */
  private spinActive = false;
  private lastFrameTime: number | null = null;
  private groupColorById = new Map<string, string>();
  private groupNameById = new Map<string, string>();

  /** Live single-string drag (D17) — set on pointerdown on a string's hit target, cleared on
   * release. Both levels slide by ANGLE along their own ring: roots on the main rail, children
   * on their branch's mini rim. A plain click (angle unchanged) commits nothing. */
  private dragState: {
    id: string;
    pointerId: number;
    rect: DOMRect;
    /** Previous pointermove's local X — slides accumulate incremental X deltas. */
    lastX: number;
    /** The angle (deg, incl. the ring's rotation offset) the anchor is currently slid to. */
    dragAngleDeg: number;
    startAngleDeg: number;
  } | null = null;
  private liveDragId: string | null = null;
  /** The svg's <defs> — kept so setTheme (T3) can rebuild the theme-derived plate fill. */
  private defs: SVGDefsElement;
  /** v2 photoreal: per-tint thread stroke paint (plain tint, or a textured yarn pattern when
   * the theme ships a thread texture) — see createThreadPaintSource. */
  private threadPaint: ThreadPaintSource;
  /** D21.2: whether the scene breeze also stirs the threads (same signal as the backdrop
   * sheet). While on and visible, the physics loop never parks — the air never goes still. */
  private windEnabled = true;
  /** D21.8: multiplies organic breeze intensity for threadWindAccel (shake envelope). */
  private windScale = 1;
  private windPhase = 0;
  private visible = true;

  /** Q23: document-unique prefix for this instance's SVG def ids (plate fill, thread
   * patterns) — url(#…) resolves document-wide, so ids must never repeat across instances. */
  private readonly uid = nextInstanceUid("hsd-ring");

  constructor(container: HTMLElement, options: RingSvgRendererOptions) {
    this.options = options;
    this.rebuildGroupMaps();
    this.effectiveHeight = options.height;

    this.svg = document.createElementNS(SVG_NS, "svg");
    this.svg.setAttribute("width", String(options.width));
    this.svg.setAttribute("height", String(options.height));
    this.svg.setAttribute("viewBox", `0 0 ${options.width} ${options.height}`);
    this.svg.setAttribute("role", "img");
    this.svg.setAttribute("aria-label", "Hanging Strings Diagram, ring rail");
    this.svg.classList.add("hsd-svg");

    // T1/T2: the plate's paint is the one surface this renderer materializes from theme data
    // itself (CSS can't express SVG gradient/pattern defs) — style.css's .hsd-rail-plate reads
    // var(--hsd-plate-fill), which this svg points at ITS OWN def (Q23: the id is per-instance,
    // so two ring charts themed differently each keep their plate), a gradient or a T2 pattern
    // depending on the theme, for the main disc and every D19 mini disc alike. Rebuilt by
    // setTheme (T3 live switching).
    this.defs = document.createElementNS(SVG_NS, "defs");
    this.defs.appendChild(
      createFillDef(this.plateFillId, (options.theme ?? STUDIO_THEME).plate.fill)
    );
    this.svg.style.setProperty("--hsd-plate-fill", `url(#${this.plateFillId})`);
    this.svg.appendChild(this.defs);
    this.threadPaint = createThreadPaintSource(this.defs, `${this.uid}-yarn`);
    this.threadPaint.setTexture((options.theme ?? STUDIO_THEME).thread.texture);

    // Stacking order (back to front): the disc's back half (vinyl plate + D18 arrows), hanger
    // rings, the disc's front half (rail + D13 ruler + rotate hit target), then strings. Two
    // placeholder groups let the hangers slot between the assembly's own layers.
    const railBack = document.createElementNS(SVG_NS, "g");
    this.svg.appendChild(railBack);

    this.hangerLayer = document.createElementNS(SVG_NS, "g");
    this.hangerLayer.setAttribute("class", "hsd-hangers");
    this.svg.appendChild(this.hangerLayer);

    const railFront = document.createElementNS(SVG_NS, "g");
    this.svg.appendChild(railFront);

    // D26 (usability): the discs' rotate hit-targets live in ONE layer stacked ABOVE the
    // strings (appended after stringLayer below) — anywhere inside a disc, the pointer turns
    // that disc and nothing else. Strings crossing a disc's interior (back-rim strings hang
    // straight through it) are grabbable only outside the discs.
    this.railHitLayer = document.createElementNS(SVG_NS, "g");
    this.railHitLayer.setAttribute("class", "hsd-rail-hits");

    // D19: the whole disc — plate, spin arrows, rail, compass ruler, and the Q12b "grab the
    // disc to spin the ring" gesture — is one reusable assembly, shared with the mini rings.
    this.mainRail = new RingRailAssembly(
      this.svg,
      railBack,
      railFront,
      {
        showRuler: true,
        plateGapRx: PLATE_GAP_RX,
        plateGapRy: PLATE_GAP_RY,
        onRotate: (deltaDeg) => this.options.onRotate(deltaDeg),
        onRotateGestureStart: () => this.options.onRotateGestureStart?.(),
        onInteraction: () => this.ensureTicking(),
      },
      this.railHitLayer
    );

    // D6 sub-detail: what one bead is worth — same caption as straight mode.
    this.captionEl = document.createElementNS(SVG_NS, "text");
    this.captionEl.setAttribute("class", "hsd-tick-caption");
    this.captionEl.setAttribute("x", "8");
    this.captionEl.setAttribute("y", "16");
    this.svg.appendChild(this.captionEl);

    // D16 sub-rails render between the rail furniture and the strings, same stacking as
    // straight mode: the rod sits behind the strings that hang from it.
    this.subRailLayer = document.createElementNS(SVG_NS, "g");
    this.subRailLayer.setAttribute("class", "hsd-subrails");
    this.svg.appendChild(this.subRailLayer);

    this.stringLayer = document.createElementNS(SVG_NS, "g");
    this.svg.appendChild(this.stringLayer);

    // D26: on top of the strings — see the note at railHitLayer's creation above.
    this.svg.appendChild(this.railHitLayer);

    container.appendChild(this.svg);

    this.hoverCard = document.createElement("div");
    this.hoverCard.className = "hsd-hover-card";
    this.hoverCard.style.display = "none";
    // Same rule as render.ts: give the card a positioned ancestor, but never overwrite the
    // positioning an adapter's overlay host already chose.
    if (getComputedStyle(container).position === "static") {
      container.style.position = "relative";
    }
    container.appendChild(this.hoverCard);

    // Heal stale string drags: one pointer cannot press twice, so a NEW pointerdown carrying
    // the same pointerId proves the previous drag's pointerup was lost (capture failure,
    // element torn out mid-drag, …). Left in place, a stale drag pins its string to the drag
    // target forever — it stops rotating/swinging with the ring and can't be re-grabbed.
    // Capture phase, so it runs before any target handler starts the new drag.
    this.svg.addEventListener(
      "pointerdown",
      (ev) => {
        if (this.dragState && this.dragState.pointerId === ev.pointerId) {
          this.stringEls.get(this.dragState.id)?.g.classList.remove("hsd-dragging");
          this.dragState = null;
          this.liveDragId = null;
        }
      },
      true
    );
  }

  /** True while ANY disc (main or a branch's mini ring) has a live rotate drag. */
  private anyRailDragging(): boolean {
    if (this.mainRail.isDragging) return true;
    for (const sub of this.subRailEls.values()) {
      if (sub.assembly.isDragging) return true;
    }
    return false;
  }

  setOptions(patch: Partial<RingSvgRendererOptions>) {
    const groupsChanged = patch.groups !== undefined;
    this.options = { ...this.options, ...patch };
    if (groupsChanged) this.rebuildGroupMaps();
  }

  private rebuildGroupMaps() {
    this.groupColorById = new Map(this.options.groups.map((g) => [g.id, g.color]));
    this.groupNameById = new Map(this.options.groups.map((g) => [g.id, g.name]));
  }

  /** T3 live theme switching: everything else themes through CSS variables (applyTheme), but
   * the plate fill and (v2 photoreal) the per-tint thread patterns are SVG defs built from
   * theme data — rebuild them in place. The plate def keeps its id, so every .hsd-rail-plate
   * url() reference (main disc + D19 mini discs) repaints without per-element work; thread
   * strokes are re-resolved by the re-render below, mid-spin state untouched. */
  setTheme(theme: HangingStringsDiagramTheme) {
    this.options = { ...this.options, theme };
    this.defs.textContent = "";
    this.defs.appendChild(createFillDef(this.plateFillId, theme.plate.fill));
    this.threadPaint.setTexture(theme.thread.texture);
    if (this.lastLayout) this.render(this.lastLayout);
  }

  /** Q23: this instance's plate-fill def id — referenced only via this svg's own
   * --hsd-plate-fill variable. */
  private get plateFillId(): string {
    return `${this.uid}-plate-fill`;
  }

  /** Shows/hides this renderer's DOM without tearing it down — mirrors SvgRenderer.setVisible so
   * main.ts can toggle rail modes uniformly, and so this renderer's own D10 spring state survives
   * a round trip through straight mode. */
  setVisible(visible: boolean) {
    this.visible = visible;
    this.svg.style.display = visible ? "" : "none";
    if (!visible) this.hoverCard.style.display = "none";
    else this.ensureTicking(); // resume the breeze (the loop parks while hidden)
  }

  /** D21.2: the scene breeze stirring the threads — tied to the backdrop's toggle. */
  setWind(on: boolean) {
    this.windEnabled = on;
    if (on) this.ensureTicking();
  }

  /** D21.8: multiplies breeze intensity applied to threads (default 1). */
  setWindScale(scale: number) {
    this.windScale = Number.isFinite(scale) ? Math.max(0, scale) : 0;
  }

  /** D25 (Q13 morph): every string's CURRENT animated anchor in screen px relative to the
   * svg's top-left — the hand-off space shared with the planar renderer. */
  captureAnchorScreenPositions(): Map<string, { x: number; y: number }> {
    const out = new Map<string, { x: number; y: number }>();
    const rect = this.svg.getBoundingClientRect();
    if (!(rect.width > 0)) return out;
    const scale = rect.width / this.options.width;
    for (const [id, anim] of this.anim) {
      out.set(id, { x: anim.anchorX * scale, y: anim.anchorY * scale });
    }
    return out;
  }

  /** D25: the incoming half of the hand-off — see render.ts's twin. */
  seedAnchorScreenPositions(seed: Map<string, { x: number; y: number }>): void {
    this.morphSeedScreen = seed;
  }

  /** D25 cross-fade, outgoing side — see render.ts's twin. */
  morphOut(durationMs: number): void {
    if (this.morphTimer !== null) clearTimeout(this.morphTimer);
    const svg = this.svg;
    svg.classList.add("hsd-morphing", "hsd-morph-ghost");
    svg.style.opacity = "1";
    requestAnimationFrame(() => {
      svg.style.opacity = "0";
    });
    this.morphTimer = setTimeout(() => {
      this.morphTimer = null;
      svg.classList.remove("hsd-morphing", "hsd-morph-ghost");
      svg.style.opacity = "";
      this.setVisible(false);
    }, durationMs);
  }

  /** D25 cross-fade, incoming side — see render.ts's twin. */
  morphIn(durationMs: number): void {
    if (this.morphTimer !== null) clearTimeout(this.morphTimer);
    const svg = this.svg;
    svg.classList.remove("hsd-morph-ghost");
    svg.classList.add("hsd-morphing");
    svg.style.opacity = "0";
    this.setVisible(true);
    requestAnimationFrame(() => {
      svg.style.opacity = "1";
    });
    this.morphTimer = setTimeout(() => {
      this.morphTimer = null;
      svg.classList.remove("hsd-morphing");
      svg.style.opacity = "";
    }, durationMs);
  }

  /** Tears this renderer's DOM out of the container and stops its animation loop — the façade's
   * destroy() path (integration I4). The instance must not be used afterwards. */
  destroy() {
    if (this.rafId !== null) cancelAnimationFrame(this.rafId);
    this.rafId = null;
    this.svg.remove();
    this.hoverCard.remove();
  }

  /** Adopts a new canvas width (responsive sizing) — the caller updates the RingConfig geometry
   * and re-runs layout + render after. */
  resize(width: number) {
    this.options.width = width;
    this.applyCanvasSize();
  }

  private applyCanvasSize() {
    this.svg.setAttribute("width", String(this.options.width));
    this.svg.setAttribute("height", String(this.effectiveHeight));
    this.svg.setAttribute("viewBox", `0 0 ${this.options.width} ${this.effectiveHeight}`);
  }

  /** D4 parity with straight mode: dims strings outside the active group (multiplied into the
   * per-frame depth opacity, since ring strings animate opacity inline every frame). */
  setActiveGroup(groupId: string | null) {
    this.activeGroupId = groupId;
    if (this.lastLayout) this.render(this.lastLayout);
  }

  render(layout: RingLayoutResult) {
    // D25: convert the morph hand-off (screen px) into layout coords, with each string's
    // sweep chase rate — see render.ts's twin.
    if (this.morphSeedScreen) {
      const rect = this.svg.getBoundingClientRect();
      if (rect.width > 0) {
        const toLayout = this.options.width / rect.width;
        const orderIndex = new Map(layout.strings.map((s, i) => [s.category.id, i]));
        const lastIndex = Math.max(1, layout.strings.length - 1);
        this.morphSeedLayout = new Map(
          [...this.morphSeedScreen].map(([id, p]) => [
            id,
            {
              x: p.x * toLayout,
              y: p.y * toLayout,
              rate: morphAnchorEaseRate((orderIndex.get(id) ?? 0) / lastIndex),
            },
          ])
        );
      }
      this.morphSeedScreen = null;
    }

    this.lastLayout = layout;
    this.stringById = new Map(layout.strings.map((s) => [s.category.id, s]));
    const radii = layout.strings.map((s) => s.knobRadius);
    this.radiusMin = radii.length ? Math.min(...radii) : 0;
    this.radiusMax = radii.length ? Math.max(...radii) : 0;
    const { config } = layout;

    // D19: the disc assembly gets the rail geometry (plate/arrows/rail/ruler all derive from
    // it) and the rotation target for its arrow spring.
    this.mainRail.setGeometry(
      {
        centerX: config.centerX,
        centerY: config.centerY,
        radiusX: config.radiusX,
        radiusY: config.radiusY,
      },
      config
    );
    this.mainRail.setTargetRotation(config.rotationOffsetDeg);

    this.captionEl.textContent = `· 1 knot = ${layout.tickStepValue}`;
    this.captionEl.style.display = this.options.showTicks ? "" : "none";

    // D16: grow the canvas while expanded branches hang past the base height; shrink back once
    // everything is collapsed (same behavior as straight mode).
    const desiredHeight = Math.max(this.options.height, Math.ceil(layout.contentHeight ?? 0));
    if (desiredHeight !== this.effectiveHeight) {
      this.effectiveHeight = desiredHeight;
      this.applyCanvasSize();
    }

    // D16/D19 sub-rails: one full disc assembly per expanded parent — diffed by parent id (like
    // strings) so a mini ring's arrow-spring state and live rotate drag survive the re-renders
    // its own spinning triggers. Geometry is set every frame from the parent's live knob in
    // applyTransform — nothing to position here.
    const seenRails = new Set<string>();
    for (const rail of layout.subRails ?? []) {
      seenRails.add(rail.parentId);
      let entry = this.subRailEls.get(rail.parentId);
      if (!entry) {
        const parentId = rail.parentId;
        entry = {
          assembly: new RingRailAssembly(
            this.svg,
            this.subRailLayer,
            this.subRailLayer,
            {
              showRuler: false, // sub-pixel noise at branch scale
              plateGapRx: SUB_PLATE_GAP_RX,
              plateGapRy: SUB_PLATE_GAP_RY,
              onRotate: (deltaDeg) => this.options.onSubRotate?.(parentId, deltaDeg),
              onInteraction: () => this.ensureTicking(),
            },
            this.railHitLayer // D26: mini discs win inside their interiors too
          ),
          radiusX: rail.radiusX,
          radiusY: rail.radiusY,
          gapPx: rail.gapPx,
        };
        this.subRailEls.set(parentId, entry);
      } else {
        entry.radiusX = rail.radiusX;
        entry.radiusY = rail.radiusY;
        entry.gapPx = rail.gapPx;
      }
      entry.assembly.setTargetRotation(rail.rotationDeg);
    }
    for (const [id, entry] of this.subRailEls) {
      if (!seenRails.has(id)) {
        entry.assembly.dispose();
        this.subRailEls.delete(id);
      }
    }

    const secondaryValues = layout.strings
      .map((s) => s.category.secondaryValue)
      .filter((v): v is number => typeof v === "number");
    const secondaryDomain: [number, number] =
      secondaryValues.length > 0
        ? [Math.min(...secondaryValues), Math.max(...secondaryValues)]
        : [0, 1];
    const heatT = linearScale(secondaryDomain, [0, 1]);

    // Diffed by category id (persistent DOM + anim state) so the D10 physics has continuity to
    // animate from, instead of Phase 1's full rebuild every call.
    const seenIds = new Set<string>();
    for (const s of layout.strings) {
      seenIds.add(s.category.id);
      let els = this.stringEls.get(s.category.id);
      if (!els) {
        els = this.createStringElement(s.category.id);
        this.stringEls.set(s.category.id, els);
        this.hangerLayer.appendChild(els.hanger);
        this.stringLayer.appendChild(els.g);
      }
      this.updateStringElement(els, s, heatT);
    }
    for (const [id, els] of this.stringEls) {
      if (!seenIds.has(id)) {
        els.g.remove();
        els.hanger.remove();
        this.stringEls.delete(id);
        this.anim.delete(id);
      }
    }
    this.morphSeedLayout = null; // one-shot: consumed by the pass above
    this.ensureTicking();
    this.svg.classList.toggle("hsd-dense", layout.strings.length >= DENSE_STRING_THRESHOLD);
  }

  /**
   * Rotate fast-path: retarget root anchors + the disc's arrow spring from a fresh layout.
   * Skips color/label/aria/tick rebuilds — those don't change while spinning. Children chase
   * parents in the tick loop. Called from onRotate (already inside RAF) so applyTransform runs
   * once via the continuing tick.
   */
  retargetForRotate(layout: RingLayoutResult) {
    this.lastLayout = layout;
    this.stringById = new Map(layout.strings.map((s) => [s.category.id, s]));
    // D18: keep the plate arrows chasing the live rotation offset. Full render() used to do
    // this; without it here the spin fast-path leaves arrows frozen at the last full render.
    this.mainRail.setTargetRotation(layout.config.rotationOffsetDeg);
    for (const s of layout.strings) {
      if (s.parentId || s.category.id === this.liveDragId) continue;
      const anim = this.anim.get(s.category.id);
      if (!anim) continue;
      anim.targetX = s.anchorX;
      anim.targetY = s.anchorY;
    }
    this.ensureTicking();
  }

  private createStringElement(id: string): StringEls {
    const hanger = document.createElementNS(SVG_NS, "ellipse");
    hanger.setAttribute("class", "hsd-string-hanger");
    hanger.setAttribute("rx", String(HANGER_RING_RX));
    hanger.setAttribute("ry", String(HANGER_RING_RY));

    const g = document.createElementNS(SVG_NS, "g");
    g.setAttribute("class", "hsd-string hsd-string-ring");
    g.dataset.id = id;

    // Everything that hangs (thread/ticks/knob/label) starts below the curtain-hanger ring's
    // bottom edge (D13) so the string visibly hangs *from* the hanger rather than sprouting out
    // of the rail line.
    const hang = document.createElementNS(SVG_NS, "g");
    hang.setAttribute("transform", `translate(0 ${HANGER_DROP_OFFSET})`);
    g.appendChild(hang);

    // D11.1: the cast shadows go in FIRST — beneath the thread, ticks, knob and label — and
    // carry the scene light's fixed offset; per frame they just mirror the thread's d / knob's
    // cx, so the shadow swings with the string at no filter cost.
    const castThread = document.createElementNS(SVG_NS, "path");
    castThread.setAttribute("class", "hsd-thread-cast");
    castThread.setAttribute("transform", CAST_SHADOW_TRANSFORM);
    hang.appendChild(castThread);

    const castKnob = document.createElementNS(SVG_NS, "circle");
    castKnob.setAttribute("class", "hsd-knob-cast");
    castKnob.setAttribute("transform", CAST_SHADOW_TRANSFORM);
    hang.appendChild(castKnob);

    const thread = document.createElementNS(SVG_NS, "path");
    thread.setAttribute("class", "hsd-thread");
    thread.setAttribute("fill", "none");
    hang.appendChild(thread);

    const ticksLayer = document.createElementNS(SVG_NS, "g");
    ticksLayer.setAttribute("class", "hsd-ticks");
    hang.appendChild(ticksLayer);

    // D28: quipu knots paint over the thread exactly like the bead-ticks they replace.
    const quipuLayer = document.createElementNS(SVG_NS, "g");
    quipuLayer.setAttribute("class", "hsd-quipu");
    hang.appendChild(quipuLayer);

    const shadow = document.createElementNS(SVG_NS, "ellipse");
    shadow.setAttribute("class", "hsd-shadow");
    shadow.setAttribute("rx", "10");
    shadow.setAttribute("ry", "3");
    hang.appendChild(shadow);

    const knob = document.createElementNS(SVG_NS, "circle");
    knob.setAttribute("class", "hsd-knob");
    hang.appendChild(knob);

    const glyph = document.createElementNS(SVG_NS, "text");
    glyph.setAttribute("class", "hsd-expand-glyph");
    hang.appendChild(glyph);

    const label = document.createElementNS(SVG_NS, "text");
    label.setAttribute("class", "hsd-label");
    hang.appendChild(label);

    // Q12a / D30: grab-and-slide hit hugs the lower weight only (not the full cord).
    const hit = document.createElementNS(SVG_NS, "rect");
    hit.setAttribute("class", "hsd-hit");
    hit.setAttribute("x", "-18");
    hang.appendChild(hit);
    this.attachStringInteractions(hit, id);

    const knobHit = document.createElementNS(SVG_NS, "circle");
    knobHit.setAttribute("class", "hsd-knob-hit");
    knobHit.setAttribute("aria-hidden", "true");
    knobHit.style.display = "none";
    hang.appendChild(knobHit);
    this.attachToggleInteractions(knobHit, id);

    return {
      g,
      hanger,
      castThread,
      castKnob,
      thread,
      ticksLayer,
      tickYs: [],
      tickSig: "",
      quipuLayer,
      quipuEls: [],
      quipuSig: "",
      shadow,
      knob,
      glyph,
      label,
      hit,
      knobHit,
      lastGTransform: "",
      lastHangerTransform: "",
      lastPathD: "",
    };
  }

  /** D16: the +/− knob button — a press here always toggles the branch and never starts a
   * slide (it sits above the lower-end drag hit). Same slop-and-cancel behavior as straight
   * mode: up to 8px of hand jitter still counts as a press; real movement beyond that cancels
   * the toggle rather than turning into a surprise drag. */
  private attachToggleInteractions(knobHit: SVGCircleElement, id: string) {
    let press: { pointerId: number; startX: number; startY: number; cancelled: boolean } | null =
      null;
    const gOf = () => this.stringEls.get(id)?.g;
    knobHit.addEventListener("pointerenter", () => {
      gOf()?.classList.add("hsd-expand-hover");
      gOf()?.classList.remove("hsd-slide-hover");
    });
    knobHit.addEventListener("pointerleave", () => {
      gOf()?.classList.remove("hsd-expand-hover", "hsd-expand-press");
    });
    knobHit.addEventListener("pointerdown", (ev) => {
      press = { pointerId: ev.pointerId, startX: ev.clientX, startY: ev.clientY, cancelled: false };
      gOf()?.classList.add("hsd-expand-press");
      try {
        knobHit.setPointerCapture(ev.pointerId);
      } catch {
        // ignore — see ringRail.ts's rotate pointerdown for the identical guard's rationale
      }
    });
    knobHit.addEventListener("pointermove", (ev) => {
      if (!press || press.pointerId !== ev.pointerId) return;
      if (Math.abs(ev.clientX - press.startX) > 8 || Math.abs(ev.clientY - press.startY) > 8) {
        press.cancelled = true;
        gOf()?.classList.remove("hsd-expand-press");
      }
    });
    knobHit.addEventListener("pointerup", (ev) => {
      if (!press || press.pointerId !== ev.pointerId) return;
      try {
        knobHit.releasePointerCapture(ev.pointerId);
      } catch {
        // ignore
      }
      const ok = !press.cancelled;
      press = null;
      gOf()?.classList.remove("hsd-expand-press");
      if (ok) this.options.onToggleExpand?.(id);
    });
    knobHit.addEventListener("pointercancel", () => {
      press = null;
      gOf()?.classList.remove("hsd-expand-press");
    });
  }

  private updateStringElement(els: StringEls, s: RingStringLayout, heatT: (v: number) => number) {
    const color = this.colorFor(s, heatT);
    const wasTicking = this.rafId !== null;

    let anim = this.anim.get(s.category.id);
    if (!anim) {
      // D16: a child appearing on expand spawns at its parent's live knob and swings out to its
      // slot — the "unfurl" comes free from the shared chain physics, same as straight mode.
      const spawn = s.parentId ? this.parentKnobWorld(s.parentId) : null;
      anim = createChainAnim(spawn?.x ?? s.anchorX, spawn?.y ?? s.anchorY);
      anim.targetX = s.anchorX;
      anim.targetY = s.anchorY;
      this.anim.set(s.category.id, anim);
    } else if (s.category.id !== this.liveDragId && !s.parentId) {
      // Never retarget the string currently being dragged — a mid-drag preview render must move
      // its *neighbors*, not yank the grabbed string off the pointer. Children are excluded too:
      // their targets chase the parent's live knob every frame in the tick loop instead of the
      // resting layout anchor set here.
      anim.targetX = s.anchorX;
      anim.targetY = s.anchorY;
    }
    // D25: a rail-mode morph starts this string's spring where it sat in the planar renderer,
    // gliding over at its sweep chase rate (self-clearing, see core/chain.ts).
    const morphFrom = this.morphSeedLayout?.get(s.category.id);
    if (morphFrom) {
      anim.anchorX = morphFrom.x;
      anim.anchorY = morphFrom.y;
      anim.anchorEaseRate = morphFrom.rate;
    }

    setAttrIfChanged(els.thread, "stroke", this.threadPaint.paintFor(color));

    // Q30: quipu mode owns the cord's knot vocabulary — the D6 bead-ticks yield while it's on.
    const quipuOn = this.options.quipuKnots === true;
    els.ticksLayer.style.display = this.options.showTicks && !quipuOn ? "" : "none";
    els.quipuLayer.style.display = quipuOn ? "" : "none";
    // D6.1: the scale marks are KNOTS tied in the thread — ellipse bulges filled with the
    // thread's OWN paint (data tint, or the rope texture: both live in the same local frame,
    // so the pattern runs continuously through the knot like a knot tied in the same rope).
    // Sized off the theme's thread width — a fat rope gets a fat knot; the faint themable
    // edge (--hsd-tick-stroke) is what keeps the bulge readable against the straight run.
    // Paint and size join the rebuild signature so theme/texture/color-mode switches restyle.
    const tickPaint = this.threadPaint.paintFor(color);
    const knotRx = Math.max(2.6, (this.options.theme ?? STUDIO_THEME).thread.strokeWidth * 0.85);
    const tickSig = `${tickPaint}|${knotRx}|${s.ticks.map((t) => t.y.toFixed(2)).join(",")}`;
    if (tickSig !== els.tickSig) {
      els.tickSig = tickSig;
      els.tickYs = s.ticks.map((t) => t.y);
      els.ticksLayer.textContent = "";
      for (const tick of s.ticks) {
        const knot = document.createElementNS(SVG_NS, "ellipse");
        knot.setAttribute("class", "hsd-tick");
        knot.setAttribute("cy", String(tick.y));
        knot.setAttribute("rx", String(knotRx));
        knot.setAttribute("ry", String(knotRx * 0.72));
        knot.style.fill = tickPaint;
        els.ticksLayer.appendChild(knot);
      }
    }

    // D28: quipu glyphs — dropPx here is the UNSCALED value-true drop (D1); the group's depth
    // scale transform shrinks the whole knot set with the string, so back-rim cords keep
    // correct (smaller) knots for free.
    if (quipuOn) {
      const qLayout = computeQuipuLayout(s.category.secondaryValue, s.dropPx);
      const sw = (this.options.theme ?? STUDIO_THEME).thread.strokeWidth;
      const qSig = `${tickPaint}|${sw}|${s.dropPx.toFixed(1)}|${qLayout.mode}|${qLayout.digits.join("")}|${qLayout.bucketUnit ?? ""}`;
      if (qSig !== els.quipuSig) {
        els.quipuSig = qSig;
        els.quipuEls = buildQuipuLayer(
          els.quipuLayer,
          qLayout,
          s.dropPx,
          tickPaint,
          sw,
          DEFAULT_QUIPU_CONFIG
        );
      }
    } else if (els.quipuSig !== "") {
      els.quipuSig = "";
      els.quipuEls = [];
      els.quipuLayer.textContent = "";
    }

    setAttrIfChanged(els.shadow, "cy", String(s.dropPx + s.knobRadius * 0.9));

    setAttrIfChanged(els.knob, "cy", String(s.dropPx));
    setAttrIfChanged(els.knob, "r", String(s.knobRadius));
    setAttrIfChanged(els.castKnob, "cy", String(s.dropPx));
    setAttrIfChanged(els.castKnob, "r", String(s.knobRadius));
    setAttrIfChanged(els.knob, "fill", color);

    // D16 affordances, mirroring straight mode: dark-ringed knob + a +/− glyph on parents, and
    // the dedicated knob toggle button (never part of the drag surface).
    const childCount = s.category.children?.length ?? 0;
    const isExpanded = this.lastLayout?.subRails?.some((r) => r.parentId === s.category.id) ?? false;
    els.knob.classList.toggle("hsd-knob-branch", childCount > 0);
    els.g.classList.toggle("hsd-expanded", isExpanded);
    const glyphText = childCount > 0 ? (isExpanded ? "−" : "+") : "";
    if (els.glyph.textContent !== glyphText) els.glyph.textContent = glyphText;
    setAttrIfChanged(els.glyph, "y", String(s.dropPx));
    setAttrIfChanged(els.glyph, "font-size", String(Math.max(9, s.knobRadius * 1.7)));
    els.knobHit.style.display = childCount > 0 ? "" : "none";
    setAttrIfChanged(els.knobHit, "r", String(expandHitRadius(s.knobRadius)));
    setAttrIfChanged(els.knobHit, "cy", String(s.dropPx));
    setAttrIfChanged(
      els.knobHit,
      "aria-label",
      childCount > 0
        ? `${isExpanded ? "Collapse" : "Expand"} ${s.category.name}`
        : ""
    );

    // D9.1 (user, 2026-07-15): ALL labels ride their knob at the string's BOTTOM — option C
    // replaces the rotated rail-tag (B); the hover card (D) is unchanged. One convention for
    // roots and children; the rail line stays clean for the D13 hangers.
    const isChild = Boolean(s.parentId);
    els.label.classList.toggle("hsd-label-child", isChild);
    setAttrIfChanged(els.label, "x", "0");
    setAttrIfChanged(els.label, "y", "0");
    setLabelContent(els.label, s.category, this.options.labelValues, 0);

    // D30: grab-to-slide only at the lower weight (upper cord / mini-disc stay free of slides).
    const hitGeo = lowerEndHitGeometry(s.dropPx, s.knobRadius);
    setAttrIfChanged(els.hit, "x", String(hitGeo.x));
    setAttrIfChanged(els.hit, "y", String(hitGeo.y));
    setAttrIfChanged(els.hit, "width", String(hitGeo.width));
    setAttrIfChanged(els.hit, "height", String(hitGeo.height));
    els.hit.style.cursor = "grab";
    setAttrIfChanged(els.hit, "tabindex", "0");
    setAttrIfChanged(els.hit, "role", "button");
    const groupName = this.groupNameById.get(s.category.groupId);
    const childHint =
      childCount > 0
        ? `, ${childCount} children — press the +/− on the weight to ${isExpanded ? "collapse" : "expand"}`
        : "";
    setAttrIfChanged(
      els.hit,
      "aria-label",
      `${s.category.name}, value ${s.category.value}${groupName ? `, group ${groupName}` : ""}${childHint}. Drag the weight to slide along the ${isChild ? "branch ring" : "rail"}.`
    );

    // Skip duplicate pose when RAF is already running (tick will applyTransform).
    if (!wasTicking) this.applyTransform(els, anim, s);
  }

  /**
   * Positions everything from the current animation state. Depth (scale/opacity) is derived
   * fresh every frame from the anchor's *current* (animated, possibly mid-swing) Y position via
   * `depthFromAnchorY` — not the resting layout's precomputed scale/opacity — so a string
   * visibly grows/brightens as it swings toward the front and shrinks/fades as it swings toward
   * the back, instead of popping to its new size only once the swing settles.
   */
  /**
   * D16: depth for a string — children inherit their PARENT's live depth (the whole branch
   * lives at the parent's position on the ring), never derive their own: a child's anchor sits
   * far below the ellipse, where `depthFromAnchorY` would just clamp to "front". D16.1: a
   * child's own angle around its mini ring composes a static local multiplier on top (computed
   * in layout), so back-of-the-mini-ring children read slightly farther than front ones.
   */
  private depthFor(
    s: RingStringLayout,
    anim: StringChainAnim
  ): { depthT: number; scale: number; opacity: number } {
    const config = this.lastLayout?.config;
    if (!config) return { depthT: 0, scale: 1, opacity: 1 };
    const parentAnim = s.parentId ? this.anim.get(s.parentId) : undefined;
    const depth = depthFromAnchorY(parentAnim ? parentAnim.anchorY : anim.anchorY, config);
    if (!s.parentId) return depth;
    return {
      depthT: depth.depthT,
      scale: depth.scale * (s.localScale ?? 1),
      opacity: depth.opacity * (s.localOpacity ?? 1),
    };
  }

  /**
   * D16: the parent's knob in world coordinates, from its LIVE animation state (anchor position,
   * chain sway, depth scale) — the point the whole branch hangs from, recomputed every frame so
   * the sub-rail and children ride along as the parent slides around the arc or is dragged.
   */
  private parentKnobWorld(parentId: string): { x: number; y: number; scale: number } | null {
    const pAnim = this.anim.get(parentId);
    const pS = this.stringById.get(parentId);
    const config = this.lastLayout?.config;
    if (!pAnim || !pS || !config) return null;
    const { scale } = depthFromAnchorY(pAnim.anchorY, config);
    return {
      x: pAnim.anchorX + pAnim.nodes[N_NODES - 1].value * scale,
      y: pAnim.anchorY + (HANGER_DROP_OFFSET + pS.dropPx) * scale,
      scale,
    };
  }

  /** D16: where a child's anchor should be right now, relative to its parent's live knob.
   * D16.1: the point sits ON the sub-ring ellipse — the resting slot offsets from layout, or,
   * while the child is being DRAGGED (D17-for-children), the point at its live drag angle: the
   * hanger slides around the mini rail's rim and never detaches from it. */
  private childTargetWorld(
    s: RingStringLayout,
    liveDragAngleDeg?: number
  ): { x: number; y: number } | null {
    if (!s.parentId) return null;
    const knob = this.parentKnobWorld(s.parentId);
    const sub = this.subRailEls.get(s.parentId);
    if (!knob || !sub) return null;
    if (liveDragAngleDeg === undefined) {
      return {
        x: knob.x + (s.slotOffsetX ?? 0) * knob.scale,
        y: knob.y + (s.slotOffsetY ?? sub.gapPx) * knob.scale,
      };
    }
    // Same sin-for-X / cos-for-Y projection as the layout's resting slot points.
    const rad = (liveDragAngleDeg * Math.PI) / 180;
    return {
      x: knob.x + sub.radiusX * Math.sin(rad) * knob.scale,
      y: knob.y + (sub.gapPx + sub.radiusY + sub.radiusY * Math.cos(rad)) * knob.scale,
    };
  }

  private applyTransform(els: StringEls, anim: StringChainAnim, s: RingStringLayout) {
    const { depthT, scale, opacity } = this.depthFor(s, anim);

    // D4 dimming is multiplied into the depth opacity (an inline style would otherwise override
    // the .hsd-dimmed class straight mode uses).
    const dimFactor =
      this.activeGroupId !== null && s.category.groupId !== this.activeGroupId
        ? DIMMED_OPACITY_FACTOR
        : 1;
    const effectiveOpacity = opacity * dimFactor;

    const gTransform = `translate(${anim.anchorX} ${anim.anchorY}) scale(${scale})`;
    if (els.lastGTransform !== gTransform) {
      els.g.setAttribute("transform", gTransform);
      els.lastGTransform = gTransform;
    }
    els.g.style.opacity = String(effectiveOpacity);
    if (els.lastHangerTransform !== gTransform) {
      els.hanger.setAttribute("transform", gTransform);
      els.lastHangerTransform = gTransform;
    }
    els.hanger.style.opacity = String(effectiveOpacity);

    // Labels near the back overlap illegibly — fade them out entirely past a depth threshold
    // (faster than the string itself fades).
    const labelFade =
      1 - clamp((depthT - LABEL_FADE_START_DEPTH) / (LABEL_FADE_END_DEPTH - LABEL_FADE_START_DEPTH), 0, 1);
    els.label.style.opacity = String(labelFade);

    const points: Point[] = [{ x: 0, y: 0 }];
    for (let i = 0; i < N_NODES; i++) {
      points.push({ x: anim.nodes[i].value, y: ((i + 1) / N_NODES) * s.dropPx });
    }
    const knobX = anim.nodes[N_NODES - 1].value;

    const pathD = smoothPathThroughPoints(points);
    if (els.lastPathD !== pathD) {
      els.thread.setAttribute("d", pathD);
      els.castThread.setAttribute("d", pathD);
      els.lastPathD = pathD;
    }

    // D9.1: every label rides its knob — to the right of the weight, at the value's depth.
    setAttrIfChanged(
      els.label,
      "transform",
      `translate(${knobX + s.knobRadius + 6} ${s.dropPx + 4})`
    );

    // D23: knots track their thread every frame EXCEPT during a disc-turn session (they are
    // CSS-hidden then anyway; the session-end restore pass re-places them).
    if (!this.spinActive && this.options.showTicks && this.options.quipuKnots !== true) {
      const tickEls = els.ticksLayer.children;
      for (let i = 0; i < tickEls.length; i++) {
        setAttrIfChanged(tickEls[i], "cx", String(xAlongPolyline(points, els.tickYs[i])));
      }
    }
    // D28: quipu glyphs ride the bowed thread like the bead-ticks; D23's spin LOD applies
    // (a disc turn re-runs full layout per frame — the knots pause tracking, same as ticks).
    if (!this.spinActive) {
      for (const q of els.quipuEls) {
        setAttrIfChanged(q.g, "transform", `translate(${xAlongPolyline(points, q.y)} ${q.y})`);
      }
    }

    if (!this.spinActive) {
      setAttrIfChanged(els.shadow, "cx", String(knobX));
    }
    setAttrIfChanged(els.knob, "cx", String(knobX));
    setAttrIfChanged(els.castKnob, "cx", String(knobX));
    setAttrIfChanged(els.glyph, "x", String(knobX));
    setAttrIfChanged(els.knobHit, "cx", String(knobX));

    // D16/D19: keep this parent's mini ring glued to its live knob — position, sway, depth
    // scale and opacity all come from the parent's current animation state, so the whole disc
    // (plate, arrows, rail) visibly hangs from the string and foreshortens/fades with it as it
    // moves around the main ring. Center sits gapPx + radiusY below the knob: top rim gapPx
    // below it.
    const sub = this.subRailEls.get(s.category.id);
    if (sub) {
      const knobWorldX = anim.anchorX + knobX * scale;
      const centerWorldY =
        anim.anchorY + (HANGER_DROP_OFFSET + s.dropPx + sub.gapPx + sub.radiusY) * scale;
      sub.assembly.setGeometry({
        centerX: knobWorldX,
        centerY: centerWorldY,
        radiusX: sub.radiusX * scale,
        radiusY: sub.radiusY * scale,
      });
      sub.assembly.setOpacity(effectiveOpacity);
    }
  }

  // --- animation loop (D10, shared physics via core/chain.ts) ----------------------------

  private ensureTicking() {
    if (this.rafId === null) {
      this.lastFrameTime = null;
      this.rafId = requestAnimationFrame(this.tick);
    }
  }

  private tick = (timestamp: number) => {
    const dt = Math.min((timestamp - (this.lastFrameTime ?? timestamp)) / 1000, 1 / 30);
    this.lastFrameTime = timestamp;

    // Flush rotation accumulated on any disc since the last frame as a single layout+render
    // each — pointermove can fire far more often than the display refreshes, and each
    // onRotate/onSubRotate re-runs the full ring layout, so this coalescing is what keeps a
    // fast spin cheap. (Only one disc can be mid-drag at a time; the others flush to no-ops.)
    this.mainRail.flushRotation();
    // Snapshot: each flush may synchronously re-render, which diffs this very map.
    for (const sub of [...this.subRailEls.values()]) sub.assembly.flushRotation();

    // Hoisted out of the per-string loop: same for every string this frame.
    const chainParams = chainParamsForStiffness(this.options.stiffness);

    // D21.2: the same breeze that waves the backdrop sheet stirs the threads — one wind for
    // the whole scene (same signal, same traveling gust field, phase integrating gust speed).
    const wind = this.windEnabled && this.visible ? breezeSignal(timestamp / 1000) : null;
    if (wind) this.windPhase += wind.speed * dt * 1.1;

    let allSettled = true;
    for (const [id, anim] of this.anim) {
      const s = this.stringById.get(id);

      // D16: children chase their PARENT's live knob (anchor + sway + depth scale), not a static
      // layout anchor, so the whole branch hangs off the parent string while it slides around
      // the arc, spins with the ring, or is dragged. Parents are created before their children,
      // so the parent has already stepped this frame (Map preserves insertion order).
      // A child being DRAGGED stays pinned to the sub-ring's rim (D17-for-children): its target
      // is the mini-ellipse point at its live drag angle, recomputed from the parent's live
      // knob — the hanger slides around the mini rail instead of detaching from it.
      if (s?.parentId) {
        const target = this.childTargetWorld(
          s,
          id === this.liveDragId ? this.dragState?.dragAngleDeg : undefined
        );
        if (target) {
          anim.targetX = target.x;
          anim.targetY = target.y;
        }
      }

      const { settled } = stepChainAnim(anim, {
        isDraggingThis: id === this.liveDragId,
        stiffness: this.options.stiffness,
        chainParams,
        knobRadius: s?.knobRadius ?? this.radiusMin,
        radiusMin: this.radiusMin,
        radiusMax: this.radiusMax,
        dt,
        windAccelPx: wind
          ? threadWindAccel(
              anim.anchorX / this.options.width,
              this.windPhase,
              wind.intensity * this.windScale
            )
          : 0,
      });
      if (!settled) allSettled = false;

      const els = this.stringEls.get(id);
      if (els && s) this.applyTransform(els, anim, s);
    }

    // D18/D19: every disc's arrow spring follows its rotation with a little inertia of its own.
    let railsAtRest = this.mainRail.step(dt);
    for (const sub of this.subRailEls.values()) {
      if (!sub.assembly.step(dt)) railsAtRest = false;
    }
    if (!railsAtRest) allSettled = false;

    // D23: the animation-LOD split. A disc turn re-runs the FULL ring layout every frame —
    // that is the one animation worth shedding detail for. Breeze sway and single-thread
    // pulls are cheap and keep knots/shadows/filters live. The session edge (not the loop
    // parking — ambient wind keeps the loop alive forever while a cloth is up) drives the
    // hsd-animating class, the end-of-session knot/shadow restore, and onSettle.
    const spinning = !railsAtRest || this.anyRailDragging();
    if (spinning !== this.spinActive) {
      this.spinActive = spinning;
      this.svg.classList.toggle("hsd-animating", spinning);
      if (!spinning) {
        // Session over: one restore pass re-places the knots/shadows skipped during the spin.
        for (const [id, anim] of this.anim) {
          const els = this.stringEls.get(id);
          const s = this.stringById.get(id);
          if (els && s) this.applyTransform(els, anim, s);
        }
        this.options.onSettle?.();
      }
    }

    if (
      !allSettled ||
      this.liveDragId !== null ||
      this.anyRailDragging() ||
      (this.windEnabled && this.visible)
    ) {
      this.rafId = requestAnimationFrame(this.tick);
    } else {
      this.rafId = null;
      this.lastFrameTime = null;
    }
  };

  private groupColor(groupId: string): string {
    return this.groupColorById.get(groupId) ?? "#888";
  }

  private colorFor(s: RingStringLayout, heatT: (v: number) => number): string {
    if (this.options.colorMode === "heatmap") {
      if (typeof s.category.secondaryValue !== "number") return "#9ca3af";
      return heatmapColor(heatT(s.category.secondaryValue));
    }
    return this.groupColor(s.category.groupId);
  }

  // --- D17: grab-and-slide a single string (root on the main rail, child on its mini rim) ----

  /** The angle a string currently rests at on ITS ring — a root's main-rail angle, a child's
   * mini-ring angle (both include their ring's rotation offset). Drags and arrow-key nudges
   * start from here. */
  private restAngleOf(s: RingStringLayout): number {
    return s.parentId ? s.localAngleDeg ?? 0 : s.angleDeg;
  }

  private attachStringInteractions(hit: SVGRectElement, id: string) {
    hit.addEventListener("pointerenter", () => {
      if (this.anyRailDragging()) return;
      this.stringEls.get(id)?.g.classList.add("hsd-slide-hover");
      this.showHoverCard(id);
    });
    hit.addEventListener("pointerleave", () => {
      this.stringEls.get(id)?.g.classList.remove("hsd-slide-hover");
      if (this.dragState) return;
      this.hideHoverCard();
    });
    hit.addEventListener("pointerdown", (ev) => {
      const anim = this.anim.get(id);
      const s = this.stringById.get(id);
      const rect = this.svg.getBoundingClientRect();
      const local = this.localPoint(ev, rect);
      // D30: grab is always the weight — drive the chain from the knob node.
      if (anim) anim.grabbedIndex = N_NODES - 1;
      const startAngle = s ? this.restAngleOf(s) : 0;
      this.dragState = {
        id,
        pointerId: ev.pointerId,
        rect,
        lastX: local.x,
        dragAngleDeg: startAngle,
        startAngleDeg: startAngle,
      };
      this.liveDragId = id;
      try {
        hit.setPointerCapture(ev.pointerId);
      } catch {
        // ignore — see ringRail.ts's rotate pointerdown for the identical guard's rationale
      }
      this.stringEls.get(id)?.g.classList.add("hsd-dragging");
      this.stringEls.get(id)?.g.classList.remove("hsd-slide-hover");
      hit.style.cursor = "grabbing";
      this.ensureTicking();
    });
    hit.addEventListener("pointermove", (ev) => {
      if (!this.dragState || this.dragState.id !== id || !this.lastLayout) return;
      const st = this.dragState;
      const local = this.localPoint(ev, st.rect);
      const anim = this.anim.get(id);
      const s = this.stringById.get(id);
      if (!anim || !s) return;

      // D17, both levels: the anchor slides ALONG its rail ellipse — the hanger stays threaded
      // on the rod, like a real curtain ring. Pointer X deltas convert to angle deltas via the
      // ellipse's local slope (dx/dangle = radiusX·cos·π/180), so at the ring's front the
      // string tracks the pointer 1:1. The slope is floored (|cos| ≥ 0.25) to stay finite near
      // the left/right apexes, where the string simply keeps sliding at a capped rate and
      // parks — crossing an apex from pointer X alone is geometrically ambiguous, so it
      // doesn't. No slots, no preview: nothing else moves (positions are free).
      // For a CHILD the ellipse is its mini ring at the parent's live scale; its target point
      // is recomputed from the parent's live knob every frame by the tick loop — here we only
      // advance the angle.
      const sub = s.parentId ? this.subRailEls.get(s.parentId) : null;
      const knob = s.parentId ? this.parentKnobWorld(s.parentId) : null;
      const railRxPx = s.parentId
        ? (sub?.radiusX ?? 0) * (knob?.scale ?? 1)
        : this.lastLayout.config.radiusX;
      if (railRxPx > 0) {
        const pxPerDeg =
          ((railRxPx * Math.PI) / 180) * Math.cos((st.dragAngleDeg * Math.PI) / 180);
        const minPxPerDeg = ((railRxPx * Math.PI) / 180) * 0.25;
        const eff =
          Math.abs(pxPerDeg) < minPxPerDeg
            ? (pxPerDeg < 0 ? -minPxPerDeg : minPxPerDeg)
            : pxPerDeg;
        st.dragAngleDeg += (local.x - st.lastX) / eff;
      }
      if (s.parentId) {
        const target = this.childTargetWorld(s, st.dragAngleDeg);
        if (target) {
          anim.targetX = target.x;
          anim.targetY = target.y;
        }
      } else {
        const p = pointOnRailEllipse(this.lastLayout.config, st.dragAngleDeg);
        anim.targetX = p.anchorX;
        anim.targetY = p.anchorY;
      }
      st.lastX = local.x;
      this.ensureTicking();
    });
    const endStringDrag = (ev: PointerEvent) => {
      if (!this.dragState || this.dragState.id !== id) return;
      try {
        hit.releasePointerCapture(ev.pointerId);
      } catch {
        // ignore — capture may never have been granted (see pointerdown's guard above)
      }
      this.stringEls.get(id)?.g.classList.remove("hsd-dragging");
      hit.style.cursor = "grab";
      const st = this.dragState;
      this.dragState = null;
      this.liveDragId = null;
      if (st.dragAngleDeg !== st.startAngleDeg) {
        // D17, both levels: commit the exact angle it was dropped at — it stays where it was
        // slid, and no other string is repositioned. (A plain click changes nothing.)
        this.options.onSlide?.(id, st.dragAngleDeg);
      }
      this.hideHoverCard();
      this.ensureTicking();
    };
    hit.addEventListener("pointerup", endStringDrag);
    hit.addEventListener("pointercancel", endStringDrag);
    // Capture can be lost without a pointerup ever reaching us (e.g. the element is torn out of
    // the DOM by a re-render mid-drag) — commit the drag where it currently is instead of
    // leaving it pinned to its drag target forever.
    hit.addEventListener("lostpointercapture", endStringDrag);
    hit.addEventListener("keydown", (ev: KeyboardEvent) => {
      // D16 keyboard parity with straight mode: Enter/Space toggles a parent's branch.
      if (ev.key === "Enter" || ev.key === " ") {
        const s = this.stringById.get(id);
        if ((s?.category.children?.length ?? 0) > 0) {
          ev.preventDefault();
          this.options.onToggleExpand?.(id);
        }
        return;
      }
      if (ev.key !== "ArrowLeft" && ev.key !== "ArrowRight") return;
      ev.preventDefault();
      const s = this.stringById.get(id);
      if (!s) return;
      // D17, both levels: arrows nudge the string a few degrees along its rail (no slots).
      this.options.onSlide?.(id, this.restAngleOf(s) + (ev.key === "ArrowLeft" ? -5 : 5));
    });
  }

  private localPoint(ev: PointerEvent, rect = this.svg.getBoundingClientRect()): {
    x: number;
    y: number;
  } {
    const scaleX = this.options.width / rect.width;
    const scaleY = this.options.height / rect.height;
    return { x: (ev.clientX - rect.left) * scaleX, y: (ev.clientY - rect.top) * scaleY };
  }

  private showHoverCard(id: string) {
    const s = this.stringById.get(id);
    if (!s) return;
    const knobY = s.anchorY + (HANGER_DROP_OFFSET + s.dropPx) * s.scale;
    // Layer-local px vs layout units — see render.ts's showHoverCard note (D27: clientWidth
    // keeps the card's coordinates untransformed inside the zoom layer).
    const localW = this.svg.clientWidth || this.svg.getBoundingClientRect().width;
    const localH = this.svg.clientHeight || this.svg.getBoundingClientRect().height;
    const displayScale = localW > 0 ? localW / this.options.width : 1;
    const left = clamp((s.anchorX + 24) * displayScale, 8, Math.max(8, localW - 170));
    const top = clamp(knobY * displayScale, 8, Math.max(8, localH - 90));

    // Q25: the host tooltip event — once per enter (not on the re-shows a drag can trigger).
    if (this.hoverId !== id) {
      this.hoverId = id;
      this.options.onHover?.({
        id,
        parentId: s.parentId ?? null,
        category: s.category,
        x: left,
        y: top,
      });
    }
    if (this.options.showHoverCard === false) return;
    const group = this.options.groups.find((g) => g.id === s.category.groupId);

    // Built with textContent (not innerHTML) so category/group names can never inject markup.
    this.hoverCard.textContent = "";
    const title = document.createElement("div");
    title.className = "hsd-hover-title";
    title.textContent = s.category.name;
    this.hoverCard.appendChild(title);
    const addRow = (label: string, val: string) => {
      const row = document.createElement("div");
      row.className = "hsd-hover-row";
      row.append(`${label}: `);
      const strong = document.createElement("strong");
      strong.textContent = val;
      row.appendChild(strong);
      this.hoverCard.appendChild(row);
    };
    addRow("Group", group?.name ?? "—");
    addRow("Value", String(s.category.value));
    if (typeof s.category.secondaryValue === "number") {
      addRow("2nd metric", s.category.secondaryValue.toFixed(1));
    }

    this.hoverCard.style.left = `${left}px`;
    this.hoverCard.style.top = `${top}px`;
    this.hoverCard.style.display = "block";
  }

  private hideHoverCard() {
    if (this.hoverId !== null) {
      this.hoverId = null;
      this.options.onHover?.(null);
    }
    this.hoverCard.style.display = "none";
  }
}
