/**
 * D28 (v4, wiki/design/quipu-v4.md): quipu knot encoding — the 2nd metric rendered as REAL
 * khipu numbers on the cord. Pure, DOM-free layout math; the SVG renderers only draw what
 * this module places (same split as layout.ts/ringLayout.ts).
 *
 * The encoding is the khipu's decimal positional system (encoding B, user sign-off
 * 2026-07-22), with the glyph spec that survived six mockup iterations:
 *   - units digit nearest the knob (the cord's free end): figure-eight = 1, long knot with
 *     n countable wraps + a bypass strand = 2–9;
 *   - tens/hundreds/… as clusters of n simple bead knots, ONE GROUP PER DECIMAL PLACE,
 *     with a clear bare-cord GAP between groups (bands stacked toward the rail);
 *   - zero = a bare band (the gap itself is the digit);
 *   - every 5th knot FROM THE BOTTOM renders bigger (tally/subitizing aid) — in wraps,
 *     bead clusters, and bucket fallback alike;
 *   - when the cord is too short for full-size bands, slots COMPRESS (keeping inter-band
 *     gaps) so multi-digit values stay positional; only extremely short cords fall back
 *     to a single bucketed bead cluster (caption "×unit").
 *
 * Sign/fraction limitation (documented): khipu knots encode counts — the glyphs carry
 * round(abs(value)); `negative` flags the sign for the renderer/hover to surface.
 */

export interface QuipuConfig {
  /** Vertical slot per decimal band, sized for the worst-case digit (9 beads) + air. */
  bandSlotPx: number;
  /** Guaranteed bare cord between adjacent bands — the khipu "space" that also reads as 0. */
  bandGapPx: number;
  /** The units band's bottom sits this far above the knob (free-end reading origin). */
  knobOffsetPx: number;
  /** Bead-to-bead pitch inside a simple-knot cluster (> bead size: bare cord shows between). */
  beadPitchPx: number;
  /** Wrap-to-wrap pitch inside a long knot (tight: the wraps form ONE knot). */
  wrapPitchPx: number;
}

/** Chart-scale defaults — proportionally the mockup's values, tuned for ~300px drops.
 * Invariant (pinned by quipu.test.ts): the worst-case band content (9 beads: 6px inset +
 * 8×pitch + 5px headroom = 87px) must fit inside bandSlot − bandGap. */
export const DEFAULT_QUIPU_CONFIG: QuipuConfig = {
  bandSlotPx: 102,
  bandGapPx: 14,
  knobOffsetPx: 22,
  beadPitchPx: 9.5,
  // Iteration 7 (user: wraps hard to count): the pitch must leave clear AIR between wraps —
  // at 5.5px the ~5px-tall ellipses fused into a ribbed blob. 7.5px + flatter ellipses
  // (quipuGlyphs.ts) puts visible strand between every turn. Worst case still fits:
  // 9 × 7.5 + 5 = 72.5px ≤ bandSlot − bandGap (88px), pinned by the separation test.
  wrapPitchPx: 7.5,
};

/** Below this per-band slot, compressed positional would fuse digit groups — use bucket. */
const MIN_BAND_SLOT_PX = 48;
/** Floor for the bare gap between digit groups (tens / hundreds / …). */
const MIN_BAND_GAP_PX = 10;

/** All glyph `y`s are measured UPWARD from the knob (the khipu reading origin: units at the
 * free end). Renderers convert with `cy = dropPx - y`. */
export type QuipuGlyph =
  | { type: "fig8"; y: number }
  | { type: "long"; y: number; turns: number } // y = the wrap stack's BOTTOM; wraps grow up
  | { type: "simple"; y: number; big: boolean }; // y = bead center

export interface QuipuLayout {
  /** "positional" = full khipu bands; "bucket" = short-cord fallback A; "none" = no value. */
  mode: "positional" | "bucket" | "none";
  glyphs: QuipuGlyph[];
  /** Decimal digits, most-significant first (aria/debug/tests). Empty when mode = "none". */
  digits: number[];
  /** Bucket mode only: one bead ≈ this much (caption "×unit"). */
  bucketUnit?: number;
  /** The magnitude actually encoded: round(abs(value)). */
  displayValue: number;
  negative: boolean;
  /** Effective band slot used for this layout (full or compressed). */
  bandSlotPx?: number;
  /** Effective inter-band gap used for this layout. */
  bandGapPx?: number;
  /** Effective pitches used when placing/drawing glyphs (may be compressed). */
  beadPitchPx?: number;
  wrapPitchPx?: number;
}

/** The tally aid: every 5th knot counted from the bottom is bigger. `indexFromBottom` is
 * 0-based, so the 5th knot has index 4. */
export function isBigFifth(indexFromBottom: number): boolean {
  return (indexFromBottom + 1) % 5 === 0;
}

/** Drop (cord length) needed to fit `nDigits` positional bands at FULL size — THE fallback
 * threshold before compression kicks in. */
export function quipuNeededDropPx(nDigits: number, cfg: QuipuConfig = DEFAULT_QUIPU_CONFIG): number {
  return cfg.knobOffsetPx + nDigits * cfg.bandSlotPx + 8;
}

/** A long knot's wrap-stack height for `turns` wraps (renderer + tests share it). */
export function wrapStackHeightPx(turns: number, cfg: QuipuConfig = DEFAULT_QUIPU_CONFIG): number {
  return turns * cfg.wrapPitchPx + 5;
}

/** Bucket units tried in order — "nice" steps so the caption reads naturally. */
const BUCKET_UNITS = [1, 2, 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000];

/** Fit band slot/gap/pitches into the available cord while keeping digit groups separated. */
export function fitQuipuBandMetrics(
  dropPx: number,
  nDigits: number,
  cfg: QuipuConfig = DEFAULT_QUIPU_CONFIG
): { bandSlotPx: number; bandGapPx: number; beadPitchPx: number; wrapPitchPx: number } | null {
  if (nDigits <= 0) return null;
  const available = dropPx - cfg.knobOffsetPx - 8;
  if (available < MIN_BAND_SLOT_PX) return null;
  const bandSlotPx = Math.min(cfg.bandSlotPx, available / nDigits);
  if (bandSlotPx < MIN_BAND_SLOT_PX) return null;

  // Keep a readable bare gap between groups; never let content eat the whole slot.
  const bandGapPx = Math.min(
    Math.max(MIN_BAND_GAP_PX, cfg.bandGapPx * (bandSlotPx / cfg.bandSlotPx)),
    bandSlotPx * 0.28
  );
  const contentBudget = Math.max(12, bandSlotPx - bandGapPx - 8);
  // Worst-case 9 beads / 9 wraps must still fit inside the content budget.
  const beadPitchPx = Math.min(cfg.beadPitchPx, contentBudget / 8);
  const wrapPitchPx = Math.min(cfg.wrapPitchPx, contentBudget / 9);
  return { bandSlotPx, bandGapPx, beadPitchPx, wrapPitchPx };
}

function layoutPositionalBands(
  digits: number[],
  cfg: QuipuConfig,
  metrics: { bandSlotPx: number; bandGapPx: number; beadPitchPx: number; wrapPitchPx: number }
): QuipuGlyph[] {
  const glyphs: QuipuGlyph[] = [];
  // place 0 = units (nearest the knob), increasing toward the rail
  for (let place = 0; place < digits.length; place++) {
    const d = digits[digits.length - 1 - place]!;
    const bandBottom = cfg.knobOffsetPx + place * metrics.bandSlotPx;
    if (d === 0) continue; // zero = the band stays bare (gap reads as 0)
    if (place === 0) {
      if (d === 1) glyphs.push({ type: "fig8", y: bandBottom + 10 });
      else glyphs.push({ type: "long", y: bandBottom + 2, turns: d });
    } else {
      // One contiguous cluster per power of ten; top of slot reserved as inter-band gap.
      for (let i = 0; i < d; i++) {
        glyphs.push({
          type: "simple",
          y: bandBottom + 6 + i * metrics.beadPitchPx,
          big: isBigFifth(i),
        });
      }
    }
  }
  return glyphs;
}

export function computeQuipuLayout(
  value: number | undefined,
  dropPx: number,
  cfg: QuipuConfig = DEFAULT_QUIPU_CONFIG
): QuipuLayout {
  const none: QuipuLayout = { mode: "none", glyphs: [], digits: [], displayValue: 0, negative: false };
  if (value === undefined || !Number.isFinite(value)) return none;
  const negative = value < 0;
  const magnitude = Math.round(Math.abs(value));
  if (magnitude === 0) return { ...none, negative }; // zero = a bare cord (authentic)

  const digits = String(magnitude).split("").map(Number); // most-significant first

  const metrics = fitQuipuBandMetrics(dropPx, digits.length, cfg);
  if (metrics) {
    const glyphs = layoutPositionalBands(digits, cfg, metrics);
    return {
      mode: "positional",
      glyphs,
      digits,
      displayValue: magnitude,
      negative,
      bandSlotPx: metrics.bandSlotPx,
      bandGapPx: metrics.bandGapPx,
      beadPitchPx: metrics.beadPitchPx,
      wrapPitchPx: metrics.wrapPitchPx,
    };
  }

  // --- bucket fallback (A) — only when even compressed bands cannot fit ---------------
  const maxKnots = Math.max(1, Math.floor((dropPx - cfg.knobOffsetPx - 4) / cfg.beadPitchPx));
  let unit = BUCKET_UNITS.find((u) => Math.round(magnitude / u) <= maxKnots && Math.round(magnitude / u) >= 1);
  if (unit === undefined) {
    // beyond the table: keep doubling the last nice unit until the cluster fits
    unit = BUCKET_UNITS[BUCKET_UNITS.length - 1]!;
    while (Math.round(magnitude / unit) > maxKnots) unit *= 2;
  }
  const count = Math.max(1, Math.round(magnitude / unit));
  const glyphs: QuipuGlyph[] = [];
  for (let i = 0; i < count; i++) {
    glyphs.push({ type: "simple", y: cfg.knobOffsetPx + i * cfg.beadPitchPx, big: isBigFifth(i) });
  }
  return { mode: "bucket", glyphs, digits, bucketUnit: unit, displayValue: magnitude, negative };
}
