/**
 * v2.5 T1/T2: the SVG/DOM half of theming — translates the renderer-agnostic theme object
 * (core/theme.ts) into the mechanisms this renderer actually paints with:
 *
 *   1. CSS custom properties (`--hsd-*`) set on a root element; every cosmetic rule in
 *      style.css reads them via var(), so a theme swap is one setProperty pass with no
 *      per-element DOM writes.
 *   2. SVG fill defs — <linearGradient> or <pattern> (T2) — for ThemeFill surfaces that CSS
 *      classes reference via url(#…); today only the ring plate (D13).
 *   3. A data-URI tile for the background slot's grain (T2) — the browser rasterizes it once
 *      and repeats the bitmap, which is exactly the "bake, never live-filter" perf rule from
 *      the texturing page.
 *
 * Data colors (group/heat tints, D5/D8) never pass through here — they are applied inline
 * per-string by the renderers, exactly as before T1 (the Q18 tint contract: theme materials
 * have no tint-carrying fields at all, see core/theme.ts).
 */

import type {
  HangingStringsDiagramTheme,
  ThemeFill,
  ThemeImageLuminanceTexture,
  ThemePatternMark,
  ThemePatternTile,
  ThemeShadow,
  ThemeThreadTexture,
} from "../../core/theme";
import { syncLabelContrast } from "../../core/labelContrast";

const SVG_NS = "http://www.w3.org/2000/svg";

/** "0" for zero, "2px" otherwise — matches how the pre-T1 stylesheet wrote shadow offsets, so
 * the Studio extraction stays character-identical to the literals it replaced. */
function px(n: number): string {
  return n === 0 ? "0" : `${n}px`;
}

/** CSS filter value for a D11 elevation shadow; `null` (the theme switched it off — the perf
 * lever) becomes `none`, which cheaply disables the filter without touching style.css. */
function dropShadow(shadow: ThemeShadow | null): string {
  if (!shadow) return "none";
  return `drop-shadow(${px(shadow.offsetX)} ${px(shadow.offsetY)} ${px(shadow.blur)} ${shadow.color})`;
}

/** box-shadow value (the hover card is HTML, not SVG, so it shadows via box-shadow). */
function boxShadow(shadow: ThemeShadow | null): string {
  if (!shadow) return "none";
  return `${px(shadow.offsetX)} ${px(shadow.offsetY)} ${px(shadow.blur)} ${shadow.color}`;
}

/** A pattern mark's SVG attributes — one source of truth for both output forms (markup string
 * for the CSS data-URI, DOM elements for <pattern> defs), so the two renderings of the same
 * tile can never drift apart. The element name is the mark's `kind`. */
function markAttrs(mark: ThemePatternMark): Record<string, string> {
  const attrs: Record<string, string> =
    mark.kind === "circle"
      ? { cx: String(mark.cx), cy: String(mark.cy), r: String(mark.r), fill: mark.fill }
      : {
          x1: String(mark.x1),
          y1: String(mark.y1),
          x2: String(mark.x2),
          y2: String(mark.y2),
          stroke: mark.stroke,
          "stroke-width": String(mark.width),
        };
  if (mark.opacity !== undefined) attrs.opacity = String(mark.opacity);
  return attrs;
}

/**
 * A pattern tile as standalone SVG markup (pure string — testable without a DOM). `base`
 * paints a ground rect under the marks; omit it for the background grain, whose ground is the
 * CSS background-color beneath the image.
 */
export function patternTileSvgMarkup(tile: ThemePatternTile, base?: string): string {
  const attrString = (attrs: Record<string, string>) =>
    Object.entries(attrs)
      .map(([k, v]) => `${k}="${v}"`)
      .join(" ");
  const baseRect = base ? `<rect width="${tile.width}" height="${tile.height}" fill="${base}"/>` : "";
  const marks = tile.marks.map((m) => `<${m.kind} ${attrString(markAttrs(m))}/>`).join("");
  return (
    `<svg xmlns="${SVG_NS}" width="${tile.width}" height="${tile.height}">` +
    baseRect +
    marks +
    `</svg>`
  );
}

/** CSS `url()` value carrying the tile as a data-URI — rasterized once by the browser, then
 * tiled as a plain bitmap (no per-frame cost; the tile itself never animates). */
export function patternTileCssUrl(tile: ThemePatternTile): string {
  return `url("data:image/svg+xml,${encodeURIComponent(patternTileSvgMarkup(tile))}")`;
}

/**
 * The full theme → CSS custom property map. Pure (no DOM), so tests can assert the Studio
 * theme produces exactly the pre-T1 literals and that style.css's var() references and this
 * map never drift apart.
 *
 * `railSheenDefId` is the def id `--hsd-rail-paint` points at when the theme ships a rod sheen
 * — applyTheme passes each scope element's own id (Q23: two instances with different sheen
 * themes must not fight over one `#hsd-rail-sheen`).
 */
export function themeCssVars(
  theme: HangingStringsDiagramTheme,
  railSheenDefId: string = RAIL_SHEEN_DEF_ID
): Record<string, string> {
  return {
    "--hsd-background": theme.background.color,
    "--hsd-background-image": theme.background.grain
      ? patternTileCssUrl(theme.background.grain)
      : "none",

    "--hsd-rail-color": theme.rail.color,
    // The rod's actual stroke paint: the photoreal sheen def when the theme has one (Wool &
    // brass v2's lit pipe), else the flat rail color. --hsd-rail-color stays authoritative for
    // everything else rail-toned (focus dash), so the two vars never conflate.
    "--hsd-rail-paint": theme.rail.sheen ? `url(#${railSheenDefId})` : theme.rail.color,
    "--hsd-rail-width": String(theme.rail.strokeWidth),
    "--hsd-hanger-fill": theme.rail.hanger.fill,
    "--hsd-hanger-stroke": theme.rail.hanger.stroke,
    "--hsd-hanger-width": String(theme.rail.hanger.strokeWidth),
    "--hsd-ruler-minor": theme.rail.ruler.minor,
    "--hsd-ruler-medium": theme.rail.ruler.medium,
    "--hsd-ruler-major": theme.rail.ruler.major,
    "--hsd-ruler-front": theme.rail.ruler.front,

    "--hsd-plate-edge": theme.plate.edge,
    "--hsd-plate-arrow-fill": theme.plate.arrowFill,
    "--hsd-plate-arrow-edge": theme.plate.arrowEdge,

    "--hsd-thread-width": String(theme.thread.strokeWidth),
    "--hsd-thread-dash": theme.thread.strokeDash ? theme.thread.strokeDash.join(" ") : "none",
    "--hsd-tick-stroke": theme.thread.tickStroke,

    "--hsd-knob-edge": theme.knob.edge,
    "--hsd-knob-branch-edge": theme.knob.branchEdge,
    "--hsd-knob-glyph": theme.knob.glyph,

    "--hsd-label-ink": theme.label.ink,
    "--hsd-label-halo": theme.label.halo,
    "--hsd-label-value-ink": theme.label.valueInk,
    "--hsd-caption-ink": theme.label.captionInk,
    "--hsd-label-font": theme.label.fontFamily,
    "--hsd-card-bg": theme.label.card.background,
    "--hsd-card-ink": theme.label.card.ink,

    "--hsd-rail-shadow": dropShadow(theme.shadow.rail),
    "--hsd-plate-shadow": dropShadow(theme.shadow.plate),
    "--hsd-thread-shadow": dropShadow(theme.shadow.thread),
    "--hsd-label-shadow": dropShadow(theme.shadow.label),
    "--hsd-card-shadow": boxShadow(theme.shadow.card),
    "--hsd-floor-fill": theme.shadow.floor.color,
    "--hsd-floor-opacity": String(theme.shadow.floor.opacity),
    "--hsd-cast-color": theme.shadow.cast.color,
    // The cast copy is slightly wider than the thread — reads as soft penumbra, no filter.
    "--hsd-cast-width": String(theme.thread.strokeWidth + 1.5),
  };
}

/** The default id `--hsd-rail-paint` references when a theme ships a rod sheen. The def lives
 * in ONE shared, always-rendered host svg (see ensureSharedThemeDefs) because BOTH renderers'
 * rails read the same CSS variable — a per-renderer def would need per-svg ids and two
 * variables for one material. Q23: each theme SCOPE (the element applyTheme targets) gets its
 * own suffixed copy of this id, so two instances with different sheen themes coexist. */
const RAIL_SHEEN_DEF_ID = "hsd-rail-sheen";

/** Q23: each applyTheme scope element owns one sheen def id for its lifetime — stable across
 * theme switches (the def is replaced in place), unique across scopes. */
const sheenDefIdByScope = new WeakMap<Element, string>();
let sheenScopeCounter = 0;

function sheenDefIdFor(el: Element): string {
  let id = sheenDefIdByScope.get(el);
  if (!id) {
    sheenScopeCounter += 1;
    id = `${RAIL_SHEEN_DEF_ID}-s${sheenScopeCounter}`;
    sheenDefIdByScope.set(el, id);
  }
  return id;
}

/** A zero-size (but rendered — paint servers inside `display:none` are unreliable across
 * engines) svg appended once to <body>, hosting theme defs that are referenced document-wide
 * via url(#…) from CSS variables. Created lazily so pure/module-level test imports never touch
 * the DOM. */
function ensureSharedThemeDefs(): SVGDefsElement {
  const HOST_ID = "hsd-theme-defs-host";
  let host = document.getElementById(HOST_ID) as SVGSVGElement | null;
  if (!host) {
    host = document.createElementNS(SVG_NS, "svg");
    host.setAttribute("id", HOST_ID);
    host.setAttribute("width", "0");
    host.setAttribute("height", "0");
    host.setAttribute("aria-hidden", "true");
    host.style.position = "absolute";
    host.appendChild(document.createElementNS(SVG_NS, "defs"));
    document.body.appendChild(host);
  }
  return host.querySelector("defs") as SVGDefsElement;
}

/**
 * Applies the theme's CSS variables to `el`'s inline style. main.ts targets the document root
 * (not the chart container) because the background slot styles the page body, which sits
 * outside any chart element; inline properties also override the stylesheet's pre-JS
 * `--hsd-background` bootstrap default by specificity, with no rule-ordering concerns.
 *
 * Also stamps the theme's chrome scheme (Q20, T3) as a `data-hsd-dark` attribute — style.css's
 * dark-chrome override block keys on it, so the app chrome flips with the theme in the same
 * single pass — and (v2 photoreal) maintains the shared rail-sheen def that
 * `--hsd-rail-paint` references. Safe to re-run for live theme switching (the T3 picker):
 * everything it touches is idempotently overwritten.
 */
export function applyTheme(
  el: Element & ElementCSSInlineStyle,
  theme: HangingStringsDiagramTheme
): void {
  // Q23: the sheen def id is per-scope, so two instances themed differently each reference
  // their own def in the shared host instead of overwriting one global `#hsd-rail-sheen`.
  const sheenId = sheenDefIdFor(el);
  for (const [name, value] of Object.entries(themeCssVars(theme, sheenId))) {
    el.style.setProperty(name, value);
  }
  if (theme.chromeScheme === "dark") el.setAttribute("data-hsd-dark", "");
  else el.removeAttribute("data-hsd-dark");

  const sharedDefs = ensureSharedThemeDefs();
  sharedDefs.querySelector(`#${sheenId}`)?.remove();
  if (theme.rail.sheen) {
    sharedDefs.appendChild(createFillDef(sheenId, theme.rail.sheen));
  }

  // After theme vars (and any host CSS that overrides background-color), keep labels readable.
  syncLabelContrast(el);
}

/**
 * Per-renderer paint source for thread strokes (v2 photoreal). Without a texture the paint IS
 * the data tint, exactly as before. With one (Wool & brass's yarn), each distinct tint gets a
 * lazily-built `<pattern>` in the OWNING renderer's defs, so the stroke renders as textured
 * yarn whose hue is still precisely the encoding — Q18 survives photorealism structurally:
 * the tint paints the pattern's ground, and the theme contributes only lightness, either as
 * a procedural tile's white/black marks or as a photo's grayscale luminance maps blended
 * multiply (grooves) + screen (crest highlights) over the tinted ground. Patterns are cached
 * per tint and rebuilt from scratch on setTexture (theme switches). `prefix` keeps ids unique
 * per renderer, since both svgs host their own copies.
 *
 * Image textures use SVG `feBlend` filters (not CSS `mix-blend-mode` on `<image>` children of
 * `<pattern>`). Pattern contents are never-rendered paint servers — Firefox does not apply
 * mix-blend-mode there, so grayscale maps would paint opaque over the tint (B&W cords).
 * `feBlend` is the portable luminance pipeline and matches Chromium's previous look.
 */
export function createThreadPaintSource(defs: SVGDefsElement, prefix: string) {
  let texture: ThemeThreadTexture | null = null;
  const built = new Map<string, string>();

  function setFeImageHref(el: SVGElement, href: string) {
    el.setAttribute("href", href);
    // Older Firefox SVG filter paths still resolve xlink:href on feImage.
    el.setAttributeNS("http://www.w3.org/1999/xlink", "href", href);
  }

  /** Appends a sibling filter def (`${id}-blend`) and returns the pattern that uses it. */
  function imagePatternDef(id: string, tex: ThemeImageLuminanceTexture, tint: string): SVGElement {
    const filterId = `${id}-blend`;
    const filter = document.createElementNS(SVG_NS, "filter");
    filter.setAttribute("id", filterId);
    filter.setAttribute("filterUnits", "userSpaceOnUse");
    filter.setAttribute("primitiveUnits", "userSpaceOnUse");
    filter.setAttribute("x", "0");
    filter.setAttribute("y", "0");
    filter.setAttribute("width", String(tex.width));
    filter.setAttribute("height", String(tex.height));
    filter.setAttribute("color-interpolation-filters", "sRGB");

    const flood = document.createElementNS(SVG_NS, "feFlood");
    flood.setAttribute("flood-color", tint);
    flood.setAttribute("result", "tint");
    filter.appendChild(flood);

    const multMap = document.createElementNS(SVG_NS, "feImage");
    setFeImageHref(multMap, tex.multiply);
    multMap.setAttribute("x", "0");
    multMap.setAttribute("y", "0");
    multMap.setAttribute("width", String(tex.width));
    multMap.setAttribute("height", String(tex.height));
    multMap.setAttribute("preserveAspectRatio", "none");
    multMap.setAttribute("result", "multMap");
    filter.appendChild(multMap);

    const multiply = document.createElementNS(SVG_NS, "feBlend");
    multiply.setAttribute("in", "tint");
    multiply.setAttribute("in2", "multMap");
    multiply.setAttribute("mode", "multiply");
    multiply.setAttribute("result", tex.screen ? "shaded" : "out");
    filter.appendChild(multiply);

    if (tex.screen) {
      const scrMap = document.createElementNS(SVG_NS, "feImage");
      setFeImageHref(scrMap, tex.screen);
      scrMap.setAttribute("x", "0");
      scrMap.setAttribute("y", "0");
      scrMap.setAttribute("width", String(tex.width));
      scrMap.setAttribute("height", String(tex.height));
      scrMap.setAttribute("preserveAspectRatio", "none");
      scrMap.setAttribute("result", "scrMap");
      filter.appendChild(scrMap);

      const screen = document.createElementNS(SVG_NS, "feBlend");
      screen.setAttribute("in", "shaded");
      screen.setAttribute("in2", "scrMap");
      screen.setAttribute("mode", "screen");
      filter.appendChild(screen);
    }

    defs.appendChild(filter);

    const pattern = document.createElementNS(SVG_NS, "pattern");
    pattern.setAttribute("id", id);
    pattern.setAttribute("patternUnits", "userSpaceOnUse");
    pattern.setAttribute("width", String(tex.width));
    pattern.setAttribute("height", String(tex.height));
    const tile = document.createElementNS(SVG_NS, "rect");
    tile.setAttribute("width", String(tex.width));
    tile.setAttribute("height", String(tex.height));
    // Opaque fill so the filter has a defined geometry; color comes from feFlood/feBlend.
    tile.setAttribute("fill", "#fff");
    tile.setAttribute("filter", `url(#${filterId})`);
    pattern.appendChild(tile);
    return pattern;
  }

  return {
    setTexture(tex: ThemeThreadTexture | null | undefined) {
      texture = tex ?? null;
      for (const id of built.values()) {
        defs.querySelector(`#${id}`)?.remove();
        defs.querySelector(`#${id}-blend`)?.remove();
      }
      built.clear();
    },
    paintFor(tint: string): string {
      if (!texture) return tint;
      let id = built.get(tint);
      if (!id) {
        id = `${prefix}-${tint.replace(/[^a-zA-Z0-9]/g, "")}`;
        const def =
          "marks" in texture
            ? createFillDef(id, { kind: "pattern", base: tint, tile: texture })
            : imagePatternDef(id, texture, tint);
        // Center the tile on the stroke: threads live at local x = 0, which without this
        // offset is a TILE BOUNDARY — the stroke band would straddle two tile edges with a
        // visible seam down its middle (and show the texture's edge columns instead of the
        // rope's crest). Shifting the tiling phase by half a tile puts the tile's horizontal
        // center on the stroke's center line; with tiles wider than the stroke there is then
        // no horizontal wrap inside the stroke at all.
        def.setAttribute("x", String(-texture.width / 2));
        defs.appendChild(def);
        built.set(tint, id);
      }
      return `url(#${id})`;
    },
  };
}

export type ThreadPaintSource = ReturnType<typeof createThreadPaintSource>;

/**
 * Builds the <defs> element for a ThemeFill that CSS references via url(#id): a
 * <linearGradient> for gradient fills (a flat fill becomes a single-stop gradient — solid
 * paint) or a <pattern> for T2 pattern fills — the url() indirection keeps working for any
 * theme without touching the referencing style.css rule. patternUnits stays userSpaceOnUse so
 * the tile's px sizing is absolute: the texture's grain does NOT stretch with the element it
 * paints (a bigger cork board has more flecks, not bigger flecks).
 */
/** D11.1: the scene light's cast-shadow offset — one constant for the whole picture, so
 * every thread/knob throws its shadow onto the backdrop sheet in the same direction (light
 * from the upper left). Color/width come from the theme (--hsd-cast-color / --hsd-cast-width);
 * geometry is an offset copy, so nothing here re-evaluates a filter per frame. */
export const CAST_SHADOW_TRANSFORM = "translate(7 5)";

export function createFillDef(id: string, fill: ThemeFill): SVGElement {
  if (fill.kind === "pattern") {
    const pattern = document.createElementNS(SVG_NS, "pattern");
    pattern.setAttribute("id", id);
    pattern.setAttribute("patternUnits", "userSpaceOnUse");
    pattern.setAttribute("width", String(fill.tile.width));
    pattern.setAttribute("height", String(fill.tile.height));
    const baseRect = document.createElementNS(SVG_NS, "rect");
    baseRect.setAttribute("width", String(fill.tile.width));
    baseRect.setAttribute("height", String(fill.tile.height));
    baseRect.setAttribute("fill", fill.base);
    pattern.appendChild(baseRect);
    for (const mark of fill.tile.marks) {
      const el = document.createElementNS(SVG_NS, mark.kind);
      for (const [name, value] of Object.entries(markAttrs(mark))) {
        el.setAttribute(name, value);
      }
      pattern.appendChild(el);
    }
    return pattern;
  }

  let grad: SVGElement;
  let stops: { offset: number; color: string }[];
  if (fill.kind === "radial-gradient") {
    // D22: center-out over the element's bbox — cx/cy/r default to the centered unit circle.
    grad = document.createElementNS(SVG_NS, "radialGradient");
    stops = fill.stops;
  } else {
    grad = document.createElementNS(SVG_NS, "linearGradient");
    const from = fill.kind === "linear-gradient" ? fill.from : [0, 0];
    const to = fill.kind === "linear-gradient" ? fill.to : [1, 1];
    grad.setAttribute("x1", String(from[0]));
    grad.setAttribute("y1", String(from[1]));
    grad.setAttribute("x2", String(to[0]));
    grad.setAttribute("y2", String(to[1]));
    stops = fill.kind === "linear-gradient" ? fill.stops : [{ offset: 0, color: fill.color }];
  }
  grad.setAttribute("id", id);
  for (const { offset, color } of stops) {
    const stop = document.createElementNS(SVG_NS, "stop");
    stop.setAttribute("offset", String(offset));
    stop.setAttribute("stop-color", color);
    grad.appendChild(stop);
  }
  return grad;
}
