/**
 * D30: slide/grab geometry hugs the lower weight (knob), not the full cord — so a finger or
 * cursor crossing the upper thread does not accidentally start a slide.
 */

export function lowerEndHitGeometry(dropPx: number, knobRadius: number): {
  x: number;
  width: number;
  y: number;
  height: number;
} {
  const halfW = Math.max(22, knobRadius + 14);
  const topPad = Math.max(10, knobRadius * 0.65); // short cord stub above the weight
  const bottomPad = Math.max(14, knobRadius + 10);
  return {
    x: -halfW,
    width: halfW * 2,
    y: dropPx - topPad,
    height: topPad + bottomPad,
  };
}

/** Expand/collapse press target — sits on the knob face, above the slide hit. */
export function expandHitRadius(knobRadius: number): number {
  return knobRadius + 4;
}
