/**
 * D28: the quipu knot GLYPHS — the SVG half of core/quipu.ts, shared by both renderers
 * (same split as labels.ts) so the six-iteration glyph spec lives in exactly one place:
 *
 *   - simple knot: a round bead, bare cord visible between beads; the 5th-from-bottom is
 *     bigger (count-in-fives);
 *   - long knot: countable separated ellipse WRAPS rotated 45° (helix slant of a real long
 *     knot) + an external bypass strand in the SAME thread paint as the cord, tight on the
 *     LEFT flank, top→bottom (what unifies the wraps into "one knot"); 5th wrap bigger;
 *   - figure-eight: two offset stroked lobes;
 *   - bucket fallback: bead cluster + a small "×unit" caption.
 *
 * Every glyph is one <g> positioned by a translate whose y is FIXED in the string's local
 * frame; the renderers' animation loops re-translate x along the bowed thread each frame
 * (exactly the bead-ticks' sway-follow). Sizes derive from the theme's thread width, so a
 * fat kernmantle rope gets proportionate knots (mockup ratios preserved: bead ≈ 0.9×sw,
 * wrap rx ≈ 1.3×sw).
 */

import { isBigFifth, type QuipuConfig, type QuipuLayout } from "../../core/quipu";

const SVG_NS = "http://www.w3.org/2000/svg";

export interface QuipuGlyphEl {
  g: SVGGElement;
  /** The glyph's y in the string's local frame (0 = anchor, dropPx = knob) — the animation
   * loop translates to (xAlongPolyline(points, y), y). */
  y: number;
}

/** Wipes and rebuilds `layer` from a computed QuipuLayout; returns the per-glyph groups the
 * animation loop repositions. */
export function buildQuipuLayer(
  layer: SVGGElement,
  layout: QuipuLayout,
  dropPx: number,
  paint: string,
  strokeWidth: number,
  cfg: QuipuConfig
): QuipuGlyphEl[] {
  layer.textContent = "";
  const els: QuipuGlyphEl[] = [];
  const rBead = Math.max(3.2, strokeWidth * 0.9);
  const rWrap = Math.max(4.6, strokeWidth * 1.3);
  const BIG = 1.35;

  const group = (y: number): SVGGElement => {
    const g = document.createElementNS(SVG_NS, "g");
    g.setAttribute("transform", `translate(0 ${y})`);
    layer.appendChild(g);
    els.push({ g, y });
    return g;
  };

  const drawCfg: QuipuConfig = {
    ...cfg,
    wrapPitchPx: layout.wrapPitchPx ?? cfg.wrapPitchPx,
    beadPitchPx: layout.beadPitchPx ?? cfg.beadPitchPx,
    bandSlotPx: layout.bandSlotPx ?? cfg.bandSlotPx,
    bandGapPx: layout.bandGapPx ?? cfg.bandGapPx,
  };

  for (const glyph of layout.glyphs) {
    if (glyph.type === "simple") {
      const g = group(dropPx - glyph.y);
      const bead = document.createElementNS(SVG_NS, "circle");
      bead.setAttribute("class", "hsd-quipu-knot");
      bead.setAttribute("r", String(glyph.big ? rBead * BIG : rBead));
      bead.style.fill = paint;
      g.appendChild(bead);
    } else if (glyph.type === "fig8") {
      const g = group(dropPx - glyph.y);
      for (const [dx, dy] of [
        [-2, -2.6],
        [2, 2.6],
      ]) {
        const lobe = document.createElementNS(SVG_NS, "ellipse");
        lobe.setAttribute("class", "hsd-quipu-fig8");
        lobe.setAttribute("cx", String(dx));
        lobe.setAttribute("cy", String(dy));
        lobe.setAttribute("rx", String(rBead * 0.85));
        lobe.setAttribute("ry", String(rBead * 0.68));
        lobe.style.stroke = paint;
        lobe.style.strokeWidth = String(Math.max(2, strokeWidth * 0.55));
        g.appendChild(lobe);
      }
    } else {
      // long knot: anchor at the wrap stack's BOTTOM; wraps grow upward from it
      const g = group(dropPx - glyph.y);
      const topY = -(3 + (glyph.turns - 1) * drawCfg.wrapPitchPx);
      // Bypass strand first (under the wraps): same thread paint / near-full cord width so
      // the yarn grain reads — a thin flat stroke looked like a separate wire, not the cord
      // continuing past its own wraps.
      const strand = document.createElementNS(SVG_NS, "path");
      strand.setAttribute("class", "hsd-quipu-strand");
      const sx = -(rWrap + 1.8);
      strand.setAttribute(
        "d",
        `M -1 ${topY - 5} Q ${sx} ${topY - 3.5} ${sx} ${topY + 2} L ${sx} ${-1} Q ${sx} ${4} -1 ${5}`
      );
      strand.setAttribute("stroke", paint);
      strand.setAttribute("stroke-width", String(Math.max(2.2, strokeWidth * 0.9)));
      g.appendChild(strand);
      for (let i = 0; i < glyph.turns; i++) {
        const big = isBigFifth(i); // i counts from the BOTTOM wrap
        const cy = -(3 + i * drawCfg.wrapPitchPx);
        const rx = big ? rWrap * BIG : rWrap;
        const wrap = document.createElementNS(SVG_NS, "ellipse");
        wrap.setAttribute("class", "hsd-quipu-knot");
        wrap.setAttribute("cx", "0");
        wrap.setAttribute("cy", String(cy));
        wrap.setAttribute("rx", String(rx));
        // Flat ellipse + 45° rotation ≈ a helix turn of cord (was axis-aligned "rib" ovals).
        wrap.setAttribute("ry", String(rx * 0.32));
        wrap.setAttribute("transform", `rotate(45 0 ${cy})`);
        wrap.style.fill = paint;
        g.appendChild(wrap);
      }
    }
  }

  if (layout.mode === "bucket" && layout.bucketUnit !== undefined) {
    const g = group(dropPx - cfg.knobOffsetPx + 12);
    const caption = document.createElementNS(SVG_NS, "text");
    caption.setAttribute("class", "hsd-quipu-unit");
    caption.setAttribute("x", String(rBead + 5));
    caption.textContent = `×${layout.bucketUnit}`;
    g.appendChild(caption);
  }

  return els;
}
