/**
 * The embeddable façade (integration.md I1/I4): `createHangingStringsDiagram(container, options)` is
 * THE public API every host — vanilla embed, Chart.js controller, ECharts extension, React
 * wrapper — integrates through. It owns the wiring the prototype's main.ts proved is subtle:
 * two renderers kept warm and swapped by visibility (spring state survives mode switches),
 * the ring's rotate fast-path and spin-time LOD, the breeze backdrop synced to the rail's
 * rendered form, theming/texture application, and D17/D20 slid-position state. Doing that once
 * here means every adapter inherits it correctly (I1); the demo panel is just another consumer.
 *
 * Style isolation (I5): the theme's CSS variables and the busy-sheet/dark-chrome attributes are
 * applied to THE CONTAINER, never to document.documentElement — a host page's own styling can't
 * collide unless it deliberately uses the `hsd-` prefix. The container gets the `hsd-container`
 * class (position: relative + the theme's background slot painted on the chart's own box).
 *
 * Events (I4): callbacks fire on committed state changes (a slide's release, a branch toggle,
 * a group selection) — never per animation frame.
 */

import {
  DEFAULT_CONFIG,
  type ColorMode,
  type HangingStringCategory,
  type HangingStringGroup,
} from "./core/types";
import { bringGroupToFront, computeLayout } from "./core/layout";
import { ArcRailForm, WaveRailForm, type PlanarRailForm } from "./core/railForm";
import {
  DEFAULT_HIERARCHY_EXTRAS,
  computeHierarchyLayout,
  findParentOf,
  type HierarchyConfig,
} from "./core/hierarchy";
import { DEFAULT_RING_CONFIG, centerGroupInRing } from "./core/ringLayout";
import { computeRingHierarchyLayout, type RingHierarchyConfig } from "./core/ringHierarchy";
import { STUDIO_THEME, THEMES, type HangingStringsDiagramTheme } from "./core/theme";
import { THREAD_TEXTURES } from "./core/assets/threadTextures";
import { wheelDeltaYPixels } from "./core/wheel";
import { syncLabelContrast } from "./core/labelContrast";
import { applyTheme, themeCssVars } from "./renderers/svg/theme";
import {
  createSheetBackdrop,
  TOP_PROFILE_POINTS,
  type SheetTexture,
} from "./renderers/svg/backdrop";
import { SvgRenderer } from "./renderers/svg/render";
import { RingSvgRenderer } from "./renderers/svg/renderRing";
import type { StringHoverEvent } from "./renderers/svg/hover";

export type RailMode = "straight" | "arc" | "wave" | "ring";
/** D29 (v4): the 2nd-metric encoding modes — none, knob size (D7), heat-map (D8), or quipu
 * knots (D28). */
export type SecondaryEncoding = "none" | "knob" | "heat" | "quipu";
/** Q24 (DECIDED 2026-07-20, user: "no" to opt-in): the breeze backdrop is part of the
 * product's default look — "plain" (the white sheet) is the default everywhere; hosts that
 * don't want the weight/motion pass `backdrop: "off"` explicitly. */
export type BackdropMode = "off" | "plain" | "tablecloth" | "bavarian";

/** A committed slide (D17/D20) — `position` is the arc-length `along` the planar rod for a
 * planar root, an x-offset from the parent's anchor for a planar child, or the base angle in
 * degrees for anything slid in ring mode. */
export interface ReorderEvent {
  id: string;
  parentId: string | null;
  railMode: RailMode;
  position: number;
}

export interface ExpandEvent {
  id: string;
  expanded: boolean;
}

/** Q25: the hovered string's data plus which rail family it was hovered in. */
export interface HoverEvent extends StringHoverEvent {
  railMode: RailMode;
}

export interface HangingStringsDiagramOptions {
  /** The canonical data shape (I3) — adapters convert their host's format to exactly this. */
  categories: HangingStringCategory[];
  groups: HangingStringGroup[];
  railMode?: RailMode;
  /** A THEMES registry key or a full theme object. Unknown keys throw — a host integration
   * bug should fail loudly, not silently render Studio. */
  theme?: string | HangingStringsDiagramTheme;
  /** A THREAD_TEXTURES key overriding the theme's thread texture. Absent = the product
   * default (kernmantle); an explicit null = the theme's own texture. */
  threadTexture?: string | null;
  backdrop?: BackdropMode;
  colorMode?: ColorMode;
  knobEncodesSecondMetric?: boolean;
  /** D29 (v4): ONE switch for how the 2nd metric is encoded — knob size (D7), heat-map color
   * (D8), or khipu knots on the cord (D28, which hides the D6 bead-ticks while active, Q30).
   * When given it WINS over the legacy `colorMode`/`knobEncodesSecondMetric` pair; when
   * absent it derives from them, so v3 configs keep working unchanged. */
  secondaryEncoding?: SecondaryEncoding;
  showTicks?: boolean;
  tickTarget?: number;
  labelValues?: boolean;
  stiffness?: number;
  /** Canvas height in px (the canvas grows below this while branches are expanded). */
  height?: number;
  /** A group was brought to front (or deselected — null). */
  onSelect?: (groupId: string | null) => void;
  /** A string was slid to a new position and released (commit, not per-frame preview). */
  onReorder?: (event: ReorderEvent) => void;
  /** A branch was expanded or collapsed (D16). */
  onExpand?: (event: ExpandEvent) => void;
  /** Q25: a string was hovered (its data + the built-in card's container-px anchor) or
   * un-hovered (`null`) — for a host's own tooltip. Fires on enter/leave, never per frame. */
  onHover?: (event: HoverEvent | null) => void;
  /** Q25: whether the built-in hover info card renders (default true). Hosts replacing it
   * with their own tooltip via `onHover` pass false. */
  showHoverCard?: boolean;
}

/** The per-call option subset `setOptions` patches live. */
export type HangingStringsDiagramDisplayOptions = Partial<
  Pick<
    HangingStringsDiagramOptions,
    "colorMode" | "knobEncodesSecondMetric" | "showTicks" | "tickTarget" | "labelValues" | "stiffness"
  >
>;

export interface HangingStringsDiagram {
  readonly container: HTMLElement;
  /** Replace the data (diffed against current state: surviving strings keep their order and
   * slid positions; state for removed ids is pruned). */
  update(patch: { categories?: HangingStringCategory[]; groups?: HangingStringGroup[] }): void;
  setRailMode(mode: RailMode): void;
  setTheme(theme: string | HangingStringsDiagramTheme): void;
  setThreadTexture(key: string | null): void;
  setBackdrop(mode: BackdropMode): void;
  /** D21.8: multiplies organic breeze intensity on the cords (1 = normal; 0 = calm). */
  setWindScale(scale: number): void;
  /** D29: switch how the 2nd metric is encoded — knob size, heat-map color, or quipu knots
   * (which hide the D6 bead-ticks while active). */
  setSecondaryEncoding(mode: SecondaryEncoding): void;
  setOptions(patch: HangingStringsDiagramDisplayOptions): void;
  /** Group-to-front toggle (D4): fronts the group, dims the rest; toggling the active group
   * deselects it. Ring mode centers the group at the arc's front (angle 0). */
  toggleGroup(groupId: string): void;
  /** D16: expand/collapse a branch by category id (no-op if the id has no children). */
  toggleExpand(id: string): void;
  getActiveGroup(): string | null;
  getRailMode(): RailMode;
  /** Restores base order, collapses branches, clears slid positions/rotations/selection. */
  reset(): void;
  /** Removes everything this instance added to the container and stops all animation. */
  destroy(): void;
}

/** Fixed canvas height default — matches the prototype. */
const DEFAULT_HEIGHT = 460;
/** Responsive width clamp (the container's measured width drives everything between). */
const MIN_WIDTH = 560;
const MAX_WIDTH = 1800;
/** Horizontal margin the ring rail keeps from the canvas edges. */
const RING_EDGE_MARGIN_PX = 50;
/** M2/M3 gentle form parameters (Q17 — a real per-form parameter surface — stays open). */
const ARC_SAG_PX = 48;
const WAVE_AMPLITUDE_PX = 24;
const WAVE_CYCLES = 2;
/** Spin-time LOD (D23): bead-knot density while the disc turns. */
const SPIN_COARSE_TICK_TARGET = 2;
/** D25 (Q13): rail-mode cross-fade duration — slightly past the CSS 850ms opacity transition
 * so the ghost class is removed only after the fade fully lands. */
const MORPH_MS = 920;

/** Product defaults (user, 2026-07-20): the chart's out-of-the-box look is the full physical
 * treatment — Wool & brass theme, kernmantle rope threads, values on the labels' 2nd line,
 * fine knot granularity, very flexible strings, and the white-sheet backdrop (Q24). Every
 * one is overridable per instance. */
const DEFAULT_THEME_KEY = "wool-brass";
const DEFAULT_THREAD_TEXTURE = "kernmantle";
const DEFAULT_LABEL_VALUES = true;
const DEFAULT_TICK_TARGET = 8;
const DEFAULT_STIFFNESS = 0.2;
const DEFAULT_BACKDROP: BackdropMode = "plain";

function resolveTheme(theme: string | HangingStringsDiagramTheme | undefined): HangingStringsDiagramTheme {
  if (theme === undefined) return THEMES[DEFAULT_THEME_KEY] ?? STUDIO_THEME;
  if (typeof theme !== "string") return theme;
  const found = THEMES[theme];
  if (!found) throw new TypeError(`Unknown Hanging Strings Diagram theme key: "${theme}"`);
  return found;
}

export function createHangingStringsDiagram(
  container: HTMLElement,
  options: HangingStringsDiagramOptions
): HangingStringsDiagram {
  // --- state (the prototype's `state`, per instance) ----------------------------------------
  let categories = options.categories;
  let groups = options.groups;
  let baseOrder = categories.map((c) => c.id);
  let theme = resolveTheme(options.theme);
  // undefined = the product default; an explicit null = "the theme's own texture".
  let threadTextureKey =
    options.threadTexture === undefined ? DEFAULT_THREAD_TEXTURE : options.threadTexture;
  let backdropMode: BackdropMode = options.backdrop ?? DEFAULT_BACKDROP;
  let destroyed = false;

  const state = {
    order: [...baseOrder],
    activeGroupId: null as string | null,
    // D29: the consolidated switch wins; absent, it derives from the legacy pair (v3 compat).
    secondaryEncoding: (options.secondaryEncoding ??
      (options.knobEncodesSecondMetric
        ? "knob"
        : options.colorMode === "heatmap"
          ? "heat"
          : "none")) as SecondaryEncoding,
    colorMode: options.colorMode ?? ("group" as ColorMode),
    knobEncodesSecondMetric: options.knobEncodesSecondMetric ?? false,
    stiffness: options.stiffness ?? DEFAULT_STIFFNESS,
    showTicks: options.showTicks ?? true,
    labelValues: options.labelValues ?? DEFAULT_LABEL_VALUES,
    tickTarget: options.tickTarget ?? DEFAULT_TICK_TARGET,
    railMode: options.railMode ?? ("straight" as RailMode),
    ringRotationOffsetDeg: 0,
    ringAngles: new Map<string, number>(),
    subRingRotations: new Map<string, number>(),
    childRingAngles: new Map<string, number>(),
    railPositions: new Map<string, number>(),
    childRailPositions: new Map<string, number>(),
    expandedIds: new Set<string>(),
  };
  // D29: when the consolidated switch was given explicitly, it overrides the legacy pair.
  if (options.secondaryEncoding !== undefined) {
    state.knobEncodesSecondMetric = state.secondaryEncoding === "knob";
    state.colorMode = state.secondaryEncoding === "heat" ? "heatmap" : "group";
  }

  /** D20 retired sibling slot-reorder — children spread in natural data order. */
  const naturalChildOrders = new Map<string, string[]>();

  const height = options.height ?? DEFAULT_HEIGHT;
  const config: HierarchyConfig = {
    ...DEFAULT_CONFIG,
    ...DEFAULT_HIERARCHY_EXTRAS,
    railY: 60,
    maxDropPx: 320,
  };
  const ringConfig: RingHierarchyConfig = {
    ...DEFAULT_RING_CONFIG,
    ...DEFAULT_HIERARCHY_EXTRAS,
  };

  // --- container (I5) -----------------------------------------------------------------------
  container.classList.add("hsd-container");
  applyCurrentTheme(); // vars + data-hsd-dark on the container BEFORE any child renders

  // D27 (zoom & pan): everything the chart paints — backdrop, both svgs, hover cards — lives
  // in one transform layer inside the container. Zooming/panning is a single CSS transform on
  // this layer; the container clips (overflow hidden), so it behaves as a window onto the
  // zoomed scene. All renderer pointer math already converts through live client rects, so
  // interactions keep working at any zoom.
  const zoomLayer = document.createElement("div");
  zoomLayer.className = "hsd-zoom-layer";
  container.appendChild(zoomLayer);

  // --- backdrop (D21) -----------------------------------------------------------------------
  const backdrop = createSheetBackdrop(zoomLayer);

  // --- layout helpers (verbatim semantics from the prototype) -------------------------------
  function currentPlanarForm(order: string[]): PlanarRailForm | undefined {
    if (state.railMode !== "arc" && state.railMode !== "wave") return undefined;
    const probe = computeLayout(categories, order, config);
    return state.railMode === "arc"
      ? new ArcRailForm(config.railY, ARC_SAG_PX, probe.contentWidth)
      : new WaveRailForm(config.railY, WAVE_AMPLITUDE_PX, WAVE_CYCLES, probe.contentWidth);
  }

  function straightLayoutFor(order: string[]) {
    return computeHierarchyLayout(
      categories,
      order,
      naturalChildOrders,
      state.expandedIds,
      {
        ...config,
        knobEncodesSecondMetric: state.knobEncodesSecondMetric,
        tickTarget: effectiveTickTarget(),
      },
      currentPlanarForm(order),
      state.railPositions,
      state.childRailPositions
    );
  }

  function ringLayoutFor(order: string[]) {
    return computeRingHierarchyLayout(
      categories,
      order,
      naturalChildOrders,
      state.expandedIds,
      {
        ...ringConfig,
        colorMode: state.colorMode,
        knobEncodesSecondMetric: state.knobEncodesSecondMetric,
        tickTarget: effectiveTickTarget(),
        rotationOffsetDeg: state.ringRotationOffsetDeg,
      },
      state.ringAngles,
      state.subRingRotations,
      state.childRingAngles
    );
  }

  function toggleExpand(id: string) {
    const expanded = !state.expandedIds.has(id);
    if (expanded) state.expandedIds.add(id);
    else state.expandedIds.delete(id);
    rerender();
    options.onExpand?.({ id, expanded });
  }

  // --- renderers (both warm; visibility-swapped so spring state survives mode switches) -----
  const renderer = new SvgRenderer(zoomLayer, {
    width: 820,
    height,
    groups,
    categories,
    colorMode: state.colorMode,
    stiffness: state.stiffness,
    showTicks: state.showTicks,
    labelValues: state.labelValues,
    quipuKnots: state.secondaryEncoding === "quipu",
    theme: effectiveTheme(),
    onSlide: (id, position) => {
      const parent = findParentOf(categories, id);
      if (parent) state.childRailPositions.set(id, position);
      else state.railPositions.set(id, position);
      rerender();
      options.onReorder?.({ id, parentId: parent?.id ?? null, railMode: state.railMode, position });
    },
    onToggleExpand: toggleExpand,
    onGroupToggle: (groupId) => toggleGroup(groupId),
    onHover: options.onHover
      ? (ev) => options.onHover!(ev ? { ...ev, railMode: state.railMode } : null)
      : undefined,
    showHoverCard: options.showHoverCard,
  });

  const ringRenderer = new RingSvgRenderer(zoomLayer, {
    width: 820,
    height,
    groups,
    theme: effectiveTheme(),
    colorMode: state.colorMode,
    showTicks: state.showTicks,
    labelValues: state.labelValues,
    quipuKnots: state.secondaryEncoding === "quipu",
    stiffness: state.stiffness,
    onRotate: (deltaDeg) => {
      state.ringRotationOffsetDeg += deltaDeg;
      // Fast path: retarget anchors only — a full render would rebuild colors/labels/aria
      // every frame of the spin.
      ringRenderer.retargetForRotate(ringLayoutFor(state.order));
    },
    onRotateGestureStart: () => beginSpinLod(),
    onSettle: () => endSpinLod(),
    onSubRotate: (parentId, deltaDeg) => {
      state.subRingRotations.set(parentId, (state.subRingRotations.get(parentId) ?? 0) + deltaDeg);
      renderRingOnly(state.order);
    },
    onSlide: (id, angleDeg) => {
      const parent = findParentOf(categories, id);
      let position: number;
      if (parent) {
        position = angleDeg - (state.subRingRotations.get(parent.id) ?? 0);
        state.childRingAngles.set(id, position);
      } else {
        position = angleDeg - state.ringRotationOffsetDeg;
        state.ringAngles.set(id, position);
      }
      renderRingOnly(state.order);
      options.onReorder?.({ id, parentId: parent?.id ?? null, railMode: "ring", position });
    },
    onToggleExpand: toggleExpand,
    onHover: options.onHover
      ? (ev) => options.onHover!(ev ? { ...ev, railMode: "ring" } : null)
      : undefined,
    showHoverCard: options.showHoverCard,
  });

  // --- spin-time LOD (D23) ------------------------------------------------------------------
  // The user's tickTarget is never mutated by a spin — the coarse density is a transient
  // overlay resolved at layout time, so no dial-sync plumbing leaks out of the façade.
  let spinLodActive = false;

  function effectiveTickTarget(): number {
    return spinLodActive ? Math.min(state.tickTarget, SPIN_COARSE_TICK_TARGET) : state.tickTarget;
  }

  function beginSpinLod() {
    backdrop.setSuspended(true);
    if (spinLodActive) return; // already in a spin session (e.g. re-grab)
    spinLodActive = true;
    if (state.tickTarget !== effectiveTickTarget()) renderRingOnly(state.order);
  }

  function endSpinLod() {
    backdrop.setSuspended(false);
    if (!spinLodActive) return;
    const wasCoarse = state.tickTarget !== effectiveTickTarget();
    spinLodActive = false;
    if (wasCoarse) renderRingOnly(state.order);
  }

  // --- rendering ----------------------------------------------------------------------------
  function renderRingOnly(order: string[]) {
    ringRenderer.render(ringLayoutFor(order));
  }

  function rerender() {
    // Only layout+render the visible rail mode — the hidden SVG stays mounted (spring state
    // intact); a mode switch always rerenders so the newly visible view catches up.
    if (state.railMode !== "ring") renderer.render(straightLayoutFor(state.order));
    else renderRingOnly(state.order);
    syncBackdropTop();
  }

  function toggleGroup(groupId: string) {
    if (state.activeGroupId === groupId) {
      state.activeGroupId = null;
      state.order = [...baseOrder];
    } else {
      state.activeGroupId = groupId;
      if (state.railMode === "ring") {
        // Ring-specific D4: "front" is the arc's visual center (angle 0) — also reset manual
        // spin and slid angles so the centered order's even spread is what fronts.
        state.order = centerGroupInRing(categories, state.order, groupId);
        state.ringRotationOffsetDeg = 0;
        state.ringAngles = new Map();
      } else {
        state.order = bringGroupToFront(categories, state.order, groupId);
        state.railPositions = new Map();
      }
    }
    renderer.setActiveGroup(state.activeGroupId);
    ringRenderer.setActiveGroup(state.activeGroupId);
    rerender();
    options.onSelect?.(state.activeGroupId);
  }

  // --- D25.1: the rail's own metamorphosis ------------------------------------------------
  // The strings glide, but a cross-fade alone never shows the ROD becoming the RING. During a
  // planar↔ring morph both real rods hide and a transient overlay path interpolates between
  // their sampled geometries — the rod visibly curls into the ellipse (its middle sweeping
  // over the back rim, the ends meeting at the left edge) and uncurls back.
  const RAIL_MORPH_SAMPLES = 72;
  let railMorphCleanup: (() => void) | null = null;

  function cancelRailMorph() {
    railMorphCleanup?.();
  }

  function chartSvgs(): SVGSVGElement[] {
    return [...container.querySelectorAll<SVGSVGElement>("svg.hsd-svg")];
  }

  /** The planar rod's rendered geometry in container px (works for straight/arc/wave). */
  function samplePlanarRodPx(): { x: number; y: number }[] | null {
    const svg = chartSvgs().find((s) => !s.getAttribute("aria-label")?.includes("ring"));
    const rail = svg?.querySelector<SVGGeometryElement>(".hsd-rail");
    const ctm = rail?.getScreenCTM();
    if (!rail || !ctm || typeof rail.getTotalLength !== "function") return null;
    const total = rail.getTotalLength();
    if (!(total > 0)) return null;
    const rect = container.getBoundingClientRect();
    const pts: { x: number; y: number }[] = [];
    for (let i = 0; i < RAIL_MORPH_SAMPLES; i++) {
      const p = rail.getPointAtLength((i / (RAIL_MORPH_SAMPLES - 1)) * total);
      pts.push({
        x: ctm.a * p.x + ctm.c * p.y + ctm.e - rect.left,
        y: ctm.b * p.x + ctm.d * p.y + ctm.f - rect.top,
      });
    }
    return pts;
  }

  /** The ring rail ellipse in container px, parameterized so index 0 is the LEFT edge, the
   * first half sweeps the BACK rim and the second half returns across the front — pairing
   * index-for-index with the rod's left→right samples, so the interpolation reads as the rod
   * curling into a loop rather than scrambling. */
  function sampleRingEllipsePx(): { x: number; y: number }[] | null {
    const svg = chartSvgs().find((s) => s.getAttribute("aria-label")?.includes("ring"));
    if (!svg || svg.style.display === "none") return null;
    const svgRect = svg.getBoundingClientRect();
    if (!(svgRect.width > 0)) return null;
    const rect = container.getBoundingClientRect();
    const s = svgRect.width / chartWidth;
    const offsetY = svgRect.top - rect.top;
    const pts: { x: number; y: number }[] = [];
    for (let i = 0; i < RAIL_MORPH_SAMPLES; i++) {
      const theta = (i / (RAIL_MORPH_SAMPLES - 1)) * 2 * Math.PI;
      pts.push({
        x: (ringConfig.centerX - ringConfig.radiusX * Math.cos(theta)) * s,
        y: (ringConfig.centerY - ringConfig.radiusY * Math.sin(theta)) * s + offsetY,
      });
    }
    return pts;
  }

  function beginRailMorph(
    fromPts: { x: number; y: number }[] | null,
    toPts: { x: number; y: number }[] | null,
    durationMs: number
  ) {
    cancelRailMorph();
    if (!fromPts || !toPts || fromPts.length !== toPts.length) return;
    const rect = container.getBoundingClientRect();
    const overlay = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    overlay.setAttribute("class", "hsd-morph-rail");
    overlay.setAttribute("viewBox", `0 0 ${Math.max(1, rect.width)} ${Math.max(1, rect.height)}`);
    overlay.setAttribute("preserveAspectRatio", "none");
    overlay.setAttribute("aria-hidden", "true");
    const rod = document.createElementNS("http://www.w3.org/2000/svg", "path");
    overlay.appendChild(rod);
    container.appendChild(overlay);
    // Only each svg's MAIN rod hides (querySelector = first .hsd-rail); sub/mini rails keep
    // riding the svg cross-fade.
    const hiddenRods = chartSvgs()
      .map((svg) => svg.querySelector<SVGGraphicsElement>(".hsd-rail"))
      .filter((r): r is SVGGraphicsElement => r !== null);
    for (const r of hiddenRods) r.style.visibility = "hidden";

    let raf: number | null = null;
    const start = performance.now();
    const easeInOutCubic = (t: number) =>
      t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
    const cleanup = () => {
      if (raf !== null) cancelAnimationFrame(raf);
      overlay.remove();
      for (const r of hiddenRods) r.style.visibility = "";
      railMorphCleanup = null;
    };
    railMorphCleanup = cleanup;
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / durationMs);
      const k = easeInOutCubic(t);
      let d = "";
      for (let i = 0; i < fromPts.length; i++) {
        const x = fromPts[i].x + (toPts[i].x - fromPts[i].x) * k;
        const y = fromPts[i].y + (toPts[i].y - fromPts[i].y) * k;
        d += `${i === 0 ? "M" : " L"} ${x.toFixed(1)} ${y.toFixed(1)}`;
      }
      rod.setAttribute("d", d);
      if (t < 1) raf = requestAnimationFrame(tick);
      else cleanup();
    };
    raf = requestAnimationFrame(tick);
  }

  /** D21.5/D21.6: pin the backdrop cloth's top edge to the visible rail's rendered form. */
  function syncBackdropTop() {
    requestAnimationFrame(() => {
      if (destroyed) return;
      // D25: during a rail-mode morph BOTH svgs render — the outgoing ghost must not win the
      // rail measurement; the cloth re-pins to the incoming mode's rail immediately.
      const visible = [...container.querySelectorAll<SVGSVGElement>("svg.hsd-svg")].find(
        (s) => s.style.display !== "none" && !s.classList.contains("hsd-morph-ghost")
      );
      const rail = visible?.querySelector<SVGGeometryElement>(".hsd-rail");
      const ctm = rail?.getScreenCTM();
      if (!rail || !ctm || typeof rail.getTotalLength !== "function") return;
      // D27: the backdrop lives INSIDE the zoom layer, so its coordinates are the layer's
      // LOCAL (untransformed) px — screen samples divide out the current zoom.
      const layerRect = zoomLayer.getBoundingClientRect();
      const localWidth = zoomLayer.clientWidth || layerRect.width;
      if (!(layerRect.width > 0) || !(localWidth > 0)) return;
      const zoomNow = layerRect.width / localWidth;
      const total = rail.getTotalLength();
      if (!(total > 0)) return;

      const GEOM_SAMPLES = 96;
      const pts: { x: number; y: number }[] = [];
      for (let i = 0; i <= GEOM_SAMPLES; i++) {
        const p = rail.getPointAtLength((i / GEOM_SAMPLES) * total);
        pts.push({
          x: (ctm.a * p.x + ctm.c * p.y + ctm.e - layerRect.left) / zoomNow,
          y: (ctm.b * p.x + ctm.d * p.y + ctm.f - layerRect.top) / zoomNow,
        });
      }

      // D21.7: the cloth's horizontal span IS the rendered rail's extent — the sheet hangs
      // exactly as wide as the diagram, not as wide as the hosting container. The top profile
      // is sampled across that same span (the cloth's u = 0..1 maps onto it).
      const railMinX = Math.min(...pts.map((p) => p.x));
      const railMaxX = Math.max(...pts.map((p) => p.x));
      if (!(railMaxX > railMinX)) return;
      backdrop.setSpan(railMinX, railMaxX, localWidth);

      const halfBucket = (railMaxX - railMinX) / (TOP_PROFILE_POINTS - 1) / 2 + 1;
      const profile: number[] = new Array(TOP_PROFILE_POINTS).fill(Infinity);
      for (let i = 0; i < TOP_PROFILE_POINTS; i++) {
        const x = railMinX + (i / (TOP_PROFILE_POINTS - 1)) * (railMaxX - railMinX);
        for (const p of pts) {
          if (Math.abs(p.x - x) <= halfBucket && p.y < profile[i]) profile[i] = p.y;
        }
      }
      if (profile.every((y) => !Number.isFinite(y))) return;
      for (let i = 0; i < profile.length; i++) {
        if (!Number.isFinite(profile[i])) {
          const known = profile.findIndex(Number.isFinite);
          let nearest = Infinity;
          for (let j = 0; j < profile.length; j++) {
            if (Number.isFinite(profile[j]) && Math.abs(j - i) < Math.abs(nearest - i)) nearest = j;
          }
          profile[i] = profile[nearest === Infinity ? known : nearest];
        }
      }
      backdrop.setTop(profile.map((y) => y + 2));
    });
  }

  // --- theming (I5: everything lands on the container) --------------------------------------
  function effectiveTheme(): HangingStringsDiagramTheme {
    const entry = threadTextureKey === null ? undefined : THREAD_TEXTURES[threadTextureKey];
    if (!entry) return theme;
    return {
      ...theme,
      thread: {
        ...theme.thread,
        texture: entry.texture,
        strokeWidth: Math.max(theme.thread.strokeWidth, 5),
        strokeDash: null,
      },
    };
  }

  function applyCurrentTheme() {
    applyTheme(container, effectiveTheme());
    // Night gallery (and other host CSS) may override background-color after vars land;
    // re-check once styles have flushed so labels match the painted ground.
    requestAnimationFrame(() => syncLabelContrast(container));
  }

  function applyThemeEverywhere() {
    const eff = effectiveTheme();
    applyTheme(container, eff);
    requestAnimationFrame(() => syncLabelContrast(container));
    ringRenderer.setTheme(eff);
    renderer.setTheme(eff);
    syncBackdropTop(); // a new rail stroke width shifts the rail's measured top edge
  }

  function applyBackdropMode() {
    const sheetOn = backdropMode !== "off";
    if (sheetOn) backdrop.setTexture(backdropMode as SheetTexture);
    backdrop.setEnabled(sheetOn);

    // D21.8: wind toggle is always available — breeze stirs cords with or without a sheet.
    // Sheet wave motion only runs when a cloth is actually up.
    breezeBtn.hidden = false;
    applyBreezeMotion(breezeActive, { remember: false });

    // D9.2: over a patterned cloth the labels step up — stamped on the CONTAINER (I5).
    container.toggleAttribute("data-hsd-busy-sheet", sheetOn && backdropMode !== "plain");
  }

  // --- D21.8: breeze toggle -----------------------------------------------------------------
  function prefersReducedMotion(): boolean {
    return (
      typeof matchMedia === "function" &&
      matchMedia("(prefers-reduced-motion: reduce)").matches
    );
  }

  function isCoarsePointerHost(): boolean {
    if (typeof matchMedia !== "function") return false;
    return (
      matchMedia("(pointer: coarse)").matches || matchMedia("(hover: none)").matches
    );
  }

  /** Parked by default on touch / reduced-motion; desktop fine-pointer starts with breeze on. */
  let breezeActive = !isCoarsePointerHost() && !prefersReducedMotion();

  const chrome = document.createElement("div");
  chrome.className = "hsd-chrome";
  container.appendChild(chrome);

  const breezeBtn = document.createElement("button");
  breezeBtn.type = "button";
  breezeBtn.className = "hsd-breeze-toggle";
  breezeBtn.setAttribute("aria-label", "Breeze");
  breezeBtn.innerHTML =
    `<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false">` +
    `<path fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" ` +
    `stroke-linejoin="round" ` +
    `d="M3.5 8.5h9.5a2.75 2.75 0 1 0-2.75-2.75M3.5 12.5h13a2.75 2.75 0 1 1-2.75 2.75M3.5 16.5h7a2.25 2.25 0 1 1-2.25 2.25"/>` +
    `</svg>`;
  chrome.appendChild(breezeBtn);

  function applyBreezeMotion(on: boolean, opts?: { remember?: boolean }) {
    if (opts?.remember !== false) breezeActive = on;
    const sheetOn = backdropMode !== "off";
    // Cloth waves only when a sheet is visible; cord wind is independent.
    backdrop.setIntensityScale(on && sheetOn ? 1 : 0);
    backdrop.setMotionEnabled(on && sheetOn);
    const scale = on ? windScale : 0;
    renderer.setWindScale(scale);
    ringRenderer.setWindScale(scale);
    renderer.setWind(on);
    ringRenderer.setWind(on);
    breezeBtn.setAttribute("aria-pressed", on ? "true" : "false");
    breezeBtn.classList.toggle("hsd-breeze-on", on);
    breezeBtn.title = on ? "Turn breeze off" : "Turn breeze on";
  }

  /** Multiplier for cord wind while breeze is on (thumbs / demos may raise this). */
  let windScale = 1;

  function toggleBreezeFromUser(ev: Event) {
    ev.preventDefault();
    ev.stopPropagation();
    if (destroyed) return;
    applyBreezeMotion(!breezeActive);
  }

  // touchend is the reliable path on iOS (pointer events are flaky on controls over SVG).
  // preventDefault on touchend suppresses the synthetic click so we do not double-toggle.
  let breezeTouchGuard = false;
  breezeBtn.addEventListener(
    "touchend",
    (ev) => {
      breezeTouchGuard = true;
      toggleBreezeFromUser(ev);
    },
    { passive: false }
  );
  breezeBtn.addEventListener("click", (ev) => {
    if (breezeTouchGuard) {
      breezeTouchGuard = false;
      ev.preventDefault();
      ev.stopPropagation();
      return;
    }
    toggleBreezeFromUser(ev);
  });
  breezeBtn.addEventListener("pointerdown", (ev) => {
    ev.stopPropagation();
  });

  function removeBreezeToggle() {
    chrome.remove();
  }

  // --- D27: zoom & pan ----------------------------------------------------------------------
  // The chart is a window onto the zoomed scene: pinch / Ctrl(⌘)+wheel zooms toward the
  // cursor (plain wheel joins in once already zoomed, so page scrolling stays untouched at
  // base zoom), dragging any NON-interactive spot pans, double-click zooms in / resets.
  // Strings and discs keep every gesture they had — the pan only claims the background.
  const ZOOM_MAX = 6;
  const PAN_IGNORE = ".hsd-hit, .hsd-knob-hit, .hsd-plate-hit, .hsd-hover-card, .hsd-breeze-toggle";
  let zoom = 1;
  let panX = 0;
  let panY = 0;
  let panDrag: { pointerId: number; startX: number; startY: number; x0: number; y0: number } | null =
    null;

  function applyZoomTransform() {
    // translate3d keeps a Firefox compositor layer so scale is visible inside
    // parents that use backdrop-filter (demo panel blur).
    zoomLayer.style.transform =
      zoom === 1 && panX === 0 && panY === 0
        ? ""
        : `translate3d(${panX}px, ${panY}px, 0) scale(${zoom})`;
    container.classList.toggle("hsd-zoomed", zoom > 1);
  }

  function clampPan() {
    const w = zoomLayer.clientWidth;
    const h = zoomLayer.clientHeight;
    panX = Math.min(0, Math.max(w - w * zoom, panX));
    panY = Math.min(0, Math.max(h - h * zoom, panY));
  }

  function zoomAt(clientX: number, clientY: number, factor: number) {
    setZoomAround(clientX, clientY, zoom * factor);
  }

  /** Absolute zoom toward a client point (used by wheel factoring and touch pinch). */
  function setZoomAround(clientX: number, clientY: number, nextZoom: number) {
    const next = Math.min(ZOOM_MAX, Math.max(1, nextZoom));
    if (next === zoom) {
      clampPan();
      applyZoomTransform();
      return;
    }
    const rect = container.getBoundingClientRect();
    const px = clientX - rect.left;
    const py = clientY - rect.top;
    panX = px - ((px - panX) / zoom) * next;
    panY = py - ((py - panY) / zoom) * next;
    zoom = next;
    clampPan();
    applyZoomTransform();
  }

  function resetZoom() {
    zoom = 1;
    panX = 0;
    panY = 0;
    applyZoomTransform();
  }

  const onZoomWheel = (ev: WheelEvent) => {
    // D27.5: only handle wheels whose target lies inside this chart (listener is on window
    // capture — required so Firefox does not hand the gesture to page APZ first).
    const t = ev.target;
    if (!(t instanceof Node) || !container.contains(t)) return;

    // D27.1: plain scrolling zooms — no modifier. Pinch (ctrlKey+wheel) keeps a stronger
    // factor (trackpad pinch deltas are small). D27.4: normalize LINE/PAGE (Firefox).
    // D27.5: always claim the wheel inside the grey frame (page scrolls only outside).
    const pinch = ev.ctrlKey || ev.metaKey;
    let deltaY = wheelDeltaYPixels(ev, typeof window !== "undefined" ? window.innerHeight : 800);
    if (deltaY === 0) return;
    // Floor tiny trackpad ticks so Firefox pixel-mode dribbles still move the zoom.
    if (!pinch && Math.abs(deltaY) < 4) deltaY = Math.sign(deltaY) * 4;

    const factor = Math.exp(-deltaY * (pinch ? 0.01 : 0.003));
    const next = Math.min(ZOOM_MAX, Math.max(1, zoom * factor));
    ev.preventDefault();
    ev.stopPropagation();
    if (next === zoom) return;
    zoomAt(ev.clientX, ev.clientY, factor);
  };
  const onPanDown = (ev: PointerEvent) => {
    if (zoom === 1 || ev.button !== 0) return;
    if ((ev.target as Element | null)?.closest?.(PAN_IGNORE)) return;
    // Two-finger pinch owns the gesture — do not start a one-finger pan.
    if (typeof (ev as PointerEvent & { isPrimary?: boolean }).isPrimary === "boolean" && !ev.isPrimary)
      return;
    // D27.3: claim the gesture before the browser starts a page scroll (esp. touch).
    ev.preventDefault();
    panDrag = { pointerId: ev.pointerId, startX: ev.clientX, startY: ev.clientY, x0: panX, y0: panY };
    container.classList.add("hsd-panning");
    try {
      container.setPointerCapture(ev.pointerId);
    } catch {
      /* synthetic pointers may not support capture */
    }
  };
  const onPanMove = (ev: PointerEvent) => {
    if (!panDrag || ev.pointerId !== panDrag.pointerId) return;
    ev.preventDefault();
    panX = panDrag.x0 + (ev.clientX - panDrag.startX);
    panY = panDrag.y0 + (ev.clientY - panDrag.startY);
    clampPan();
    applyZoomTransform();
  };
  const onPanUp = (ev: PointerEvent) => {
    if (!panDrag || ev.pointerId !== panDrag.pointerId) return;
    panDrag = null;
    container.classList.remove("hsd-panning");
  };
  const onZoomDblClick = (ev: MouseEvent) => {
    if ((ev.target as Element | null)?.closest?.(PAN_IGNORE)) return;
    if (zoom === 1) zoomAt(ev.clientX, ev.clientY, 2.5);
    else resetZoom();
  };

  // D27.2: two-finger pinch zoom on touch devices (iOS does not send ctrlKey+wheel for pinch).
  let pinch:
    | { startDist: number; startZoom: number; cx: number; cy: number }
    | null = null;

  function touchDistance(a: Touch, b: Touch): number {
    return Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
  }

  const onPinchStart = (ev: TouchEvent) => {
    if (ev.touches.length !== 2) {
      pinch = null;
      return;
    }
    if ((ev.target as Element | null)?.closest?.(".hsd-breeze-toggle")) return;
    panDrag = null;
    container.classList.remove("hsd-panning");
    const a = ev.touches[0];
    const b = ev.touches[1];
    pinch = {
      startDist: Math.max(1, touchDistance(a, b)),
      startZoom: zoom,
      cx: (a.clientX + b.clientX) / 2,
      cy: (a.clientY + b.clientY) / 2,
    };
    // D27.3: once a pinch is claimed, block page scroll for the rest of the gesture.
    ev.preventDefault();
  };
  const onPinchMove = (ev: TouchEvent) => {
    if (!pinch || ev.touches.length !== 2) return;
    ev.preventDefault();
    const dist = Math.max(1, touchDistance(ev.touches[0], ev.touches[1]));
    setZoomAround(pinch.cx, pinch.cy, pinch.startZoom * (dist / pinch.startDist));
  };
  const onPinchEnd = (ev: TouchEvent) => {
    if (ev.touches.length < 2) pinch = null;
  };

  // D27.5: window capture so Firefox cannot commit the wheel to page-scroll APZ before we
  // see it. Handler no-ops unless the event target is inside this container.
  window.addEventListener("wheel", onZoomWheel, { passive: false, capture: true });
  // D27.3: non-passive so preventDefault can stop page scroll while panning (touch).
  container.addEventListener("pointerdown", onPanDown, { passive: false });
  container.addEventListener("pointermove", onPanMove, { passive: false });
  container.addEventListener("pointerup", onPanUp);
  container.addEventListener("pointercancel", onPanUp);
  container.addEventListener("dblclick", onZoomDblClick);
  // touchstart must be non-passive so a 2-finger pinch can preventDefault immediately.
  container.addEventListener("touchstart", onPinchStart, { passive: false });
  container.addEventListener("touchmove", onPinchMove, { passive: false });
  container.addEventListener("touchend", onPinchEnd);
  container.addEventListener("touchcancel", onPinchEnd);

  function removeZoomListeners() {
    window.removeEventListener("wheel", onZoomWheel, { capture: true });
    container.removeEventListener("pointerdown", onPanDown);
    container.removeEventListener("pointermove", onPanMove);
    container.removeEventListener("pointerup", onPanUp);
    container.removeEventListener("pointercancel", onPanUp);
    container.removeEventListener("dblclick", onZoomDblClick);
    container.removeEventListener("touchstart", onPinchStart);
    container.removeEventListener("touchmove", onPinchMove);
    container.removeEventListener("touchend", onPinchEnd);
    container.removeEventListener("touchcancel", onPinchEnd);
  }

  // --- responsive sizing --------------------------------------------------------------------
  let chartWidth = 820;
  function applyChartWidth(width: number) {
    const next = Math.round(Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, width)));
    if (Math.abs(next - chartWidth) < 2) return;
    chartWidth = next;
    renderer.resize(next);
    ringRenderer.resize(next);
    ringConfig.centerX = next / 2;
    ringConfig.radiusX = next / 2 - RING_EDGE_MARGIN_PX;
    rerender();
  }

  const resizeObserver =
    typeof ResizeObserver === "function"
      ? new ResizeObserver((entries) => {
          const width = entries[0]?.contentRect.width;
          if (width) applyChartWidth(width);
        })
      : null;
  resizeObserver?.observe(container);

  // --- initial paint ------------------------------------------------------------------------
  const initialPlanar = state.railMode !== "ring";
  renderer.setVisible(initialPlanar);
  ringRenderer.setVisible(!initialPlanar);
  applyBackdropMode();
  applyChartWidth(container.clientWidth || 820);
  rerender();

  // --- the instance -------------------------------------------------------------------------
  return {
    container,

    update(patch) {
      if (patch.groups) {
        groups = patch.groups;
        renderer.setOptions({ groups });
        ringRenderer.setOptions({ groups });
        if (state.activeGroupId && !groups.some((g) => g.id === state.activeGroupId)) {
          state.activeGroupId = null;
          renderer.setActiveGroup(null);
          ringRenderer.setActiveGroup(null);
        }
      }
      if (patch.categories) {
        categories = patch.categories;
        baseOrder = categories.map((c) => c.id);
        const known = new Set(baseOrder);
        // Surviving strings keep their order; new ones append in data order.
        state.order = [
          ...state.order.filter((id) => known.has(id)),
          ...baseOrder.filter((id) => !state.order.includes(id)),
        ];
        const knownOrChild = (id: string) =>
          known.has(id) || categories.some((c) => c.children?.some((ch) => ch.id === id));
        for (const map of [
          state.ringAngles,
          state.railPositions,
          state.childRingAngles,
          state.childRailPositions,
          state.subRingRotations,
        ]) {
          for (const id of [...map.keys()]) if (!knownOrChild(id)) map.delete(id);
        }
        for (const id of [...state.expandedIds]) if (!known.has(id)) state.expandedIds.delete(id);
        renderer.setOptions({ categories });
      }
      rerender();
    },

    setRailMode(mode) {
      if (mode === state.railMode) return;
      const wasPlanar = state.railMode !== "ring";
      const isPlanar = mode !== "ring";
      state.railMode = mode;
      const reducedMotionQuery =
        typeof matchMedia === "function" &&
        matchMedia("(prefers-reduced-motion: reduce)").matches;
      // Planar↔planar (straight/arc/wave) is the same renderer, but D25.2 makes the change a
      // visible metamorphosis too: without it the rod's path SNAPS to the new form and the
      // anchors chase it in ~50ms. The same overlay rod bends between the two sampled forms
      // while the strings ripple to their new heights at the sweep chase rates.
      if (wasPlanar === isPlanar) {
        if (reducedMotionQuery) {
          rerender();
          return;
        }
        const railFrom = samplePlanarRodPx();
        renderer.beginFormSweep();
        rerender();
        const railTo = samplePlanarRodPx();
        beginRailMorph(railFrom, railTo, MORPH_MS);
        return;
      }
      // D25 (Q13 decided: MORPH, not instant): hand the outgoing renderer's live anchor
      // positions to the incoming one — every string's spring starts where the string
      // currently IS on screen and glides to its new-geometry anchor — while the two svgs
      // cross-fade (the outgoing one ghosts in place). Reduced motion keeps the old instant
      // switch.
      const from = wasPlanar ? renderer : ringRenderer;
      const to = isPlanar ? renderer : ringRenderer;
      if (reducedMotionQuery) {
        renderer.setVisible(isPlanar);
        ringRenderer.setVisible(!isPlanar);
        rerender();
        return;
      }
      to.seedAnchorScreenPositions(from.captureAnchorScreenPositions());
      // D25.1: the rail's own metamorphosis — capture the outgoing rod's geometry while it
      // still stands, sample the incoming one right after it renders, and let the overlay
      // rod bend between them.
      const railFrom = wasPlanar ? samplePlanarRodPx() : sampleRingEllipsePx();
      from.morphOut(MORPH_MS);
      to.morphIn(MORPH_MS); // makes `to` visible — rerender() below renders + applies the seed
      rerender();
      const railTo = isPlanar ? samplePlanarRodPx() : sampleRingEllipsePx();
      beginRailMorph(railFrom, railTo, MORPH_MS);
    },

    setTheme(next) {
      theme = resolveTheme(next);
      applyThemeEverywhere();
    },

    setThreadTexture(key) {
      if (key !== null && !THREAD_TEXTURES[key]) {
        throw new TypeError(`Unknown Hanging Strings Diagram thread texture key: "${key}"`);
      }
      threadTextureKey = key;
      applyThemeEverywhere();
    },

    setBackdrop(mode) {
      backdropMode = mode;
      applyBackdropMode();
      syncBackdropTop();
    },

    setWindScale(scale) {
      windScale = Number.isFinite(scale) ? Math.max(0, scale) : 1;
      if (breezeActive) applyBreezeMotion(true, { remember: false });
    },

    setSecondaryEncoding(mode) {
      if (mode === state.secondaryEncoding) return;
      state.secondaryEncoding = mode;
      // The one switch drives all three underlying mechanisms (D7 knob / D8 heat / D28 quipu).
      state.knobEncodesSecondMetric = mode === "knob";
      state.colorMode = mode === "heat" ? "heatmap" : "group";
      const quipu = mode === "quipu";
      renderer.setOptions({ colorMode: state.colorMode, quipuKnots: quipu });
      ringRenderer.setOptions({ colorMode: state.colorMode, quipuKnots: quipu });
      rerender();
    },

    setOptions(patch) {
      if (patch.colorMode !== undefined) {
        state.colorMode = patch.colorMode;
        renderer.setOptions({ colorMode: patch.colorMode });
        ringRenderer.setOptions({ colorMode: patch.colorMode });
      }
      if (patch.stiffness !== undefined) {
        state.stiffness = patch.stiffness;
        renderer.setOptions({ stiffness: patch.stiffness });
        ringRenderer.setOptions({ stiffness: patch.stiffness });
      }
      if (patch.showTicks !== undefined) {
        state.showTicks = patch.showTicks;
        renderer.setOptions({ showTicks: patch.showTicks });
        ringRenderer.setOptions({ showTicks: patch.showTicks });
      }
      if (patch.labelValues !== undefined) {
        state.labelValues = patch.labelValues;
        renderer.setOptions({ labelValues: patch.labelValues });
        ringRenderer.setOptions({ labelValues: patch.labelValues });
      }
      if (patch.knobEncodesSecondMetric !== undefined) {
        state.knobEncodesSecondMetric = patch.knobEncodesSecondMetric;
      }
      if (patch.tickTarget !== undefined) state.tickTarget = patch.tickTarget;
      rerender();
    },

    toggleGroup,

    toggleExpand,

    getActiveGroup: () => state.activeGroupId,
    getRailMode: () => state.railMode,

    reset() {
      state.order = [...baseOrder];
      state.activeGroupId = null;
      state.ringRotationOffsetDeg = 0;
      state.ringAngles = new Map();
      state.subRingRotations = new Map();
      state.childRingAngles = new Map();
      state.railPositions = new Map();
      state.childRailPositions = new Map();
      state.expandedIds = new Set();
      renderer.setActiveGroup(null);
      ringRenderer.setActiveGroup(null);
      rerender();
      options.onSelect?.(null);
    },

    destroy() {
      if (destroyed) return;
      destroyed = true;
      cancelRailMorph();
      removeZoomListeners();
      removeBreezeToggle();
      resizeObserver?.disconnect();
      backdrop.dispose();
      renderer.destroy();
      ringRenderer.destroy();
      zoomLayer.remove();
      container.classList.remove("hsd-container", "hsd-zoomed", "hsd-panning");
      container.removeAttribute("data-hsd-busy-sheet");
      container.removeAttribute("data-hsd-dark");
      for (const name of Object.keys(themeCssVars(effectiveTheme()))) {
        container.style.removeProperty(name);
      }
    },
  };
}
