/**
 * D19: the ring-rail assembly — the reusable "spinnable disc" component. One instance bundles
 * everything a perspective ring rail is made of:
 *
 *   - the vinyl plate (D13 follow-up) — the filled disc inside the rail ellipse;
 *   - the D18 spin-affordance arrows lying on the plate surface, rotating on their inertia
 *     spring and foreshortening per-point through the squashed-ellipse projection;
 *   - the rail ellipse itself (the rod strings hang from);
 *   - optionally the D13 compass ruler (graduated marks around the full ellipse);
 *   - the Q12b rotate gesture: drag anywhere on the disc to spin it, deltas coalesced per
 *     animation frame and reported through `onRotate`.
 *
 * Extracted from RingSvgRenderer so the exact same component serves both the top-level ring and
 * each expanded parent's D16.1 mini ring — the branch doesn't just LOOK like its parent rail, it
 * IS the same rail, at a smaller geometry (all arrow/plate proportions are fractions of the
 * disc's semi-axes, so they scale for free), with its own rotation offset.
 *
 * The component owns no animation loop: the renderer's existing rAF tick drives it by calling
 * `flushRotation()` (forward coalesced drag deltas to the caller, which re-renders) and then
 * `step(dt)` (advance the arrow spring). Geometry is pushed in via `setGeometry` — every frame
 * for mini rings, whose disc rides the parent string's live knob.
 */

import {
  computeRailTicks,
  type RailTick,
  type RingConfig,
} from "../../core/ringLayout";

const SVG_NS = "http://www.w3.org/2000/svg";

/** D18 arrow geometry (see wiki/design/visual-design.md): every radius is a FRACTION of the
 * plate's semi-axes, every angle a sweep around the disc — one set of numbers serves any disc
 * size, from the 360px main ring to a 30px branch ring. */
const ARROW_CENTERS_DEG = [90, 270];
const ARROW_BAND_SWEEP_DEG = 72;
const ARROW_HEAD_SWEEP_DEG = 26;
const ARROW_R_INNER = 0.42;
const ARROW_R_OUTER = 0.88;
const ARROW_HEAD_R_INNER = 0.24;
const ARROW_HEAD_R_OUTER = 1.0;
const ARROW_ARC_STEP_DEG = 6;
const ARROW_OPACITY_FRONT = 0.9;
const ARROW_OPACITY_BACK = 0.3;

/** D18 inertia spring: the arrows' displayed rotation chases the target with a slightly-
 * underdamped follow (≈0.8 damping ratio), so a spin-and-release glides and settles like a
 * platter with mass. */
const SPRING_K = 140; // 1/s²
const SPRING_DRAG = 19; // 1/s

/** Rotate gesture: dragging the full plate diameter (2·radiusX) sweeps 360° — i.e.
 * 180/radiusX degrees per pixel. At the default 360px main ring that reproduces the original
 * 0.5 deg/px feel exactly, and a mini ring spins proportionally faster so the same-length
 * gesture reads the same on any disc. */
const ROTATE_SWEEP_DEG_PER_RADIUS = 180;

/** The visible mini-ring plate can be only a few px tall (radiusY is ~10% of radiusX) — far too
 * thin to grab. An invisible hit ellipse with at least this half-height is the actual rotate
 * handle; on the main ring (radiusY ≈ 32px) it coincides with the plate. */
const MIN_HIT_RY = 10;

export interface RingRailGeometry {
  centerX: number;
  centerY: number;
  radiusX: number;
  radiusY: number;
}

export interface RingRailAssemblyOptions {
  /** D13 compass ruler around the rail — on for the main ring; off for mini rings, where its
   * ticks would be sub-pixel noise. When on, pass the full RingConfig to `setGeometry` (the
   * ruler's depth fade needs the scale/opacity ranges). */
  showRuler: boolean;
  /** Inset of the plate inside the rail ellipse, px per axis (see the main ring's gap band). */
  plateGapRx: number;
  plateGapRy: number;
  /** Incremental rotation (degrees) accumulated from the drag gesture — invoked only from
   * `flushRotation()`, so at most once per animation frame. The caller owns the running offset
   * and re-renders. */
  onRotate: (deltaDeg: number) => void;
  /** Fired once when the user grabs the disc to spin — before the first delta. */
  onRotateGestureStart?: () => void;
  /** Fired on any pointer activity on the disc — the renderer uses it to (re)start its rAF
   * loop, which is what drives `flushRotation`/`step`. */
  onInteraction?: () => void;
}

interface Point {
  x: number;
  y: number;
}

export class RingRailAssembly {
  /** Layers exposed for stacking: `backLayer` (plate + arrows) paints behind whatever the
   * caller puts between them (string hangers, on the main ring), `frontLayer` (rail + ruler +
   * rotate hit target) in front of it. */
  readonly backLayer: SVGGElement;
  readonly frontLayer: SVGGElement;

  private options: RingRailAssemblyOptions;
  private svg: SVGSVGElement;
  private plate: SVGEllipseElement;
  private arrowEls: SVGPathElement[] = [];
  private rail: SVGEllipseElement;
  private rulerLayer: SVGGElement | null = null;
  private rulerKey = "";
  private hit: SVGEllipseElement;

  private geo: RingRailGeometry = { centerX: 0, centerY: 0, radiusX: 0, radiusY: 0 };
  private plateRx = 0;
  private plateRy = 0;

  private spring = { angleDeg: 0, velocity: 0, targetDeg: 0 };
  private drag: { pointerId: number; lastX: number } | null = null;
  private pendingDeltaDeg = 0;

  constructor(
    svg: SVGSVGElement,
    backParent: SVGElement,
    frontParent: SVGElement,
    options: RingRailAssemblyOptions,
    /** D26: where the rotate hit-target mounts. The ring renderer passes a layer stacked
     * ABOVE the strings, so anywhere inside the disc the pointer ALWAYS turns the disc —
     * strings crossing the disc's interior can't steal the grab. Geometry is absolute
     * (cx/cy in svg coords), so the hit works from any layer. Defaults to frontLayer. */
    hitParent?: SVGElement
  ) {
    this.svg = svg;
    this.options = options;

    this.backLayer = document.createElementNS(SVG_NS, "g");
    this.backLayer.setAttribute("class", "hsd-ring-rail-back");
    this.plate = document.createElementNS(SVG_NS, "ellipse");
    this.plate.setAttribute("class", "hsd-rail-plate");
    this.backLayer.appendChild(this.plate);
    const arrowLayer = document.createElementNS(SVG_NS, "g");
    arrowLayer.setAttribute("class", "hsd-plate-arrows");
    for (let i = 0; i < ARROW_CENTERS_DEG.length; i++) {
      const path = document.createElementNS(SVG_NS, "path");
      path.setAttribute("class", "hsd-plate-arrow");
      arrowLayer.appendChild(path);
      this.arrowEls.push(path);
    }
    this.backLayer.appendChild(arrowLayer);
    backParent.appendChild(this.backLayer);

    this.frontLayer = document.createElementNS(SVG_NS, "g");
    this.frontLayer.setAttribute("class", "hsd-ring-rail-front");
    this.rail = document.createElementNS(SVG_NS, "ellipse");
    this.rail.setAttribute("class", "hsd-rail hsd-rail-ring");
    this.frontLayer.appendChild(this.rail);
    if (options.showRuler) {
      this.rulerLayer = document.createElementNS(SVG_NS, "g");
      this.rulerLayer.setAttribute("class", "hsd-rail-ticks");
      this.frontLayer.appendChild(this.rulerLayer);
    }
    this.hit = document.createElementNS(SVG_NS, "ellipse");
    this.hit.setAttribute("class", "hsd-plate-hit");
    (hitParent ?? this.frontLayer).appendChild(this.hit);
    frontParent.appendChild(this.frontLayer);

    this.attachRotateInteractions();
  }

  get isDragging(): boolean {
    return this.drag !== null;
  }

  /** Pushes the disc's current place/size. Mini rings call this every frame (their disc rides
   * the parent string's live knob); the main ring only on layout changes. `rulerConfig` is
   * required for the ruler to (re)build — only geometry-relevant changes trigger a rebuild. */
  setGeometry(geo: RingRailGeometry, rulerConfig?: RingConfig) {
    this.geo = geo;
    this.plateRx = Math.max(0, geo.radiusX - this.options.plateGapRx);
    this.plateRy = Math.max(0, geo.radiusY - this.options.plateGapRy);

    for (const el of [this.plate, this.rail, this.hit]) {
      el.setAttribute("cx", String(geo.centerX));
      el.setAttribute("cy", String(geo.centerY));
    }
    this.plate.setAttribute("rx", String(this.plateRx));
    this.plate.setAttribute("ry", String(this.plateRy));
    this.rail.setAttribute("rx", String(geo.radiusX));
    this.rail.setAttribute("ry", String(geo.radiusY));
    this.hit.setAttribute("rx", String(this.plateRx));
    this.hit.setAttribute("ry", String(Math.max(this.plateRy, MIN_HIT_RY)));

    if (this.rulerLayer && rulerConfig) {
      const key = `${geo.centerX},${geo.centerY},${geo.radiusX},${geo.radiusY}`;
      if (key !== this.rulerKey) {
        this.rulerKey = key;
        this.rulerLayer.textContent = "";
        for (const tick of computeRailTicks(rulerConfig)) {
          this.rulerLayer.appendChild(this.buildRailTick(tick));
        }
      }
    }
    this.redrawArrows();
  }

  /** Retargets the arrow spring at the disc's current rotation offset. A jump of more than a
   * full turn is not a drag — it's a programmatic reset (e.g. group-to-front zeroing the
   * offset), so snap rather than whip the platter through N revolutions. */
  setTargetRotation(deg: number) {
    this.spring.targetDeg = deg;
    if (Math.abs(deg - this.spring.angleDeg) > 360) {
      this.spring.angleDeg = deg;
      this.spring.velocity = 0;
    }
  }

  /** Depth fade for mini rings — the whole disc dims with its parent string. */
  setOpacity(opacity: number) {
    this.backLayer.style.opacity = String(opacity);
    this.frontLayer.style.opacity = String(opacity);
  }

  /** Forwards rotation accumulated since the last frame as ONE `onRotate` call — pointermove
   * can fire far faster than the display refreshes, and each onRotate re-runs the caller's full
   * layout, so this coalescing is what keeps a fast spin cheap. Call at the top of each tick.
   * Also advances the local arrow-spring target by the same delta so D18 arrows keep turning
   * even when the caller uses a rotate fast-path that skips a full `setTargetRotation`. */
  flushRotation() {
    if (this.pendingDeltaDeg !== 0) {
      const delta = this.pendingDeltaDeg;
      this.pendingDeltaDeg = 0;
      this.spring.targetDeg += delta;
      this.options.onRotate(delta);
    }
  }

  /** Advances the arrow spring one frame; returns true when it's at rest on the target.
   * While the disc is being dragged, snap the arrows to the live target so the spin affordance
   * turns with the gesture (the spring only needs to settle residual motion after release). */
  step(dt: number): boolean {
    const s = this.spring;
    if (this.drag) {
      if (s.angleDeg !== s.targetDeg || s.velocity !== 0) {
        s.angleDeg = s.targetDeg;
        s.velocity = 0;
        this.redrawArrows();
      }
      return false; // keep the renderer ticking while the grab is live
    }
    const delta = s.targetDeg - s.angleDeg;
    if (Math.abs(delta) < 0.05 && Math.abs(s.velocity) < 0.05) {
      if (s.angleDeg !== s.targetDeg) {
        s.angleDeg = s.targetDeg;
        s.velocity = 0;
        this.redrawArrows();
      }
      return true;
    }
    s.velocity += delta * SPRING_K * dt;
    s.velocity /= 1 + SPRING_DRAG * dt;
    s.angleDeg += s.velocity * dt;
    this.redrawArrows();
    return false;
  }

  dispose() {
    this.backLayer.remove();
    this.frontLayer.remove();
    this.hit.remove(); // may live in a caller-provided hit layer (D26), not just frontLayer
  }

  // --- internals ------------------------------------------------------------------------------

  /** Pointer clientX → the svg's viewBox coordinate space (responsive canvases scale). */
  private localX(clientX: number): number {
    const rect = this.svg.getBoundingClientRect();
    const vbWidth = this.svg.viewBox.baseVal.width || rect.width;
    return rect.width > 0 ? ((clientX - rect.left) * vbWidth) / rect.width : 0;
  }

  private attachRotateInteractions() {
    const el = this.hit;
    el.style.cursor = "grab";
    el.addEventListener("pointerdown", (ev) => {
      this.drag = { pointerId: ev.pointerId, lastX: this.localX(ev.clientX) };
      // Capture after the drag state is already recorded: a capture failure (rare, but possible
      // if the pointer is already captured elsewhere) shouldn't silently cancel the whole drag —
      // pointermove/pointerup still work via bubbling, just without the "keeps tracking outside
      // the element's bounds" guarantee capture normally gives.
      try {
        el.setPointerCapture(ev.pointerId);
      } catch {
        // ignore — see above
      }
      el.style.cursor = "grabbing";
      this.options.onRotateGestureStart?.();
      this.options.onInteraction?.();
    });
    el.addEventListener("pointermove", (ev) => {
      if (!this.drag || this.drag.pointerId !== ev.pointerId) return;
      // Plain X-pixel-delta -> degrees, not an ellipse-angle inversion: the disc is wide and
      // flat, so most of its interior sits near the ellipse's vertical center, where inverting
      // sin/cos from an arbitrary interior point is numerically degenerate. Deltas accumulate
      // here and are flushed by the renderer's animation loop at most once per frame.
      const degPerPx = this.geo.radiusX > 0 ? ROTATE_SWEEP_DEG_PER_RADIUS / this.geo.radiusX : 0;
      const x = this.localX(ev.clientX);
      this.pendingDeltaDeg += (x - this.drag.lastX) * degPerPx;
      this.drag.lastX = x;
      this.options.onInteraction?.();
    });
    const endRotate = (ev: PointerEvent) => {
      if (!this.drag || this.drag.pointerId !== ev.pointerId) return;
      try {
        el.releasePointerCapture(ev.pointerId);
      } catch {
        // ignore — capture may never have been granted (see pointerdown's guard above)
      }
      el.style.cursor = "grab";
      this.drag = null;
      this.options.onInteraction?.(); // let the spring/strings settle out (and any last flush)
    };
    el.addEventListener("pointerup", endRotate);
    el.addEventListener("pointercancel", endRotate);
  }

  /** A point ON the disc's top surface — polar (angle around the disc, fraction of its radius)
   * → px, through the same squashed-ellipse projection as the rail/strings: r=1 is the plate's
   * edge, r=0 its center. */
  private plateSurfacePoint(angleDeg: number, rFrac: number): Point {
    const rad = (angleDeg * Math.PI) / 180;
    return {
      x: this.geo.centerX + rFrac * this.plateRx * Math.sin(rad),
      y: this.geo.centerY + rFrac * this.plateRy * Math.cos(rad),
    };
  }

  /** Rebuilds both D18 arrows at the spring's current angle. Each is a wide annular band capped
   * by a flared triangular head, sampled in disc coordinates and projected per-point — that
   * per-point projection is what makes the arrow visibly bend around the disc and foreshorten
   * in perspective as it rides toward the sides/back. */
  private redrawArrows() {
    if (this.plateRx <= 0 || this.plateRy <= 0) return;
    const rMid = (ARROW_R_INNER + ARROW_R_OUTER) / 2;
    for (let i = 0; i < this.arrowEls.length; i++) {
      const centerDeg = ARROW_CENTERS_DEG[i] + this.spring.angleDeg;
      const totalSweep = ARROW_BAND_SWEEP_DEG + ARROW_HEAD_SWEEP_DEG;
      const tailDeg = centerDeg - totalSweep / 2;
      const headBaseDeg = tailDeg + ARROW_BAND_SWEEP_DEG;
      const tipDeg = headBaseDeg + ARROW_HEAD_SWEEP_DEG;

      const pts: Point[] = [];
      // Outer edge of the band, tail → head-base.
      for (let d = tailDeg; d < headBaseDeg; d += ARROW_ARC_STEP_DEG) {
        pts.push(this.plateSurfacePoint(d, ARROW_R_OUTER));
      }
      pts.push(this.plateSurfacePoint(headBaseDeg, ARROW_R_OUTER));
      // Head: flare out, converge to the tip, flare back in.
      pts.push(this.plateSurfacePoint(headBaseDeg, ARROW_HEAD_R_OUTER));
      pts.push(this.plateSurfacePoint(tipDeg, rMid));
      pts.push(this.plateSurfacePoint(headBaseDeg, ARROW_HEAD_R_INNER));
      // Inner edge of the band, head-base → tail; the close (`Z`) draws the flat tail.
      for (let d = headBaseDeg; d > tailDeg; d -= ARROW_ARC_STEP_DEG) {
        pts.push(this.plateSurfacePoint(d, ARROW_R_INNER));
      }
      pts.push(this.plateSurfacePoint(tailDeg, ARROW_R_INNER));

      const el = this.arrowEls[i];
      el.setAttribute(
        "d",
        `M ${pts.map((p) => `${p.x.toFixed(2)} ${p.y.toFixed(2)}`).join(" L ")} Z`
      );
      // Depth fade from the arrow's angular center — front arrows read bold, far ones recede,
      // matching the strings' depth-opacity convention (cos: +1 = front, −1 = back).
      const depthT = (1 - Math.cos((centerDeg * Math.PI) / 180)) / 2;
      el.style.opacity = String(
        ARROW_OPACITY_FRONT - (ARROW_OPACITY_FRONT - ARROW_OPACITY_BACK) * depthT
      );
    }
  }

  /** D13 amendment (user, 2026-07-15): the ruler's graduations render as KNOTS tied on the
   * rail — a knotted measuring line (the ship's log line that gave "knots" their name), not
   * engraved tick strokes. Each grade is a bump radius; the front landmark stays the biggest. */
  private static readonly KNOT_RADIUS: Record<RailTick["tier"], number> = {
    minor: 1.9,
    medium: 3,
    major: 4.4,
  };
  /** The knot bulge is slightly wider than tall — the same vertical squash convention the
   * whole disc perspective uses (rail ellipse, plate, D18 arrows). */
  private static readonly KNOT_SQUASH = 0.78;

  private buildRailTick(tick: RailTick): SVGEllipseElement {
    const r = RingRailAssembly.KNOT_RADIUS[tick.tier] * tick.scale * (tick.isFront ? 1.15 : 1);
    const knot = document.createElementNS(SVG_NS, "ellipse");
    const classes = ["hsd-rail-knot", `hsd-rail-knot-${tick.tier}`];
    if (tick.isFront) classes.push("hsd-rail-knot-front");
    knot.setAttribute("class", classes.join(" "));
    knot.setAttribute("cx", String(tick.anchorX));
    knot.setAttribute("cy", String(tick.anchorY));
    knot.setAttribute("rx", String(r));
    knot.setAttribute("ry", String(r * RingRailAssembly.KNOT_SQUASH));
    knot.style.opacity = String(tick.opacity);
    return knot;
  }
}
