/**
 * D21: the animated backdrop — a white sheet hanging behind the chart, waving as if blown by
 * a breeze (user request, 2026-07-15: "a waving white sheet… in a loop and just like a real
 * breeze it should be random speed and random intensity"). Fits the hanging metaphor: a cloth
 * backdrop pinned up behind the strings, giving the diagram depth.
 *
 * BREEZE MODEL — organic, endless, never visibly repeating: real breezes don't loop, so
 * instead of a fixed-period animation the wind is a sum of slow sines with INCOMMENSURATE
 * periods (11.3s / 23.7s / 8.9s / 19.3s share no common multiple within hours), one pair
 * modulating SPEED (how fast the wave travels through the cloth) and one pair INTENSITY (how
 * far the cloth billows). The wave phase INTEGRATES the speed signal, so gusts genuinely
 * accelerate the fabric rather than just scaling it. Deterministic and cheap — no RNG state,
 * no physics solver, and testable as pure math.
 *
 * PERFORMANCE (texturing.md budget): no SVG filters anywhere — the sheet is one path + a few
 * gradient-filled fold streaks, rebuilt each frame from ~a dozen trig calls. The rAF loop
 * only runs while enabled and parks itself when `prefers-reduced-motion` is set (a static,
 * gently-draped sheet still renders — depth without motion).
 */

import { nextInstanceUid } from "./uid";

const SVG_NS = "http://www.w3.org/2000/svg";

/** The backdrop's own fixed drawing space; the svg stretches it to the container
 * (`preserveAspectRatio="none"`), so cloth geometry never needs resize plumbing. */
const VIEW_W = 1000;
const VIEW_H = 560;
/** Margins that let the page background show around the sheet — it reads as a hung cloth,
 * not a second page background. */
const SHEET_MARGIN_X = 56;
/** Default top edge. D21.5: like the D21.3 hem, the top is LIVE — main.ts measures the
 * visible rail's line (the rod in planar modes, the ring's top rim) in container pixels and
 * pins the cloth there via setTop(), so the sheet visibly hangs from the same line the
 * strings do instead of floating at its own height. This constant only covers the beat
 * before the first measurement. */
const SHEET_TOP = 22;
/** D21.6: the live top is a PROFILE, not one height — main.ts samples the rendered rail's
 * geometry (straight rod, arc, wave, or the ring's back rim) and the cloth's top edge follows
 * that curve, so the sheet visibly hangs from whatever form the rail takes. */
export const TOP_PROFILE_POINTS = 33;

/** The top edge — one height (a straight rod) or a sampled curve across the sheet's width. */
export type SheetTopProfile = number | readonly number[];

/** Container-px x of sheet-fraction `u` — main.ts uses this to sample the rail at exactly the
 * cloth's own x positions (the backdrop's x view-units are container-width/1000). */
export function sheetXPx(u: number, containerWidthPx: number): number {
  return ((SHEET_MARGIN_X + u * (VIEW_W - 2 * SHEET_MARGIN_X)) / VIEW_W) * containerWidthPx;
}

/** The profile's height at fraction `u` — scalar passthrough, linear interp for curves. */
export function profileAt(top: SheetTopProfile, u: number): number {
  if (typeof top === "number") return top;
  const t = Math.min(1, Math.max(0, u)) * (top.length - 1);
  const i = Math.min(top.length - 2, Math.floor(t));
  return top[i] + (top[i + 1] - top[i]) * (t - i);
}
/** Hem base distance from the view's bottom edge — leaves room for the downward billow.
 * D21.3: the viewBox HEIGHT is live (the container's pixel height, tracked by a
 * ResizeObserver) and the chart shell reserves extra bottom padding, so the hem hangs BELOW
 * the lowest knob however far branches grow the canvas. */
const SHEET_BOTTOM_MARGIN = 46;
const DEFAULT_SHEET_BOTTOM = VIEW_H - SHEET_BOTTOM_MARGIN;
/** Peak bottom-edge billow in view units at intensity 1. */
const WAVE_AMPLITUDE = 26;
/** How many wave samples shape the free (bottom) edge. */
const EDGE_POINTS = 9;
/** Moving pleat waves (D21.1): the cloth's shading is sampled as this many vertical strips —
 * enough for smooth ridges at the wave frequencies below, few enough to stay trivial. */
const PLEAT_STRIPS = 28;
/** Peak pleat opacity at full shading (element opacity scales with the local wave slope). */
const PLEAT_MAX_OPACITY = 0.17;

export interface BreezeSignal {
  /** Wave travel speed multiplier — drifts around 1, gusts up, lulls down. */
  speed: number;
  /** Billow amplitude multiplier, 0.15..~1.2 — calm to fresh breeze. */
  intensity: number;
}

/** The wind at wall-clock second `t` — pure and deterministic (see module note). */
export function breezeSignal(t: number): BreezeSignal {
  const TAU = Math.PI * 2;
  const speed =
    1 + 0.55 * Math.sin((t * TAU) / 11.3) + 0.35 * Math.sin((t * TAU) / 23.7 + 1.7);
  const intensity =
    0.6 + 0.35 * Math.sin((t * TAU) / 8.9 + 0.6) + 0.28 * Math.sin((t * TAU) / 19.3 + 2.1);
  return {
    speed: Math.max(0.15, speed),
    intensity: Math.max(0.15, Math.min(1.25, intensity)),
  };
}

/** Lateral cloth displacement at height-fraction `v` (0 = pinned top, 1 = free bottom) and
 * horizontal fraction `u`, for wave phase `phase` and billow `intensity`. The top is pinned
 * (displacement → 0), the free edge moves most — like a real hung sheet. Two superimposed
 * traveling waves with irrational frequency ratio keep the cloth from ever looking periodic
 * across its width. */
export function clothOffset(u: number, v: number, phase: number, intensity: number): number {
  const pin = v * v; // pinned top: quadratic growth of freedom toward the free edge
  return (
    WAVE_AMPLITUDE *
    intensity *
    pin *
    (0.72 * Math.sin(u * 4.1 + phase) + 0.38 * Math.sin(u * 7.3 * 1.618 - phase * 1.31 + 1.2))
  );
}

/** The sheet outline at a given phase/intensity — pinned straight top, gently waving sides,
 * billowing bottom edge (smooth quadratic runs through the sampled wave). Pure: testable. */
export function sheetPath(
  phase: number,
  intensity: number,
  bottom: number = DEFAULT_SHEET_BOTTOM,
  top: SheetTopProfile = SHEET_TOP,
  left: number = SHEET_MARGIN_X,
  right: number = VIEW_W - SHEET_MARGIN_X
): string {
  const w = right - left;
  // Bottom edge: sample the cloth wave; vertical billow + slight horizontal shimmy.
  const pts: { x: number; y: number }[] = [];
  for (let i = 0; i <= EDGE_POINTS; i++) {
    const u = i / EDGE_POINTS;
    pts.push({
      x: left + u * w + clothOffset(u, 1, phase * 0.7, intensity) * 0.25,
      y: bottom + clothOffset(u, 1, phase, intensity),
    });
  }
  // Side seams: bow with the wave a little at their lower half.
  const leftBow = clothOffset(0, 0.55, phase, intensity) * 0.5;
  const rightBow = clothOffset(1, 0.55, phase * 1.05, intensity) * 0.5;

  // Top edge: pinned to the rail's form (D21.6) — a polyline through the profile (straight
  // rods degenerate to one segment via profileAt's scalar passthrough).
  const TOP_SEGS = typeof top === "number" ? 1 : 16;
  let d = `M ${left} ${profileAt(top, 0)}`;
  for (let i = 1; i <= TOP_SEGS; i++) {
    const u = i / TOP_SEGS;
    d += ` L ${left + u * w} ${profileAt(top, u)}`;
  }
  d += ` Q ${right + rightBow} ${(profileAt(top, 1) + bottom) / 2} ${pts[EDGE_POINTS].x} ${pts[EDGE_POINTS].y}`;
  for (let i = EDGE_POINTS - 1; i >= 1; i--) {
    const p = pts[i];
    const end = i === 1 ? pts[0] : { x: (p.x + pts[i - 1].x) / 2, y: (p.y + pts[i - 1].y) / 2 };
    d += ` Q ${p.x} ${p.y} ${end.x} ${end.y}`;
  }
  d += ` Q ${left + leftBow} ${(profileAt(top, 0) + bottom) / 2} ${left} ${profileAt(top, 0)} Z`;
  return d;
}

/** D21.4 warp mesh (user, 2026-07-15: "distort the texture as the sheet moves"): the
 * patterned cloths render as a COLS×ROWS mesh of cells whose rectangle paths are STATIC —
 * only each cell's affine transform updates per frame, mapping it onto its displaced corners.
 * The pattern fill rides the element transform, so the weave stretches and shears WITH the
 * fabric (a printed cloth, not a window onto wallpaper); per-cell affinity keeps neighboring
 * checks near-continuous, and a same-paint 1px stroke hides the hairline seams of the
 * non-affine residual. */
const MESH_COLS = 28;
const MESH_ROWS = 4;
/** Cells extend this far into their right/bottom neighbors so affine residual gaps never
 * show the page background through the cloth. */
const MESH_OVERLAP = 0.75;

/** A mesh corner's displaced position — the same wave field as the hem/pleats, applied over
 * the whole cloth: vertical billow (pin-scaled by clothOffset's v²) plus the horizontal
 * shimmy, so the hem row reproduces sheetPath's hem exactly and the top row stays pinned. */
export function meshCorner(
  u: number,
  v: number,
  phase: number,
  intensity: number,
  bottom: number = DEFAULT_SHEET_BOTTOM,
  top: SheetTopProfile = SHEET_TOP,
  left: number = SHEET_MARGIN_X,
  right: number = VIEW_W - SHEET_MARGIN_X
): { x: number; y: number } {
  const w = right - left;
  const topY = profileAt(top, u); // D21.6: the pinned edge rides the rail's form
  return {
    x: left + u * w + clothOffset(u, v, phase * 0.7, intensity) * 0.25,
    y: topY + v * (bottom - topY) + clothOffset(u, v, phase, intensity),
  };
}

/**
 * D21.1 (user, 2026-07-15: "use moving pleat waves instead to show how the sheet is blown"):
 * signed pleat shading at horizontal fraction `u` — the HORIZONTAL GRADIENT of the cloth's
 * displacement field. A ridge angled toward the light reads bright (+), the valley behind it
 * dark (−); and because the displacement waves travel (the phase integrates the wind speed),
 * the pleats sweep across the sheet — the shading IS the physics, so pleats move exactly as
 * fast as the gusts push the fabric. Normalized to −1..1 at full intensity; a calm breeze
 * shades faintly, a gust deepens the pleats. Pure: testable.
 */
export function pleatShade(u: number, phase: number, intensity: number): number {
  const eps = 0.01;
  const slope =
    (clothOffset(u + eps, 1, phase, intensity) - clothOffset(u - eps, 1, phase, intensity)) /
    (2 * eps);
  // Peak |d(offset)/du| at intensity 1 (sum of the two wave terms' max slopes).
  const norm = WAVE_AMPLITUDE * (0.72 * 4.1 + 0.38 * 7.3 * 1.618);
  return Math.max(-1, Math.min(1, (slope / norm) * 1.7));
}

/**
 * D21.2 (user, 2026-07-15: "slightly, randomly move the threads by the same random breeze"):
 * the wind acceleration (px/s²) a thread at horizontal fraction `u` feels. SAME spatial
 * frequencies and phase convention as the cloth waves, so the threads sway in the very gust
 * the sheet's pleats show traveling behind them — one wind for the whole scene. Intensity is
 * squared: lulls leave the threads nearly still, gusts visibly stir them ("slightly, randomly").
 */
export function threadWindAccel(u: number, phase: number, intensity: number): number {
  return (
    55 *
    intensity *
    intensity *
    (0.7 * Math.sin(u * 4.1 + phase) + 0.3 * Math.sin(u * 7.3 * 1.618 - phase * 1.31 + 0.8))
  );
}

/** D21.3 sheet textures: the plain white cloth, a red-gingham tablecloth, or the Bavarian
 * blue-white lozenge check (Rauten). Keys are the Backdrop dropdown's option values. */
export type SheetTexture = "plain" | "tablecloth" | "bavarian";

export interface SheetBackdrop {
  setEnabled(enabled: boolean): void;
  setTexture(texture: SheetTexture): void;
  /** D21.5/D21.6: pin the cloth's top edge (container px) to the visible rail — one height
   * for a straight rod, or a sampled curve (TOP_PROFILE_POINTS values across the cloth's
   * horizontal span) that follows an arc/wave rail or the ring's back rim. */
  setTop(top: SheetTopProfile): void;
  /** D21.7 (2026-07-20): pin the cloth's HORIZONTAL span (container px) to the rendered
   * rail's extent — the sheet hangs exactly as wide as the diagram, not as wide as whatever
   * container hosts it. `containerWidthPx` converts px → the cloth's fixed view units. */
  setSpan(leftPx: number, rightPx: number, containerWidthPx: number): void;
  /** Freeze/resume the breeze loop while an interaction needs the frame budget (disc spin). */
  setSuspended(suspended: boolean): void;
  /**
   * D21.8: allow the sheet to stay visible while its rAF is parked (static drape). Unlike
   * `setEnabled(false)` this does NOT hide the SVG — used for mobile shake-gated breeze.
   * Default true (continuous breeze). Ignored when `prefers-reduced-motion` already forces
   * a static sheet.
   */
  setMotionEnabled(on: boolean): void;
  /**
   * D21.8: multiplies the organic `breezeSignal` intensity each frame (shake envelope scale).
   * Clamped to ≥0; default 1.
   */
  setIntensityScale(scale: number): void;
  dispose(): void;
}

/**
 * Mounts the breeze backdrop as the container's first child (behind the chart svgs — see the
 * .hsd-backdrop stacking rules in style.css) and drives it with its own rAF loop. The loop
 * runs only while enabled; with `prefers-reduced-motion` the sheet renders once, gently
 * draped, and never animates.
 */
export function createSheetBackdrop(container: HTMLElement): SheetBackdrop {
  // Q23: def ids are per-instance — two backdrops' gradients are visually identical today, but
  // duplicate ids would make every instance resolve against whichever defs happen to come
  // first in the document, breaking the rest the moment that instance is destroyed.
  const uid = nextInstanceUid("hsd-backdrop");
  const svg = document.createElementNS(SVG_NS, "svg");
  svg.setAttribute("class", "hsd-backdrop");
  svg.setAttribute("viewBox", `0 0 ${VIEW_W} ${VIEW_H}`);
  svg.setAttribute("preserveAspectRatio", "none");
  svg.setAttribute("aria-hidden", "true");

  const defs = document.createElementNS(SVG_NS, "defs");
  // Cloth fills (D21.3): plain near-white, red-gingham tablecloth, Bavarian blue lozenges —
  // all soft-alpha so the sheet stays a backdrop over any theme background. A separate shade
  // overlay (below) darkens toward the hem for fabric depth regardless of the weave.
  defs.innerHTML =
    `<linearGradient id="${uid}-sheet-fill" x1="0" y1="0" x2="0" y2="1">` +
    `<stop offset="0" stop-color="#ffffff" stop-opacity="0.92"/>` +
    `<stop offset="0.72" stop-color="#fbfaf7" stop-opacity="0.88"/>` +
    `<stop offset="1" stop-color="#eceae4" stop-opacity="0.85"/>` +
    `</linearGradient>` +
    // Tablecloth: classic red-white gingham — translucent red bands crossing on white; the
    // band overlap reads darker automatically (two 0.30-alpha reds stack to ≈0.51).
    `<pattern id="${uid}-sheet-tablecloth" patternUnits="userSpaceOnUse" width="36" height="36">` +
    `<rect width="36" height="36" fill="#ffffff" fill-opacity="0.9"/>` +
    `<rect x="18" width="18" height="36" fill="#c1443c" fill-opacity="0.30"/>` +
    `<rect y="18" width="36" height="18" fill="#c1443c" fill-opacity="0.30"/>` +
    `</pattern>` +
    // Bavarian check: the white-blue Rauten — a two-square checker rotated 45° into lozenges.
    `<pattern id="${uid}-sheet-bavarian" patternUnits="userSpaceOnUse" width="44" height="44"` +
    ` patternTransform="rotate(45)">` +
    `<rect width="44" height="44" fill="#ffffff" fill-opacity="0.9"/>` +
    `<rect width="22" height="22" fill="#5b9fd3" fill-opacity="0.55"/>` +
    `<rect x="22" y="22" width="22" height="22" fill="#5b9fd3" fill-opacity="0.55"/>` +
    `</pattern>` +
    // Fabric depth for the patterned cloths: a faint darkening toward the hem, laid over
    // whatever weave fills the sheet (the plain fill carries its own falloff already).
    `<linearGradient id="${uid}-sheet-shade" x1="0" y1="0" x2="0" y2="1">` +
    `<stop offset="0" stop-color="#8a8578" stop-opacity="0"/>` +
    `<stop offset="1" stop-color="#8a8578" stop-opacity="0.16"/>` +
    `</linearGradient>` +
    // Pleat shading fades in toward the free edge — the top is pinned flat, so its pleats
    // must vanish there exactly like the displacement does.
    `<linearGradient id="${uid}-pleat-light" x1="0" y1="0" x2="0" y2="1">` +
    `<stop offset="0" stop-color="#ffffff" stop-opacity="0"/>` +
    `<stop offset="0.45" stop-color="#ffffff" stop-opacity="0.4"/>` +
    `<stop offset="1" stop-color="#ffffff" stop-opacity="1"/>` +
    `</linearGradient>` +
    `<linearGradient id="${uid}-pleat-shadow" x1="0" y1="0" x2="0" y2="1">` +
    `<stop offset="0" stop-color="#8a8578" stop-opacity="0"/>` +
    `<stop offset="0.45" stop-color="#8a8578" stop-opacity="0.4"/>` +
    `<stop offset="1" stop-color="#8a8578" stop-opacity="1"/>` +
    `</linearGradient>`;
  svg.appendChild(defs);

  const sheet = document.createElementNS(SVG_NS, "path");
  sheet.setAttribute("class", "hsd-backdrop-sheet");
  sheet.setAttribute("fill", `url(#${uid}-sheet-fill)`);
  svg.appendChild(sheet);

  // D21.4: the warp mesh for patterned cloths — static rect paths, per-frame affine
  // transforms (built lazily for the current viewBox height in rebuildMesh below).
  const meshLayer = document.createElementNS(SVG_NS, "g");
  meshLayer.style.display = "none";
  svg.appendChild(meshLayer);
  const meshCells: SVGPathElement[] = [];

  // Weave-independent fabric depth (only shown for patterned cloths — see setTexture).
  const sheetShade = document.createElementNS(SVG_NS, "path");
  sheetShade.setAttribute("fill", `url(#${uid}-sheet-shade)`);
  sheetShade.style.display = "none";
  svg.appendChild(sheetShade);

  const pleats = Array.from({ length: PLEAT_STRIPS }, () => {
    const strip = document.createElementNS(SVG_NS, "path");
    strip.setAttribute("fill", `url(#${uid}-pleat-light)`);
    svg.appendChild(strip);
    return strip;
  });

  container.prepend(svg);

  // D21.3: track the container's real pixel height so the hem position is absolute — the
  // chart shell reserves bottom padding (style.css) and the sheet's hem lives inside it,
  // BELOW the lowest knob no matter how far expanded branches grow the canvas. Width stays
  // the fixed 1000-unit cloth space (stretched), so the wave math never needs resizing.
  let viewH = VIEW_H;
  if (typeof ResizeObserver === "function") {
    const ro = new ResizeObserver(() => {
      // The svg spans `inset: 0` — the PADDING box — so measure that, not contentRect (the
      // content box, which excludes the shell's D21.3 bottom padding and left the viewBox
      // slightly stretched: backdrop y-units must equal container pixels exactly for the
      // D21.5 rail-line match). clientHeight, not getBoundingClientRect: it is the same
      // padding box but UNTRANSFORMED — under the D27 zoom the bounding rect inflates with
      // the scale while the cloth's coordinate space stays local.
      const h = Math.max(200, Math.round(container.clientHeight || container.getBoundingClientRect().height));
      if (h !== viewH) {
        viewH = h;
        svg.setAttribute("viewBox", `0 0 ${VIEW_W} ${viewH}`);
        if (!enabled) draw(0.5); // keep the static (reduced-motion / pre-enable) drape fresh
      }
    });
    ro.observe(container);
  }

  const reducedMotion =
    typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;

  let enabled = false;
  let rafId: number | null = null;
  let phase = 0;
  let lastT: number | null = null;
  let suspended = false;
  /** D21.8: when false, sheet stays visible but rAF is parked (static drape). */
  let motionEnabled = true;
  /** D21.8: multiplies organic breeze intensity (shake envelope). */
  let intensityScale = 1;
  let textureKind: SheetTexture = "plain";
  let sheetTop: SheetTopProfile = SHEET_TOP; // D21.5/6: live — pinned to the rail via setTop()
  // D21.7: live horizontal span (view units) — pinned to the rail's extent via setSpan().
  let spanLeft = SHEET_MARGIN_X;
  let spanRight = VIEW_W - SHEET_MARGIN_X;
  let topRevision = 0;
  let meshBottom = -1; // the bottom the current cell rects were built for
  let meshTopRev = -1;

  function loopMayRun(): boolean {
    // D21.8: do NOT gate on prefers-reduced-motion here — that preference only sets the
    // default parked state. An explicit setMotionEnabled(true) from the breeze toggle must
    // be able to start the loop (iOS users often have Reduce Motion on).
    return enabled && motionEnabled && !suspended;
  }

  /** (Re)builds the mesh's STATIC source rectangles for the current sheet height. Only runs
   * on resize/texture change — per frame, cells change nothing but their transform. */
  function rebuildMesh(bottom: number, fill: string) {
    const left = spanLeft;
    const w = spanRight - spanLeft;
    const cellW = w / MESH_COLS;
    // Source grid stays RECTANGULAR from the profile's highest point — the per-cell affine
    // maps it onto the curved (and waving) corner grid, so the weave drapes along the rail
    // form exactly as it warps with the wind (D21.4's mechanism, reused).
    const refTop = typeof sheetTop === "number" ? sheetTop : Math.min(...sheetTop);
    const cellH = (bottom - refTop) / MESH_ROWS;
    if (meshCells.length === 0) {
      for (let i = 0; i < MESH_COLS * MESH_ROWS; i++) {
        const cell = document.createElementNS(SVG_NS, "path");
        cell.setAttribute("stroke-width", "1");
        meshLayer.appendChild(cell);
        meshCells.push(cell);
      }
    }
    for (let r = 0; r < MESH_ROWS; r++) {
      for (let c = 0; c < MESH_COLS; c++) {
        const x0 = left + c * cellW;
        const y0 = refTop + r * cellH;
        const x1 = x0 + cellW + MESH_OVERLAP;
        const y1 = y0 + cellH + MESH_OVERLAP;
        const cell = meshCells[r * MESH_COLS + c];
        cell.setAttribute("d", `M ${x0} ${y0} L ${x1} ${y0} L ${x1} ${y1} L ${x0} ${y1} Z`);
        cell.setAttribute("fill", fill);
        cell.setAttribute("stroke", fill);
      }
    }
    meshBottom = bottom;
    meshTopRev = topRevision;
  }

  function draw(intensity: number) {
    const bottom = viewH - SHEET_BOTTOM_MARGIN;
    if (textureKind === "plain") {
      sheet.setAttribute("d", sheetPath(phase, intensity, bottom, sheetTop, spanLeft, spanRight));
    } else {
      // D21.4: warp the mesh — corner grid once, then one affine per cell mapping its static
      // rect onto the displaced corners. The pattern fill rides each transform, so the weave
      // visibly stretches/shears with every gust.
      if (meshBottom !== bottom || meshTopRev !== topRevision)
        rebuildMesh(bottom, sheet.getAttribute("fill") ?? "");
      const left = spanLeft;
      const w = spanRight - spanLeft;
      const cellW = w / MESH_COLS;
      const refTop = typeof sheetTop === "number" ? sheetTop : Math.min(...sheetTop);
      const cellH = (bottom - refTop) / MESH_ROWS;
      const grid: { x: number; y: number }[][] = [];
      for (let r = 0; r <= MESH_ROWS; r++) {
        grid.push(
          Array.from({ length: MESH_COLS + 1 }, (_, c) =>
            meshCorner(c / MESH_COLS, r / MESH_ROWS, phase, intensity, bottom, sheetTop, spanLeft, spanRight)
          )
        );
      }
      for (let r = 0; r < MESH_ROWS; r++) {
        for (let c = 0; c < MESH_COLS; c++) {
          const p00 = grid[r][c];
          const p10 = grid[r][c + 1];
          const p01 = grid[r + 1][c];
          const a = (p10.x - p00.x) / cellW;
          const b = (p10.y - p00.y) / cellW;
          const cm = (p01.x - p00.x) / cellH;
          const dm = (p01.y - p00.y) / cellH;
          const x0 = left + c * cellW;
          const y0 = refTop + r * cellH;
          meshCells[r * MESH_COLS + c].setAttribute(
            "transform",
            `matrix(${a} ${b} ${cm} ${dm} ${p00.x - a * x0 - cm * y0} ${p00.y - b * x0 - dm * y0})`
          );
        }
      }
      // The depth shade traces the warped mesh boundary so it hugs the cloth exactly.
      const top = grid[0];
      const bot = grid[MESH_ROWS];
      let outline = `M ${top[0].x} ${top[0].y}`;
      for (let c = 1; c <= MESH_COLS; c++) outline += ` L ${top[c].x} ${top[c].y}`;
      for (let r = 1; r <= MESH_ROWS; r++) outline += ` L ${grid[r][MESH_COLS].x} ${grid[r][MESH_COLS].y}`;
      for (let c = MESH_COLS - 1; c >= 0; c--) outline += ` L ${bot[c].x} ${bot[c].y}`;
      for (let r = MESH_ROWS - 1; r >= 1; r--) outline += ` L ${grid[r][0].x} ${grid[r][0].y}`;
      outline += " Z";
      sheetShade.setAttribute("d", outline);
    }
    // Moving pleats: each strip is a quad from the pinned top to the live hem; its shading
    // sign picks light vs shadow, its magnitude the opacity — and the whole field travels
    // with the wave phase, so the pleats visibly sweep across the cloth with each gust.
    const left = spanLeft;
    const w = spanRight - spanLeft;
    const hemX = (u: number) => left + u * w + clothOffset(u, 1, phase * 0.7, intensity) * 0.25;
    const hemY = (u: number) => bottom + clothOffset(u, 1, phase, intensity);
    for (let i = 0; i < pleats.length; i++) {
      const u0 = i / PLEAT_STRIPS;
      const u1 = (i + 1) / PLEAT_STRIPS;
      const shade = pleatShade((u0 + u1) / 2, phase, intensity);
      const strip = pleats[i];
      strip.setAttribute("fill", shade >= 0 ? `url(#${uid}-pleat-light)` : `url(#${uid}-pleat-shadow)`);
      strip.style.opacity = String(Math.abs(shade) * PLEAT_MAX_OPACITY);
      strip.setAttribute(
        "d",
        `M ${left + u0 * w} ${profileAt(sheetTop, u0)} L ${left + u1 * w} ${profileAt(sheetTop, u1)}` +
          ` L ${hemX(u1)} ${hemY(u1)} L ${hemX(u0)} ${hemY(u0)} Z`
      );
    }
  }

  const tick = (ts: number) => {
    const t = ts / 1000;
    const dt = Math.min(t - (lastT ?? t), 1 / 20);
    lastT = t;
    const wind = breezeSignal(t);
    phase += wind.speed * dt * 1.1; // integrate: gusts genuinely speed the wave up
    const intensity = Math.max(0, wind.intensity * intensityScale);
    draw(intensity);
    rafId = loopMayRun() ? requestAnimationFrame(tick) : null;
  };

  function ensureLoop() {
    if (loopMayRun() && rafId === null) {
      lastT = null;
      rafId = requestAnimationFrame(tick);
    } else if (!loopMayRun() && rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  }

  return {
    setTexture(texture: SheetTexture) {
      textureKind = texture;
      const fill =
        texture === "tablecloth"
          ? `url(#${uid}-sheet-tablecloth)`
          : texture === "bavarian"
            ? `url(#${uid}-sheet-bavarian)`
            : `url(#${uid}-sheet-fill)`;
      sheet.setAttribute("fill", fill);
      // D21.4: plain cloth stays the single smooth path; patterned cloths render as the warp
      // mesh (the pattern must ride the fabric), plus the weave-independent depth overlay.
      const patterned = texture !== "plain";
      sheet.style.display = patterned ? "none" : "";
      meshLayer.style.display = patterned ? "" : "none";
      sheetShade.style.display = patterned ? "" : "none";
      if (patterned) rebuildMesh(viewH - SHEET_BOTTOM_MARGIN, fill);
      if (!enabled || reducedMotion || !motionEnabled) draw(0.5); // restyle the static drape immediately
    },
    setEnabled(on: boolean) {
      svg.style.display = on ? "" : "none";
      enabled = on;
      if (on && (reducedMotion || !motionEnabled)) {
        draw(0.5); // a static, gently-draped sheet — depth without motion
      }
      ensureLoop();
    },
    setMotionEnabled(on: boolean) {
      if (motionEnabled === on) return;
      motionEnabled = on;
      if (!on) {
        if (rafId !== null) {
          cancelAnimationFrame(rafId);
          rafId = null;
        }
        if (enabled) draw(0.5);
      } else {
        ensureLoop();
      }
    },
    setIntensityScale(scale: number) {
      intensityScale = Number.isFinite(scale) ? Math.max(0, scale) : 0;
    },
    setTop(top: SheetTopProfile) {
      const next: SheetTopProfile =
        typeof top === "number" ? Math.max(0, top) : top.map((y) => Math.max(0, y));
      const same =
        typeof next === "number"
          ? next === sheetTop
          : typeof sheetTop !== "number" &&
            next.length === sheetTop.length &&
            next.every((y, i) => y === (sheetTop as readonly number[])[i]);
      if (same) return;
      sheetTop = next;
      topRevision++; // static mesh rects depend on the top — rebuild on next draw
      // The running loop redraws next frame; a static/frozen drape must restyle now.
      if (rafId === null) draw(0.5);
    },
    setSpan(leftPx: number, rightPx: number, containerWidthPx: number) {
      if (!(containerWidthPx > 0) || !(rightPx > leftPx)) return;
      const toView = (px: number) => (px / containerWidthPx) * VIEW_W;
      const nextLeft = Math.max(0, toView(leftPx));
      const nextRight = Math.min(VIEW_W, toView(rightPx));
      if (Math.abs(nextLeft - spanLeft) < 0.5 && Math.abs(nextRight - spanRight) < 0.5) return;
      spanLeft = nextLeft;
      spanRight = nextRight;
      topRevision++; // static mesh rects depend on the span too — rebuild on next draw
      if (rafId === null) draw(0.5);
    },
    /** Performance gate (user, 2026-07-16): parks the breeze loop while an interaction needs
     * the whole frame budget (the ring disc spin re-runs layout every frame), holding the last
     * drawn drape on screen. Resuming leaves `phase` where it stopped and restarts the clock
     * (`lastT = null`), so the cloth eases back in with no time-jump lurch. */
    setSuspended(on: boolean) {
      if (suspended === on) return;
      suspended = on;
      if (on && rafId !== null) {
        cancelAnimationFrame(rafId);
        rafId = null;
      } else if (!on) {
        ensureLoop();
      }
    },
    dispose() {
      if (rafId !== null) cancelAnimationFrame(rafId);
      svg.remove();
    },
  };
}
