/**
 * Pure layout math for Hanging Strings Diagram, straight-rail mode (v1 focus).
 * No DOM, no rendering-library types — any renderer (SVG/Canvas/React/D3) consumes
 * this same StringLayout[] output. See wiki/design/visual-design.md decisions D1, D5, D6, D7.
 */

import type { HangingStringCategory, HangingStringsDiagramConfig } from "./types";
import { StraightRailForm, type PlanarRailForm } from "./railForm";
import { linearScale, sqrtScale, tickStep, ticksBelow } from "./scale";

export interface StringLayout {
  category: HangingStringCategory;
  /** x position of the string's anchor on the rail, in px. */
  x: number;
  /** y of the rail this string hangs from (top anchor). One shared value for every root string
   * in straight mode (D1); a child string's railY is its parent's sub-rail (D16). */
  railY: number;
  /** y of the knob (string's lower tip). railY + dropPx. Exact value read channel — D1. */
  knobY: number;
  /** Pixel length of the string. Proportional to category.value — never cosmetic (D1). */
  dropPx: number;
  /** Knob radius in px — uniform, or scaled by secondaryValue when config.knobEncodesSecondMetric (D7). */
  knobRadius: number;
  /** Bead-tick positions along the string, in px from the rail (D6). */
  ticks: { value: number; y: number }[];
  /** v2 (D16): set when this string is a child hanging from a parent's sub-rail — the parent
   * category's id. Roots leave it undefined. Reorder scoping uses it (siblings only). */
  parentId?: string;
}

/** v2 (D16): a small rail hanging at an expanded parent's knob, carrying its child strings. */
export interface SubRailLayout {
  parentId: string;
  x1: number;
  x2: number;
  y: number;
}

export interface LayoutResult {
  strings: StringLayout[];
  /** M1 (wiki/design/rail-forms.md): the planar form the roots hang from — renderers draw the
   * rod's shape from it (railPath) instead of assuming a full-width straight line. */
  railForm: PlanarRailForm;
  /** The straight form's shared rail height. Kept for straight mode's shared-baseline reads
   * (D1 comparability); per-string anchor heights live on StringLayout.railY, which is what
   * non-straight planar forms (M2+) will vary. */
  railY: number;
  contentWidth: number;
  maxValue: number;
  tickStepValue: number;
  /** v2 (D16): sub-rails for expanded branches. Absent/empty in flat v1 layouts. */
  subRails?: SubRailLayout[];
  /** v2 (D16): lowest content edge (max knobY + knob radius) so a renderer can grow its canvas
   * downward when an expanded branch needs the room. Absent in flat v1 layouts. */
  contentHeight?: number;
}

/**
 * Knob radius scale shared by every rail mode (D7): size = optional secondary metric,
 * magnitude-only (sqrt-scaled) since a size channel can't show sign. Domain is derived once from
 * whatever secondary values are present in the dataset — call this once per layout pass, not per
 * category, and reuse the returned function. Categories without a secondary value (or when
 * `knobEncodesSecondMetric` is off) get the uniform `knobMinRadiusPx` marker size.
 */
export function knobRadiusScaleForCategories(
  categories: HangingStringCategory[],
  config: Pick<
    HangingStringsDiagramConfig,
    "knobEncodesSecondMetric" | "knobMinRadiusPx" | "knobMaxRadiusPx"
  >
): (category: HangingStringCategory) => number {
  const secondaryMagnitudes = categories
    .map((c) => c.secondaryValue)
    .filter((v): v is number => typeof v === "number")
    .map((v) => Math.abs(v));
  const domain: [number, number] = [
    0,
    secondaryMagnitudes.length > 0 ? Math.max(...secondaryMagnitudes) : 1,
  ];
  const scale = sqrtScale(domain, [config.knobMinRadiusPx, config.knobMaxRadiusPx]);
  return (category: HangingStringCategory) =>
    config.knobEncodesSecondMetric && typeof category.secondaryValue === "number"
      ? scale(Math.abs(category.secondaryValue))
      : config.knobMinRadiusPx;
}

/**
 * Computes x positions with dynamic spacing (D5): tighter within a group, with an
 * extra gap inserted whenever the group changes. `order` controls left-to-right sequence
 * and is the single source of truth for both "slide to compare" and "group to front" —
 * callers just reorder `order` and re-run layout.
 */
function computeXPositions(
  categories: HangingStringCategory[],
  order: string[],
  config: HangingStringsDiagramConfig
): Map<string, number> {
  const byId = new Map(categories.map((c) => [c.id, c]));
  const xById = new Map<string, number>();
  let x = config.itemGapPx / 2;
  let prevGroupId: string | null = null;
  for (const id of order) {
    const category = byId.get(id);
    if (!category) continue;
    if (prevGroupId !== null) {
      // D5: base item gap always applies; group boundaries add extra separation on top,
      // so between-group spacing is never *smaller* than within-group spacing.
      x += config.itemGapPx + (category.groupId !== prevGroupId ? config.groupGapPx : 0);
    }
    xById.set(id, x);
    prevGroupId = category.groupId;
  }
  return xById;
}

export function computeLayout(
  categories: HangingStringCategory[],
  order: string[],
  config: HangingStringsDiagramConfig,
  /** M1: the planar rail geometry the roots hang from. Defaults to the straight rod at
   * config.railY, so every pre-M1 caller (and test) is unchanged; M2+ forms plug in here. */
  form: PlanarRailForm = new StraightRailForm(config.railY),
  /** D20: per-string along-the-rail position overrides — the planar mirror of ring mode's
   * `angles` map. A string with an entry sits exactly there (arc length from the rod's left
   * end); strings without one keep their D5 even-spread slot. Positions are free, not ordinal:
   * overriding one string never repositions any other. */
  positions?: ReadonlyMap<string, number>
): LayoutResult {
  const maxValue = Math.max(1e-9, ...categories.map((c) => c.value));
  const dropScale = linearScale([0, maxValue], [0, config.maxDropPx]);

  // Knob size encodes *magnitude* of the secondary metric (D7) — see knobRadiusScaleForCategories.
  const knobRadiusForCategory = knobRadiusScaleForCategories(categories, config);

  const step = tickStep(maxValue, config.tickTarget);
  const tickValues = ticksBelow(maxValue, step);

  const xById = computeXPositions(categories, order, config);
  const byId = new Map(categories.map((c) => [c.id, c]));

  const strings: StringLayout[] = order
    .map((id) => byId.get(id))
    .filter((c): c is HangingStringCategory => Boolean(c))
    .map((category) => {
      const dropPx = dropScale(category.value);
      const knobRadius = knobRadiusForCategory(category);
      const ticks = tickValues
        .filter((v) => v < category.value)
        .map((v) => ({ value: v, y: dropScale(v) }));
      // M1: the anchor POINT comes from the form (straight: y constant at railY). The string
      // itself still hangs plumb below it — dropPx stays pure value math whatever the rail's
      // shape (D1), which is the whole family's contract. D20: a slid string's stored position
      // replaces its slot; the slot spread itself is untouched, so nobody else moves.
      const along = positions?.get(category.id) ?? xById.get(category.id) ?? 0;
      const anchor = form.anchorAt(along);
      return {
        category,
        x: anchor.x,
        railY: anchor.y,
        knobY: anchor.y + dropPx,
        dropPx,
        knobRadius,
        ticks,
      };
    });

  // Deliberately derived from the D5 SLOT spread, not from slid positions (D20): the rail's
  // extent — and with it the renderer's centering and any arc form's chord — must not reshape
  // because one string was slid, or the "nobody else moves" contract would break.
  const slotXs = [...xById.values()];
  const contentWidth = slotXs.length > 0 ? Math.max(...slotXs) + config.itemGapPx / 2 : 0;

  return { strings, railForm: form, railY: config.railY, contentWidth, maxValue, tickStepValue: step };
}

/**
 * "Group to front" (D4/requirements): stable-partitions `order` so every category in
 * `groupId` moves to the front, preserving relative order within and outside the group.
 */
export function bringGroupToFront(
  categories: HangingStringCategory[],
  order: string[],
  groupId: string
): string[] {
  const byId = new Map(categories.map((c) => [c.id, c]));
  const front: string[] = [];
  const rest: string[] = [];
  for (const id of order) {
    const category = byId.get(id);
    if (category?.groupId === groupId) front.push(id);
    else rest.push(id);
  }
  return [...front, ...rest];
}

// moveCategory (slot reorder / "slide to compare") retired 2026-07-14 by D20: positional slide
// everywhere. Group-to-front (D4, above) and Reset are the remaining re-arranging operations.
