/**
 * Small dependency-free scale helpers (no d3). Kept pure so the core has zero
 * runtime dependencies and can be reused verbatim by every renderer.
 */

/** Rounds a raw step up to a "nice" 1/2/5 * 10^n value (same family as d3.tickStep). */
export function niceStep(rawStep: number): number {
  if (rawStep <= 0 || !Number.isFinite(rawStep)) return 1;
  const magnitude = Math.pow(10, Math.floor(Math.log10(rawStep)));
  const residual = rawStep / magnitude;
  let niceResidual: number;
  if (residual >= 5) niceResidual = 10;
  else if (residual >= 2) niceResidual = 5;
  else if (residual >= 1) niceResidual = 2;
  else niceResidual = 1;
  return niceResidual * magnitude;
}

/** Picks a "nice" tick step for [0, maxValue] targeting roughly `targetCount` ticks. */
export function tickStep(maxValue: number, targetCount: number): number {
  if (maxValue <= 0) return 1;
  return niceStep(maxValue / Math.max(1, targetCount));
}

/** Generates tick values in (0, maxValue) at the given step — excludes 0 and the endpoint. */
export function ticksBelow(maxValue: number, step: number): number[] {
  const ticks: number[] = [];
  for (let v = step; v < maxValue - step * 0.001; v += step) {
    ticks.push(Math.round(v * 1e6) / 1e6);
  }
  return ticks;
}

export function linearScale(
  domain: [number, number],
  range: [number, number]
): (v: number) => number {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const span = d1 - d0;
  if (span === 0) return () => r0;
  return (v: number) => r0 + ((v - d0) / span) * (r1 - r0);
}

/**
 * Square-root scale — perceptually correct for encoding value via a circle's radius/area.
 * Domain is clamped to >= 0: sqrt is undefined for negatives, so callers encoding a signed
 * metric via size must pre-map to magnitude (abs value) before calling this — sign belongs
 * on a different channel. Clamping here just prevents NaN if that contract is violated.
 */
export function sqrtScale(
  domain: [number, number],
  range: [number, number]
): (v: number) => number {
  const d0 = Math.max(0, domain[0]);
  const d1 = Math.max(0, domain[1]);
  const [r0, r1] = range;
  const span = Math.sqrt(d1) - Math.sqrt(d0);
  if (span === 0) return () => r0;
  return (v: number) =>
    r0 + ((Math.sqrt(Math.max(v, d0, 0)) - Math.sqrt(d0)) / span) * (r1 - r0);
}

/** Interpolates a simple blue -> yellow -> red sequential heat-map color for t in [0,1]. */
export function heatmapColor(t: number): string {
  const clamped = Math.max(0, Math.min(1, t));
  const stops: [number, [number, number, number]][] = [
    [0, [59, 130, 246]], // blue
    [0.5, [250, 204, 21]], // yellow
    [1, [239, 68, 68]], // red
  ];
  let lo = stops[0];
  let hi = stops[stops.length - 1];
  for (let i = 0; i < stops.length - 1; i++) {
    if (clamped >= stops[i][0] && clamped <= stops[i + 1][0]) {
      lo = stops[i];
      hi = stops[i + 1];
      break;
    }
  }
  const span = hi[0] - lo[0] || 1;
  const localT = (clamped - lo[0]) / span;
  const rgb = lo[1].map((c, i) => Math.round(c + (hi[1][i] - c) * localT));
  return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
}
