/**
 * Label contrast sync — keep chart text readable against the *painted* chart ground.
 *
 * Themes author label inks for their own `background.color`. Hosts (and the Night gallery
 * skin) can override the visible `background-color` afterward; this module re-reads the
 * computed ground and flips label CSS vars when ink polarity disagrees with the ground.
 */

export type LabelInkSet = {
  ink: string;
  halo: string;
  valueInk: string;
  captionInk: string;
};

/** Studio-class dark-on-light (matches STUDIO_THEME.label). */
export const LABEL_INKS_LIGHT_GROUND: LabelInkSet = {
  ink: "#333",
  halo: "rgba(255, 255, 255, 0.85)",
  valueInk: "#6d6558",
  captionInk: "#8a8378",
};

/** Foundry-class light-on-dark (matches FOUNDRY_THEME.label family). */
export const LABEL_INKS_DARK_GROUND: LabelInkSet = {
  ink: "#d7dbe4",
  halo: "rgba(23, 26, 34, 0.85)",
  valueInk: "#99a1af",
  captionInk: "#8a92a0",
};

/** Relative luminance threshold: at/below → dark ground (Night #12100e, Foundry #171a22). */
export const DARK_GROUND_LUMINANCE = 0.18;

type Rgb = { r: number; g: number; b: number };

/** sRGB channel → linear (WCAG). */
function linearize(c: number): number {
  const s = c / 255;
  return s <= 0.04045 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
}

export function relativeLuminance(r: number, g: number, b: number): number {
  return 0.2126 * linearize(r) + 0.7152 * linearize(g) + 0.0722 * linearize(b);
}

/** Parse `#rgb` / `#rrggbb` / `rgb()` / `rgba()` — returns null for `transparent` / unknown. */
export function parseCssColor(css: string): Rgb | null {
  const s = css.trim().toLowerCase();
  if (!s || s === "transparent") return null;

  const hex = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(s);
  if (hex) {
    const h = hex[1]!;
    if (h.length === 3) {
      return {
        r: parseInt(h[0]! + h[0]!, 16),
        g: parseInt(h[1]! + h[1]!, 16),
        b: parseInt(h[2]! + h[2]!, 16),
      };
    }
    return {
      r: parseInt(h.slice(0, 2), 16),
      g: parseInt(h.slice(2, 4), 16),
      b: parseInt(h.slice(4, 6), 16),
    };
  }

  const rgb = /^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)(?:\s*,\s*[\d.]+)?\s*\)$/.exec(s);
  if (rgb) {
    return {
      r: Math.round(Number(rgb[1])),
      g: Math.round(Number(rgb[2])),
      b: Math.round(Number(rgb[3])),
    };
  }
  return null;
}

export function isDarkCssColor(
  css: string,
  threshold: number = DARK_GROUND_LUMINANCE
): boolean {
  const rgb = parseCssColor(css);
  if (!rgb) return false;
  return relativeLuminance(rgb.r, rgb.g, rgb.b) < threshold;
}

/**
 * If painted ground and current label ink disagree in polarity, return the preset to apply;
 * otherwise null (keep authored inks — e.g. Foundry on its own dark ground).
 */
export function resolveLabelInks(
  paintedBackground: string,
  currentInk: string
): LabelInkSet | null {
  const groundDark = isDarkCssColor(paintedBackground);
  const inkDark = isDarkCssColor(currentInk, 0.45); // mid greys count as “dark ink”
  if (groundDark && inkDark) return LABEL_INKS_DARK_GROUND;
  if (!groundDark && !inkDark) return LABEL_INKS_LIGHT_GROUND;
  return null;
}

function readLabelInk(el: Element): string {
  if (typeof getComputedStyle === "function") {
    const fromComputed = getComputedStyle(el).getPropertyValue("--hsd-label-ink").trim();
    if (fromComputed) return fromComputed;
  }
  if ("style" in el && el.style) {
    return (el as HTMLElement).style.getPropertyValue("--hsd-label-ink").trim();
  }
  return "";
}

function readBackground(el: Element): string {
  if (typeof getComputedStyle === "function") {
    return getComputedStyle(el).backgroundColor;
  }
  if ("style" in el && el.style) {
    return (el as HTMLElement).style.backgroundColor || "";
  }
  return "";
}

export type SyncLabelContrastOptions = {
  /** Override computed background (tests / hosts that already know the painted ground). */
  backgroundColor?: string;
  /** Override current `--hsd-label-ink`. */
  labelInk?: string;
};

/**
 * Stamp light/dark label CSS vars when the painted ground disagrees with current ink polarity.
 * @returns true when vars were changed.
 */
export function syncLabelContrast(
  el: Element & { style: CSSStyleDeclaration },
  opts?: SyncLabelContrastOptions
): boolean {
  const bg = opts?.backgroundColor ?? readBackground(el);
  const ink = opts?.labelInk ?? readLabelInk(el);
  if (!bg || !ink) return false;

  const next = resolveLabelInks(bg, ink);
  const groundDark = isDarkCssColor(bg);
  if (groundDark) el.setAttribute("data-hsd-dark-ground", "");
  else el.removeAttribute("data-hsd-dark-ground");

  if (!next) return false;

  el.style.setProperty("--hsd-label-ink", next.ink);
  el.style.setProperty("--hsd-label-halo", next.halo);
  el.style.setProperty("--hsd-label-value-ink", next.valueInk);
  el.style.setProperty("--hsd-caption-ink", next.captionInk);
  return true;
}

/** Re-sync every live chart container (e.g. after gallery skin flips the painted ground). */
export function syncAllChartLabelContrast(root: ParentNode = document): void {
  for (const el of root.querySelectorAll<HTMLElement>(".hsd-container")) {
    syncLabelContrast(el);
  }
}
