/**
 * Flexible-string "shock absorber" micro-interaction (D10), extracted from the straight-mode SVG
 * renderer so ring mode can share the exact same physics rather than re-implementing it (per
 * user request: ring-mode strings should feel identical to straight mode's, not have their own
 * bespoke motion). Pure, DOM-free — a renderer owns a `StringChainAnim` per string and calls
 * `stepChainAnim` once per animation frame; everything here only ever produces numbers, never
 * touches the DOM.
 *
 * Modeled as a cheap N-node cascading chain rather than a rigid rotating rod — the anchor (top,
 * attached to the rail) only moves when explicitly dragged or when its target slot changes.
 * Whichever point along the string you grab becomes the "driver" (tracks the pointer 1:1); every
 * other node chases whichever neighbor is closer to the driver, so a flick propagates outward in
 * both directions with increasing delay/amplitude the farther a node is from the grab point.
 * The anchor itself is 2D (`anchorX`/`anchorY`) so a renderer whose attachment point moves along
 * a curve (ring mode's ellipse) can ease it in both axes; the chain nodes stay pure local-X
 * offsets in both renderers, since in both cases "down" is the local +Y direction after the
 * renderer's own transform is applied — only the inertial displacement driving the chain reacts
 * to X motion (in straight mode Y never moves at all, so this is a strict generalization, not a
 * behavior change there).
 *
 * PHASE-CORRECT INERTIA (2026-07-15 fix): anchor motion couples into the chain as an immediate
 * LOCAL DISPLACEMENT (a node with inertia holds its world position while the anchor moves under
 * it), not as a velocity impulse. The previous velocity-impulse coupling propagated so slowly
 * through the cascade that the visible swing arrived only after the anchor had stopped — and in
 * the TRAILING direction, which reads as exactly backwards ("swings the opposite as it would be
 * in reality", user report while spinning the ring's disc). With displacement coupling the
 * string trails immediately while its anchor accelerates, and the spring cascade produces the
 * real forward overshoot after the stop.
 */

import { isSettled, settle, stepSpring, type SpringState } from "./spring";

export const N_NODES = 3; // points along the string besides the anchor; the last one IS the knob
const ANCHOR_EASE_RATE = 20; // 1/s — how fast a non-dragged string's anchor catches up to its target
/** D25: the FASTEST chase rate a rail-mode morph glide uses (the first string in layout
 * order) — a ~280ms time constant, so even the quickest string's cross-geometry travel
 * visibly plays out, vs drag-follow's ~50ms snap. */
export const MORPH_ANCHOR_EASE_RATE = 3.6;

/** D25 sweep: the morph's per-string chase rate by layout-order fraction (0 = first string,
 * 1 = last). Later strings glide slower, so the transformation travels ACROSS the chart as a
 * visible left-to-right wave (first strings land ~0.9s, last ~1.6s) instead of everything
 * arriving in lockstep. */
export function morphAnchorEaseRate(orderT: number): number {
  return MORPH_ANCHOR_EASE_RATE - 1.7 * Math.min(1, Math.max(0, orderT));
}
const MAX_CHAIN_SHIFT_PX = 70; // per-frame clamp so a huge pointer jump can't fling the curve wild

// Hand-tuned feel at stiffness = 0.5 (the slider's default/midpoint). `stiffness` (0..1, user-
// adjustable) scales away from this point: stiffness/damping scale geometrically (by the same
// factor `k` for stiffness and `sqrt(k)` for damping) so the damping *ratio* — and hence the
// "bounciness" character of the motion — stays constant across the whole range; only the speed
// and amplitude change. At stiffness=0 the string is floppy (slow, big bow); at stiffness=1 it's
// close to a rigid rod (fast, barely any visible bow).
const TUNED_NEAR_PARAMS = { stiffness: 150, damping: 16 }; // for a node one hop from the driver
const TUNED_FAR_PARAMS = { stiffness: 55, damping: 7.5 }; // for nodes two+ hops from the driver
const STIFFNESS_RANGE = 4; // spring stiffness spans 4x softer .. 4x stiffer than the tuned point
const COUPLING_AT_FLEXIBLE = 0.9; // stiffness = 0: reacts a lot to anchor motion (floppy)
const COUPLING_AT_RIGID = 0.2; // stiffness = 1: reacts very little (rod-like)

// The knob is the one point in the chain that represents actual physical weight (the string
// itself is treated as massless — only the "metal weight" at the tip has inertia). A bigger
// knob (D7's second-metric encoding) gets a proportionally bigger `mass` fed into *its own*
// spring step: heavier = sluggish to catch up to the rest of the chain and slower to fully
// settle, like a real weight has more momentum than a light bead. Relative to the smallest
// knob currently on screen, not an absolute px value, so the effect scales with whatever data
// is loaded. Only applies while the knob is passively chasing its neighbor — while it's the
// point actually being dragged, it still tracks the pointer rigidly (see `driverIndex`).
const MASS_AT_MIN_KNOB_RADIUS = 1;
const MASS_AT_MAX_KNOB_RADIUS = 2.5;

// The label is treated as a small tag near the rail attachment — it gets its own light rotation
// wobble (degrees, added on top of D9's fixed tilt), kicked by the same anchor-motion impulse as
// the chain, but tuned snappier/lighter: bigger peak angle so it's clearly visible, but much
// faster settle (a light tag doesn't keep swinging anywhere near as long as the string+knob
// below it does). Reuses the impulse mechanism, not a shared spring, so it can have its own feel.
const TUNED_LABEL_PARAMS = { stiffness: 220, damping: 20 };
const LABEL_COUPLING_AT_FLEXIBLE = 4.5; // deg of impulse per px of anchor motion, floppy end
const LABEL_COUPLING_AT_RIGID = 1.5; // rigid end — still a little flutter, not zero
const MAX_LABEL_IMPULSE_DEG = 40;

export interface ChainParams {
  near: { stiffness: number; damping: number };
  far: { stiffness: number; damping: number };
  label: { stiffness: number; damping: number };
  coupling: number;
  labelCoupling: number;
}

export function chainParamsForStiffness(stiffness: number): ChainParams {
  const t = clamp(stiffness, 0, 1);
  const k = STIFFNESS_RANGE ** (2 * t - 1);
  const sqrtK = Math.sqrt(k);
  return {
    near: { stiffness: TUNED_NEAR_PARAMS.stiffness * k, damping: TUNED_NEAR_PARAMS.damping * sqrtK },
    far: { stiffness: TUNED_FAR_PARAMS.stiffness * k, damping: TUNED_FAR_PARAMS.damping * sqrtK },
    label: { stiffness: TUNED_LABEL_PARAMS.stiffness * k, damping: TUNED_LABEL_PARAMS.damping * sqrtK },
    coupling: lerp(COUPLING_AT_FLEXIBLE, COUPLING_AT_RIGID, t),
    labelCoupling: lerp(LABEL_COUPLING_AT_FLEXIBLE, LABEL_COUPLING_AT_RIGID, t),
  };
}

/** Spring params for a node `hop` steps away from whichever point is currently driving the chain.
 * `knobMass` (if given, applied only when this hop IS the knob node) makes a heavier knob react
 * more sluggishly, as if it carried real inertia. */
function paramsForHop(
  hop: number,
  chainParams: ChainParams,
  knobMass?: number
): { stiffness: number; damping: number; mass?: number } {
  const base = hop <= 1 ? chainParams.near : chainParams.far;
  return knobMass !== undefined ? { ...base, mass: knobMass } : base;
}

/** Maps a knob's radius to a physical "weight" for the spring — linear between the smallest and
 * largest knob currently on screen (min radius = baseline mass 1, unaffected). */
export function knobMassForRadius(radius: number, radiusMin: number, radiusMax: number): number {
  const t = radiusMax > radiusMin ? clamp((radius - radiusMin) / (radiusMax - radiusMin), 0, 1) : 0;
  return lerp(MASS_AT_MIN_KNOB_RADIUS, MASS_AT_MAX_KNOB_RADIUS, t);
}

/**
 * Which chain node (or the anchor, -1) sits closest to grab-depth fraction `t` (0 = rail,
 * 1 = knob). Node `i` (0-indexed) sits at depth fraction (i+1)/N_NODES, so the last node is
 * exactly at the knob.
 */
export function nearestNodeIndex(t: number): number {
  let best = -1;
  let bestDist = Math.abs(t - 0);
  for (let i = 0; i < N_NODES; i++) {
    const dist = Math.abs(t - (i + 1) / N_NODES);
    if (dist < bestDist) {
      bestDist = dist;
      best = i;
    }
  }
  return best;
}

export interface StringChainAnim {
  anchorX: number;
  anchorY: number;
  targetX: number;
  targetY: number;
  /** Horizontal offsets (px, local coords) of points along the string; nodes[N_NODES-1] = knob. */
  nodes: SpringState[];
  /** Which point is being actively dragged: -1 = anchor (rail), 0..N_NODES-1 = a node/the knob. */
  grabbedIndex: number;
  /** Extra rotation (deg) on top of a renderer's own fixed label tilt — a light "tag flutter" echo. */
  labelRot: SpringState;
  /** D25 (rail-mode morph): temporary anchor chase rate (1/s) replacing ANCHOR_EASE_RATE — a
   * seeded cross-geometry glide wants a visibly slower travel than drag-follow's snap.
   * Self-clears once the anchor arrives, so later interactions get normal snappiness. */
  anchorEaseRate?: number;
}

export function createChainAnim(x: number, y: number): StringChainAnim {
  return {
    anchorX: x,
    anchorY: y,
    targetX: x,
    targetY: y,
    nodes: Array.from({ length: N_NODES }, () => settle(0)),
    grabbedIndex: -1,
    labelRot: settle(0),
  };
}

export interface StepChainInput {
  /** True while this exact string is the live pointer drag. */
  isDraggingThis: boolean;
  stiffness: number;
  /** Precomputed `chainParamsForStiffness(stiffness)` — pass it when stepping many strings in
   * one frame so the (pow/sqrt) derivation runs once per frame, not once per string. Falls back
   * to deriving from `stiffness` when omitted. */
  chainParams?: ChainParams;
  knobRadius: number;
  radiusMin: number;
  radiusMax: number;
  dt: number;
  /** D21.2: lateral wind acceleration (px/s²) the breeze applies to this string this frame —
   * a gentle external force on the chain nodes (scaled toward the free end, like the
   * displacement coupling), so breeze sway rides the SAME spring physics as every other
   * motion and composes naturally with drags and swings. Omit/0 = still air. */
  windAccelPx?: number;
}

export interface StepChainResult {
  /** True once the anchor, every chain node, and the label rotation are all at rest. */
  settled: boolean;
}

/**
 * Advances `anim` by one frame **in place** (mutates the object passed in — the caller keeps
 * whatever Map/identity it already uses to store anim state per string id) and reports whether
 * everything has settled. Mirrors the original straight-mode `tick()` loop body, generalized so
 * the anchor can ease in Y as well as X (ring mode's attachment point moves along an ellipse;
 * straight mode's `targetY` is simply always equal to `anchorY`, so this is a no-op there).
 */
export function stepChainAnim(anim: StringChainAnim, input: StepChainInput): StepChainResult {
  const chainParams = input.chainParams ?? chainParamsForStiffness(input.stiffness);
  const knobMass = knobMassForRadius(input.knobRadius, input.radiusMin, input.radiusMax);
  const driverIndex = input.isDraggingThis ? anim.grabbedIndex : -1;
  const anchorIsDriver = driverIndex === -1;

  const prevAnchorX = anim.anchorX;
  if (input.isDraggingThis && anchorIsDriver) {
    anim.anchorX = anim.targetX; // rigid 1:1 follow while the rail point itself is grabbed
    anim.anchorY = anim.targetY;
    anim.anchorEaseRate = undefined; // grabbing overrides any morph glide outright
  } else {
    const ease = Math.min(1, (anim.anchorEaseRate ?? ANCHOR_EASE_RATE) * input.dt);
    anim.anchorX += (anim.targetX - anim.anchorX) * ease;
    anim.anchorY += (anim.targetY - anim.anchorY) * ease;
    if (
      anim.anchorEaseRate !== undefined &&
      Math.abs(anim.targetX - anim.anchorX) < 1 &&
      Math.abs(anim.targetY - anim.anchorY) < 1
    ) {
      anim.anchorEaseRate = undefined; // arrived — restore normal chase for what comes next
    }
  }
  const deltaAnchor = anim.anchorX - prevAnchorX;

  // The label tag lives right at the anchor and always gets a little flutter from however fast
  // the anchor itself is currently moving horizontally — independent of which node is being
  // dragged, since a real tag would flutter whether you tugged the string at the top or lower.
  const labelImpulse = clamp(
    -deltaAnchor * chainParams.labelCoupling,
    -MAX_LABEL_IMPULSE_DEG,
    MAX_LABEL_IMPULSE_DEG
  );
  anim.labelRot = stepSpring(
    { value: anim.labelRot.value, velocity: anim.labelRot.velocity + labelImpulse },
    0,
    chainParams.label,
    input.dt
  );

  // D21.2: the breeze pushes every free node sideways (the pinned drag driver excepted) —
  // tip feels the most, exactly like the inertial displacement scaling. A steady breeze
  // leans the thread slightly; the gust CHANGES are what make it visibly flutter.
  if (input.windAccelPx) {
    for (let i = 0; i < N_NODES; i++) {
      if (input.isDraggingThis && i === driverIndex) continue;
      anim.nodes[i].velocity += input.windAccelPx * ((i + 1) / N_NODES) * input.dt;
    }
  }

  if (input.isDraggingThis && !anchorIsDriver) {
    // Rigidly pin whichever node was actually grabbed to the pointer (in local coords) —
    // recomputed every frame so it stays under the pointer even while the anchor itself is
    // still easing toward its own target underneath it.
    anim.nodes[driverIndex] = { value: anim.targetX - anim.anchorX, velocity: 0 };
  }

  if (anchorIsDriver) {
    // Cascading chain, driven from the top. INERTIA IS A DISPLACEMENT, NOT A VELOCITY KICK
    // (user bug report, 2026-07-15: strings appeared to "swing the opposite as reality" when
    // the ring was spun — the old velocity-impulse coupling made the visible swing arrive only
    // AFTER the disc had stopped, still in the trailing direction; reality is an immediate
    // backward trail WHILE turning, then a forward overshoot after the stop): a node's inertia
    // means it holds its WORLD position while the anchor moves, so in the anchor-local frame
    // it must shift by −Δ the instant the anchor moves by Δ. `coupling` keeps the string from
    // being perfectly inertial (a stiffer string drags its tail along), and the fraction grows
    // toward the tip — the free end lags most, the top follows the rail almost rigidly. The
    // spring cascade below then plays the recovery: node0 springs back to rest and each later
    // node chases the *previous* node's current position (a moving target), which produces the
    // lagging, overshooting follow-through ("whip") on the way back to plumb.
    const shift = clamp(deltaAnchor, -MAX_CHAIN_SHIFT_PX, MAX_CHAIN_SHIFT_PX);
    if (shift !== 0) {
      for (let i = 0; i < N_NODES; i++) {
        anim.nodes[i].value -= shift * chainParams.coupling * ((i + 1) / N_NODES);
      }
    }
    anim.nodes[0] = stepSpring(
      anim.nodes[0],
      0,
      paramsForHop(1, chainParams, 0 === N_NODES - 1 ? knobMass : undefined),
      input.dt
    );
    for (let i = 1; i < N_NODES; i++) {
      const params = paramsForHop(i, chainParams, i === N_NODES - 1 ? knobMass : undefined);
      anim.nodes[i] = stepSpring(anim.nodes[i], anim.nodes[i - 1].value, params, input.dt);
    }
  } else {
    // Cascading chain, driven from wherever the string was actually grabbed: propagate outward
    // toward the anchor side and the knob side independently, each node chasing whichever
    // neighbor is closer to the driver, so a mid-string grab produces symmetric lag/overshoot on
    // both sides, and farther nodes react less (via the hop>=2 "far" params).
    for (let i = driverIndex - 1; i >= 0; i--) {
      const hop = driverIndex - i;
      const params = paramsForHop(hop, chainParams, i === N_NODES - 1 ? knobMass : undefined);
      anim.nodes[i] = stepSpring(anim.nodes[i], anim.nodes[i + 1].value, params, input.dt);
    }
    for (let i = driverIndex + 1; i < N_NODES; i++) {
      const hop = i - driverIndex;
      const params = paramsForHop(hop, chainParams, i === N_NODES - 1 ? knobMass : undefined);
      anim.nodes[i] = stepSpring(anim.nodes[i], anim.nodes[i - 1].value, params, input.dt);
    }
  }

  const anchorSettled =
    Math.abs(anim.anchorX - anim.targetX) < 0.05 && Math.abs(anim.anchorY - anim.targetY) < 0.05;
  const chainSettled = anim.nodes.every((n) => isSettled(n, 0));
  const labelSettled = isSettled(anim.labelRot, 0);
  const settled = anchorSettled && chainSettled && labelSettled;
  if (settled && !input.isDraggingThis) {
    anim.anchorX = anim.targetX;
    anim.anchorY = anim.targetY;
    anim.nodes = anim.nodes.map(() => settle(0));
    anim.labelRot = settle(0);
  }

  return { settled: settled && !input.isDraggingThis };
}

export interface Point {
  x: number;
  y: number;
}

/**
 * SVG path through `points[0]` (exact) .. `points[n]` (exact), smoothed by using every interior
 * point as a quadratic control point (the standard "smooth polyline" trick — each segment but
 * the last ends at the midpoint to the next point; the last ends exactly at the final point so
 * the knob is always rendered at its true position, never a smoothed offset).
 */
export function smoothPathThroughPoints(points: Point[]): string {
  const n = points.length - 1;
  if (n < 1) return `M${points[0]?.x ?? 0},${points[0]?.y ?? 0}`;
  let d = `M${points[0].x},${points[0].y}`;
  if (n === 1) {
    return `${d} L${points[1].x},${points[1].y}`;
  }
  for (let i = 1; i <= n - 1; i++) {
    const p = points[i];
    const end = i === n - 1 ? points[n] : { x: (p.x + points[i + 1].x) / 2, y: (p.y + points[i + 1].y) / 2 };
    d += ` Q${p.x},${p.y} ${end.x},${end.y}`;
  }
  return d;
}

/** Approximate X at height `ty` by walking the polyline through `points` (anchor..knob). Cheap
 * cosmetic placement for tick marks — the real thread is the smoothed curve, but ticks sitting a
 * shade off it (vs. exactly on it) is imperceptible at bead-tick size. */
export function xAlongPolyline(points: Point[], ty: number): number {
  for (let i = 0; i < points.length - 1; i++) {
    const a = points[i];
    const b = points[i + 1];
    if (ty <= b.y || i === points.length - 2) {
      const span = b.y - a.y;
      const t = span > 0 ? clamp((ty - a.y) / span, 0, 1) : 0;
      return lerp(a.x, b.x, t);
    }
  }
  return points[points.length - 1].x;
}

export function clamp(v: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, v));
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}
